(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.9"]={"from":216,"a":[["\u0003ואם היה זקן או חולה\u0004 שקשה לו לעבוד בעצמו, ואף אינו יכול לאכול ממנה — \u0003נותנה\u0004 להקרבה \u0003לכל כהן שירצה\u0004 ואף שאינו באותו משמר, \u0003ועבודתה ועורה לאנשי משמר.\u0004","ומבררים: \u0003האי\u0004 \u0005[זה]\u0006 אותו \u0003זקן או חולה, היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אי דמצי עביד\u0004 \u0005[אם ש\u0006הוא \u0005יכול לעשות]\u0006 \u0003עבודה\u0004 של הקרבה — \u0003עבודתה ועורה נמי תיהוי דידיה\u0004 \u0005[גם כן יהיו שלו],\u0006 \u0003ואי דלא מצי עביד\u0004 \u0005[ואם שאינו יכול לעשות]\u0006 \u0003עבודה\u0004 — \u0003שליח היכי משוי\u0004 \u0005[איך יכול למנות],\u0006 שאמרה הברייתא שנותנה לכל כהן שירצה? ולכאורה הכל צריך להיות שייך לכהנים שבאותו משמר!","\u0003אמר רב פפא:\u0004 מדובר כאן \u0003שיכול לעשות\u0004 עבודה \u0003על ידי הדחק,\u0004 ולכן: \u0003עבודה דכי עביד ליה\u0004 \u0005[שכאשר עושה הוא]\u0006 \u0003על ידי הדחק\u0004 בכל אופן נחשבת \u0003עבודה היא, ו\u0004משום כך \u0003משוי\u0004 \u0005[ממנה]\u0006 \u0003שליח\u0004 לצורך זה, אבל \u0003אכילה\u0004 אין דינה כן, משום \u0003דכי אכיל\u0004 \u0005[שכאשר אוכל]\u0006 \u0003על ידי הדחק אכילה גסה היא,\u0004 כלומר, הריהי אכילה שאינה נקראת אכילה ראויה, \u0003ואכילה גסה לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא,\u0004 ו\u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003עבודתה ועורה לאנשי משמר.\u0004","ובענין דומה \u0003אמר רב ששת: אם היה כהן טמא\u0004 במשמר שזכה \u0003בקרבן צבור\u0004 להקריבו — הריהו \u0003נותנה\u0004 את בהמת הקרבן \u0003לכל מי שירצה\u0004 מבין אנשי המשמר, \u0003ועבודתה ועורה לאנשי משמר.\u0004 ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003אי דאיכא\u0004 \u0005[אם שיש]\u0006 כהנים \u0003טהורים\u0004 במקום, \u0003טמאים מי מצו עבדי\u0004 \u0005[האם\u0006 הם \u0005יכולים לעשות]\u0006 את עבודת ההקרבה ואף לא למנות שליח על כך? \u0003ואי דליכא\u0004 \u0005[ואם שאין]\u0006 \u0003טהורים\u0004 אלא כולם טמאים, הרי אף שקרבן ציבור קרב במקרה כזה מדוע \u0003עבודתה\u0004 (בשרה) \u0003ועורה לאנשי משמר? הא\u0004 \u0005[הרי]\u0006 \u0003טמאים נינהו\u0004 \u0005[הם]\u0006 \u0003ו\u0004אף שיכולים הם להקריבו הרי הם \u0003לא מצו אכלי\u0004 \u0005[יכולים לאכול]!\u0006","\u0003אמר רבא,\u0004 מדובר באופן שכל הכהנים הראויים לעבודה טמאים, ובאשר לבשרה ועורה \u0003אימא\u0004 \u0005[אמור]\u0006 כך: אלו יינתנו \u0003לבעלי מומין טהורין שבאותו משמר,\u0004 שאף על פי שאין כהנים בעלי מומים רשאים לעבוד ולכן נעשית ההקרבה בכהנים טמאים, מכל מקום יכולים כהנים בעלי מומים לאכול בטהרה.","ובענין דומה \u0003אמר רב אשי: אם היה כהן גדול אונן\u0004 (ביום הראשון לאבלו, שמת אחד מקרוביו) ויש לו בהמת קרבן להקריב לעצמו — \u0003נותנה\u0004 להקרבה \u0003לכל כהן שירצה, ועבודתה ועורה לאנשי משמר.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב אשי בכך? הלא \u0003תנינא\u0004 \u0005[שנינו כבר]:\u0006 \u0003כהן גדול מקריב\u0004 קרבנות כאשר הוא \u0003אונן, ואינו אוכל\u0004 בעודו אונן, \u0003ואינו חולק\u0004 בקודשים \u0003לאכול לערב,\u0004 ומשום שמקריב בעצמו — יכול ליתנו לכהן אחר, ומשום שאינו יכול לאכול — אם כן אין לו זכות באכילה.","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003כי חס רחמנא עליה\u0004 \u0005[כאשר חסה התורה עליו]\u0006 על \u0003כהן גדול\u0004 והרשתה לו לעבוד בעודו אונן — \u0003לקרובי\u0004 \u0005[להקריב]\u0006 \u0003הוא\u0004 בעצמו, \u0003אבל לשוויי\u0004 \u0005[למנות]\u0006 \u0003שליח לא מצי משוי\u0004 \u0005[אינו יכול למנות],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו שליח הוא יכול למנות, כיון שהוא עצמו מותר לו לעבוד עבודה.","\u0003הגוזל את הגר ונשבע לו\u0004 שלא גזלו \u0003ומת\u0004 הגר, ורוצה הגזלן לעשות תשובה — \u0003הרי זה משלם קרן\u0004 הגזילה עצמה (או שוויה, אם איננה) \u0003וחומש לכהנים ו\u0004מביא איל כקרבן \u0003אשם למזבח, שנאמר: \"ואם אין לאיש גואל להשיב האשם אליו האשם המושב לה' לכהן מלבד איל הכפרים אשר יכפר בו עליו\"\u0004 (במדבר ה, ח).","\u0003היה מעלה\u0004 לירושלים \u0003את הכסף\u0004 לשלם לכהנים \u0003ואת האשם\u0004 להקריבו, \u0003ומת\u0004 הגזלן לפני שניתן הכסף והוקרב הקרבן — \u0003הכסף ינתן לבניו\u0004 של הגזלן, \u0003ו\u0004איל \u0003האשם ירעה עד שיסתאב\u0004 (שיפול בו מום), \u0003ו\u0004אז \u0003ימכר ויפלו דמיו לנדבה,\u0004 כלומר, להקרבת עולות על המזבח. ואם כבר \u0003נתן\u0004 את \u0003הכסף לאנשי משמר ומת\u0004 הגזלן קודם שהקריבו את אשמו — \u0003אין היורשין יכולין להוציא\u0004 את הכסף \u0003מידם, שנאמר: \"ואיש אשר יתן לכהן לו יהיה\"\u0004 (במדבר ה, י).","\u0003נתן\u0004 את \u0003הכסף ל\u0004משמר הכהונה \u0003יהויריב, ו\u0004את ה\u0003אשם\u0004 נתן להקריב \u0003ל\u0004משמר \u0003ידעיה,\u0004 שהוא המשמר שאחריו — \u0003יצא.\u0004 אבל אם נתן תחילה את ה\u0003אשם ל\u0004משמר \u0003יהויריב ו\u0004את ה\u0003כסף\u0004 נתן \u0003ל\u0004משמר \u0003ידעיה, אם קיים האשם\u0004 עדיין — \u0003יקריבוהו בני ידעיה,\u0004 אלה שקיבלו את הכסף, \u0003ואם לא\u0004 קיים האשם, שכבר הקריבוהו בני יהויריב קודם — \u0003יחזיר ויביא\u0004 קרבן \u0003אשם אחר, שהמביא\u0004 כסף \u0003גזילו עד שלא הביא\u0004 (לפני שהביא) \u0003אשמו\u0004 — \u0003יצא,\u0004 אבל אם \u0003הביא אשמו עד שלא הביא\u0004 כסף \u0003גזילו\u0004 — \u0003לא יצא.\u0004","ובהבאת הכסף עצמו, אם \u0003נתן את הקרן ולא נתן את החומש\u0004 — \u0003אין החומש מעכב\u0004 לענין קרבן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על הפסוק \"ואם אין לאיש גואל... האשם המושב לה' לכהן\": \u0003\"אשם\"\u0004 — \u0003זה קרן,\u0004 כלומר, הגזילה עצמה (או תמורתה), \u0003\"המושב\"\u0004 — \u0003זה חומש. או אינו אלא\u0004 פירוש אחר: \u0003\"אשם\"\u0004 — \u0003זה איל\u0004 של קרבן האשם?","ועוד לפני שמביאים את המשך הברייתא בפתרון השאלה מבררת הגמרא אותה: \u0003ולמאי נפקא מינה\u0004 \u0005[ומה\u0006 הבדל \u0005יוצא מזה]\u0006 אם כך או כך הוא פירוש הפסוק, והרי בין כה וכה צריך להביא את שניהם, את הקרן ואת איל האשם? ומשיבים: שאם אומרים ש\"האשם\" האמור בכתוב הוא האיל הרי זה בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: גזל הגר שהחזירו בלילה\u0004 — \u0003לא יצא,\u0004 וכן אם \u0003החזירו חצאין\u0004 — \u0003לא יצא, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003\"אשם\" קרייה רחמנא\u0004 \u0005[קראה אותו התורה]\u0006 לגזל, ודינו כדין אשם שאינו קרב באופנים אלה, ומשום כך היה צריך להדגיש שאשם זהו הקרבן ולא הקרן.","וממשיכה הברייתא בפתרון השאלה: \u0003כשהוא אומר \"מלבד איל הכפרים\"\u0004 שהוא הקרבן, \u0003הוי אומר: \"אשם\"\u0004 — \u0003זה קרן.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"\u0004\u0003אשם\"\u0004 — \u0003זה קרן, \"המושב\"\u0004 — \u0003זה חומש. או אינו אלא\u0004 פירוש אחר: \u0003\"אשם\"\u0004 — \u0003זה חומש?\u0004 ואף כאן מבררת הגמרא: \u0003למאי נפקא מינה\u0004 \u0005[מה\u0006 הבדל \u0005יוצא מזה]\u0006 אם כך או כך הוא? \u0003לאפוקי ממתניתין\u0004 \u0005[להוציא ממשנתנו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003נתן לו את הקרן ולא נתן לו את החומש\u0004 — \u0003אין החומש מעכב,\u0004 ואם נפרש ש\"אשם\" הוא חומש, יוצא ש\u0003אדרבה\u0004 (להיפך), \u0003חומש מעכב.\u0004","וממשיכה הברייתא: \u0003כשהוא אומר: \"והשיב את אשמו בראשו וחמישתו\"\u0004 (במדבר ה ז), ואם כן נזכר החומש במפורש — \u0003הוי אומר: \"אשם\"\u0004 — \u0003זה קרן\u0004 ולא החומש.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"אשם\"\u0004 — \u0003זה קרן, \"המושב\"\u0004 — \u0003זה חומש, ובגזל הגר הכתוב מדבר. או אינו אלא\u0004 פירוש אחר: \u0003\"המושב\"\u0004 — \u0003זה כפל, ובגניבת הגר הכתוב מדבר? כשהוא אומר: \"והשיב את אשמו בראשו וחמישתו\", הרי בממון המשתלם בראש,\u0004 כלומר, שמשלם רק את הקרן \u0003הכתוב מדבר,\u0004 ולא בכפל.","כיון שהזכרנו את דברי רבא באים עתה לדון בהם \u0003גופא\u0004 \u0005[לגופם].\u0006 \u0003אמר רבא: גזל הגר שהחזירו בלילה\u0004 — \u0003לא יצא, החזירוהו חצאין\u0004 — \u0003לא יצא. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003\"אשם\" קרייה רחמנא\u0004 \u0005[קראה אותו התורה]\u0006 ודינו כדין הקרבן שאינו יכול לבוא לא בלילה ולא לחצאין.","\u0003ואמר רבא: גזל הגר שאין בו שוה פרוטה לכל כהן וכהן\u0004 שבמשמר — \u0003לא יצא ידי חובתו. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"האשם המושב\",\u0004 לומר: \u0003עד שיהא השבה לכל כהן וכהן.\u0004 שלכל כהן צריך להיות דבר מה הניתן לו שיש בו דין ממון, שהוא פרוטה לפחות. ואם היה הגזל פחות מזה צריך להשלים עד שיהיה לכל כהן פרוטה אחת.","על סמך דברים אלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם \u0003אין בו\u0004 בגזל כדי לחלק \u0003ל\u0004כל \u0003משמרת יהויריב\u0004 הגדולה, \u0003ו\u0004אולם \u0003יש בו\u0004"],["\u0003למשמרת ידעיה\u0004 שהיא קטנה ממנה, ויש בגזל כדי שווה פרוטה לכל כהן, \u0003מהו\u0004 הדין?","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דיהביה\u0004 \u0005[אם תאמר שנתן אותו,\u0006 את הכסף\u0005]\u0006 \u0003ל\u0004משמרת \u0003ידעיה במשמרת ידעיה,\u0004 בזמן שהם היו במשמרתם — \u0003הא אית ביה\u0004 \u0005[הרי יש בו]\u0006 כסף כדי לשלם כראוי לכל כהן!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003דיהביה\u0004 \u0005[שנתן אותו]\u0006 \u0003לידעיה במשמרתו\u0004 של \u0003יהויריב, מאי\u0004 \u0005[מה]\u0006 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003משמרתו\u0004 של ידעיה \u0003הוא, ולא כלום הוא,\u0004 כלומר, אין זו נחשבת השבה כלל, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא חזי ליה\u0004 \u0005[ראוי לו]\u0006 למשמרת יהויריב \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 שאינו ראוי להתחלק ביניהם, אם כן \u0003ל\u0004משמרת \u0003ידעיה קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 שהם יכולים לקבל אותו, ונמצא שקיים בכך השבה. שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה\u0005.\u0006","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: כהנים, מהו שיחלקו\u0004 ביניהם \u0003גזל הגר כנגד גזל הגר\u0004, שיסכימו שאחד (או קבוצה) מהם תקבל בשלימות גזל גר אחד, וקבוצה אחרת תקבל בשלימות גזל גר שני?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 ש\u0003\"אשם\" קרייה רחמנא\u0004 \u0005[קראה לו התורה],\u0006 ולכן \u0003מה אשם אין חולקין אשם כנגד אשם,\u0004 אלא כל הכהנים מתחלקים בבשר הקרבן, ואינם יכולים להסכים ביניהם שכל אחד יאכל קרבן אשם בשלימות, וחבירו יאכל קרבן אשם אחר — \u0003אף גזל\u0004 הגר \u0003אין חולקין גזל הגר כנגד גזל הגר. או דלמא\u0004 \u0005[שמא]\u0006 \u0003גזל הגר\u0004 הניתן לכהנים \u0003ממונא\u0004 \u0005[ממון]\u0006 \u0003הוא\u0004 וממונות יכולים הם לחלק ביניהם?!","\u0003הדר פשטה\u0004 \u0005[חזר\u0006 רבא ו\u0005פתר\u0006 בעצמו\u0005]\u0006 את הבעיה: \u0003\"אשם\" קרייה רחמנא\u0004 \u0005[קראה לו התורה].\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מתני לה בהדיא\u0004 \u0005[היה שונה אותה במישרין\u0006 ולא כשאלה ותשובה\u0005]\u0006 וכך היה אומר, \u0003אמר רבא: כהנים אין חולקין גזל הגר כנגד גזל הגר, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003\"אשם\" קרייה רחמנא\u0004 \u0005[קראה לו התורה].\u0006","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 באותו נושא: \u0003כהנים בגזל הגר\u0004 מהו דינם, האם כ\u0003יורשין\u0004 של כסף הגר \u0003הוו\u0004 \u0005[הם]\u0006 נחשבים, \u0003או מקבלי מתנות הוו\u0004 \u0005[הם]\u0006 נחשבים?","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה\u0006 הבדל למעשה \u0005יוצא מזה],\u0006 אם כך או כך דינם? ומשיבים: \u0003כגון שגזל\u0004 מן הגר \u0003חמץ שעבר עליו הפסח\u0004 והוא אסור בהנאה, ואין בו ערך ממוני כלל, וזו השאלה: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003יורשין הוו\u0004 \u0005[הם],\u0006 \u0003היינו האי דירתי מורית\u0004 \u0005[זהו מה ש\u0006הם \u0005יורשים מוריש]\u0006 להם הגזלן כאשר נותן להם את החמץ, והם מקבלים את החמץ בעינו. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003מקבלי מתנות הוו\u0004 \u0005[הם],\u0006 \u0003מתנה קאמר רחמנא דניתיב להו\u0004 \u0005[אמרה התורה שיתן להם],\u0006 \u0003והא לא קא יהיב להו מידי\u0004 \u0005[והרי אינו נותן להם דבר],\u0006 \u0003דעפרא בעלמא\u0004 \u0005[שעפר סתם]\u0006 \u0003הוא.\u0004 ואם כן חייב הגזלן לשלם להם את דמי החמץ כפי שגזלו.","\u0003רב זעירא בעי הכי\u0004 \u0005[שאל כך]:\u0006 \u0003אפילו אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003מקבלי מתנה הוו\u0004 \u0005[הם],\u0006 \u0003הא\u0004 \u0005[זה],\u0006 בגזילת חמץ שעבר עליו הפסח \u0003לא איבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שיוצא בזה ידי חובתו, שהגזילה \u0003ההיא\u0004 היא אותה ה\u0003מתנה\u0004 שעליה \u0003אמר רחמנא דניתיב להו\u0004 \u0005[אמרה התורה שיתן להם].\u0006","\u0003אלא כי קמבעיא לן\u0004 \u0005[כאשר נשאלה לנו\u0006 שאלה זו\u0005]\u0006 אם יורשים הם או מקבלי מתנה, הרי זה \u0003כגון שנפלו לו\u0004 לכהן \u0003עשר בהמות בגזל הגר,\u0004 האם \u0003מחייבי לאפרושי מינייהו\u0004 \u0005[מחוייבים\u0006 הם \u0005להפריש מהן]\u0006 \u0003מעשר\u0004 בהמה, \u0003או לא?\u0004","וצדדי השאלה: האם \u0003יורשין הוו\u0004 \u0005[הם],\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה שהיורשים אם \u0003קנו בתפיסת הבית\u0004, כלומר, כשהירושה כולה של כולם, ולא חילקו אותה ביניהם, ונולדו להם בהמות במשך השנה — \u0003חייבין\u0004 במעשר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מקבלי מתנות הוו\u0004 \u0005[הם],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003הלוקח\u0004 (קונה) בהמות \u0003והניתן לו במתנה\u0004 — \u0003פטור ממעשר בהמה,\u0004 ואם כן, השאלה היא \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין בענין זה?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא: \u0003עשרים וארבע מתנות כהונה ניתנו לאהרן ולבניו, וכולן ניתנו,\u0004 כלומר, נאמרו בתורה \u0003ב\u0004לשון שיש בה \u0003כלל\u0004 כאמור: \"וידבר ה' אל אהרן ואני הנה נתתי לך את משמרת תרומותי לכל קדשי בני ישראל לך נתתים למשחה ולבניך לחק עולם\" (במדבר יח, ח), \u0003ופרט\u0004 שנתפרטו רוב מתנות כהונה מאותו פסוק והלאה (במדבר ה ט–יח), \u0003וכלל\u0004 כאמור שם בגוף הענין: \"כל תרומות הקדשים אשר ירימו בני ישראל לה' נתתי לך ולבניך ולבנותיך אתך לחק עולם\" (במדבר ה יט), \u0003וברית מלח\u0004 כפי שנאמר בהמשך אותו פסוק \"ברית מלח עולם היא\".","ללמדנו ש\u0003כל המקיימן\u0004 — \u0003כאילו מקיים כלל ופרט וכלל וברית מלח,\u0004 ו\u0003כל העובר עליהם\u0004 — \u0003כאילו עובר על כלל ופרט וכלל וברית מלח.\u0004","\u0003ואלו הן\u0004 עשרים וארבע המתנות: \u0003עשר במקדש\u0004 שנותנים אותן ואוכלים אותן רק במקדש עצמו, \u0003וארבע ב\u0004כל \u0003ירושלים, ועשר בגבולים\u0004 (בכל ערי ארץ ישראל). ומפרטים, \u0003עשר במקדש\u0004 והן: \u0003חטאת בהמה, וחטאת העוף, ואשם ודאי, ואשם תלוי, וזבחי שלמי צבור\u0004 (כבשי שלמים המוקרבים בחג השבועות), \u0003ולוג שמן של מצורע,\u0004 ששמים מקצת ממנו על בהונותיו, \u0003ומותר העומר,\u0004 מה שאין מקריבים על המזבח, \u0003ו\u0004מותר \u0003שתי הלחם\u0004 של שבועות, \u0003ולחם הפנים, ושירי מנחות\u0004 אחר שהקריבו את הקומץ.","\u0003וארבע\u0004 מתנות ניתנו להם \u0003בירושלים,\u0004 ואלו הם: \u0003הבכורה\u0004 (בכור בהמה טהורה), \u0003והביכורים, והמורם מן התודה\u0004 \u0003ואיל נזיר\u0004 אותו חלק שנותנים לכהנים, \u0003ועורות קדשים.\u0004","\u0003ועשרה בגבולין\u0004 והן: \u0003תרומה, ותרומת מעשר\u0004 שמפריש הלוי מן המעשר הראשון שקיבל, \u0003וחלה, וראשית הגז, והמתנות\u0004 (זרוע, לחיים וקיבה מכל בהמת חולין), \u0003ופדיון הבן, ופדיון פטר חמור, ושדה אחוזה, ושדה חרמים, וגזל הגר.\u0004 עד כאן לשון הברייתא.","ומדייקים: \u0003וקא קרי מיהת\u0004 \u0005[ו\u0006הריהו \u0005קורא על כל פנים]\u0006 גם לגזל הגר \u0003\"מתנה\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003מקבלי מתנות הוו\u0004 \u0005[הם]\u0006 הכהנים בגזל הגר, ולא יורשים, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003נתן\u0004 הגוזל מן הגר \u0003את הכסף לאנשי משמר\u0004 ומת קודם שקרב אשמו — אין יורשיו יכולים להוציא את הכסף מידם. \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003כסף\u0004 גזילה שמושב לנגזל \u0003מכפר מחצה. דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 \u0003מכפר\u0004 כלל, ורק עם הבאת האשם מתכפר לו, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שבגזל הגר, אם לא קרב אשמו \u0003מהדר\u0004 \u0005[מחזיר]\u0006 הכהן את הכסף \u0003ליורשין, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — משום \u0003אדעתא דהכי\u0004 \u0005[על דעת כך]\u0006 שלא יתכפר \u0003לא יהב ליה\u0004 \u0005[נתן לו\u0006 לכהן\u0005],\u0006 והרי זה כמיקח טעות.","ותוהים: \u0003אלא מעתה\u0004 לפי סברה זו, \u0003חטאת שמתו בעליה\u0004 ואין מקריבים אותה עוד, \u0003תיפוק\u0004 \u0005[תצא]\u0006 \u0003לחולין, דאדעתא דהכי\u0004 \u0005[שעל דעת כך]\u0006 שלא יתכפר בה \u0003לא אפרשה\u0004 \u0005[הפריש אותה]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003חטאת שמתו בעליה, הלכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני אנו \u0005למודים בה]\u0006 ש\u0003למיתה אזלא\u0004 \u0005[\u0006היא \u0005הולכת].\u0006","ומקשים: \u0003אלא מעתה, אשם שמתו בעליו ליפוק\u0004 \u0005[שייצא]\u0006 \u0003לחולין,\u0004 ודינו שאינו קרב עוד, \u0003דאדעתא דהכי\u0004 \u0005[שעל דעת כן]\u0006 \u0003לא אפרשיה\u0004 \u0005[הפריש אותו]!\u0006 ומשיבים: \u0003אשם נמי\u0004 \u0005[גם כן]\u0006 \u0003הלכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני אנו \u0005למודים בה]:\u0006 \u0003כל שבחטאת מתה,\u0004 כלומר, כל קרבן שהיה פסול בבעליו או בעבודתו, שבשבילו צריך להמית בהמת חטאת אם היה בה פסול זה, ובכלל זה שמתו בעליו, כגון זה \u0003ב\u0004קרבן \u0003אשם\u0004 שנפל בו פסול כזה — \u0003רועה\u0004 עד שיפול בו מום וייפדה.","ושואלים: \u0003אלא מעתה, יבמה שנפלה\u0004 ליבום \u0003לפני מוכה שחין תיפוק\u0004 \u0005[תצא]\u0006 \u0003בלא חליצה, דאדעתא דהכי\u0004 \u0005[שעל דעת כן]\u0006 שתצטרך להתייבם לאדם כזה \u0003לא קדשה עצמה\u0004 לאחיו שמת! ומשיבים: \u0003התם אנן סהדי\u0004 \u0005[שם אנו עדים]\u0006 כלומר, הכל יודעים,"],["\u0003דמינח ניחא\u0004 \u0005[שנוח]\u0006 \u0003לה בכל דהו\u0004 \u0005[שהוא]\u0006 ואף אם היתה יודעת שאולי תיזקק לאותו יבם היתה מתקדשת. \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש\u0004 ככלל, שגור הוא בפי הנשים לומר: \u0003טב למיתב טן דו מלמיתב ארמלו\u0004 \u0005[טוב לשבת בשניים,\u0006 כלומר, בנישואין \u0005מלשבת אלמנה],\u0006 שעדיף לאשה להיות עם גבר כלשהו מאשר להיות בבדידות.","שנינו במשנה: \u0003נתן את הכסף ל\u0004משמרת \u0003יהויריב\u0004 ואת האשם למשמרת ידעיה שאחריה, יצא. ואם נתן אשם למשמרת יהויריב וכסף למשמרת ידעיה, אם קיים האשם — יקריבוהו בני ידעיה, ואם לא — יחזור ויביא אשם אחר. ומביאים מחלוקת תנאים בענין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נתן אשם ל\u0004משמרת \u0003יהויריב וכסף ל\u0004משמרת \u0003ידעיה\u0004 — \u0003יחזיר כסף אצל אשם,\u0004 למשמרת שנתן לה את האשם, כלומר, למשמרת יהויריב, אלו \u0003דברי ר' יהודה. וחכמים אומרים:\u0004 להיפך, \u0003יחזיר אשם אצל כסף,\u0004 ובני ידעיה יקריבו את האשם.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דיהיב ליה\u0004 \u0005[שנתן לו]\u0006 \u0003אשם ליהויריב במשמרתו\u0004 של \u0003יהויריב,\u0004 בזמן שהיה יהויריב במשמרתו, \u0003וכסף לידעיה במשמרתו\u0004 של \u0003ידעיה,\u0004 אם כן \u0003זה זכה בשלו וזה זכה בשלו!\u0004 ומדוע יוציאו מהם את מה שזכו בו?","\u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דיהיב\u0004 \u0005[שנתן]\u0006 \u0003אשם ליהויריב במשמרתו\u0004 של \u0003יהויריב, וכסף לידעיה\u0004 גם כן \u0003במשמרתו\u0004 של \u0003יהויריב,\u0004 ובכך נחלקו. \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון דלאו\u0004 \u0005[שאין]\u0006 זו \u0003משמרת\u0004 של \u0003ידעיה היא\u0004 ונטלו מה שאינם זכאים לו — את \u0003ידעיה קנסינן ליה\u0004 \u0005[אנו קונסים],\u0006 \u0003הלכך\u0004 \u0005[משום כך]\u0006 \u0003יחזיר\u0004 משמרת ידעיה ה\u0003כסף\u0004 שאצלו \u0003אצל אשם\u0004 הנמצא במשמרתו של יהויריב. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003שלא כדין הוא עבוד\u0004 \u0005[עשו]\u0006 \u0003בני יהויריב\u0004 ש\u0003קיבלו אשם מקמי\u0004 \u0005[לפני]\u0006 שקיבלו \u0003כסף,\u0004 שהרי צריך קודם לקבל את הגזילה ואחר כך את האשם, \u0003הלכך לדידהו קנסינן להו\u0004 \u0005[משום כך אותם אנו קונסים],\u0006 \u0003ויחזור אשם\u0004 שבידיהם \u0003אצל כסף\u0004 שבידי ידעיה.","ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: לדברי ר' יהודה\u0004 הסבור שאם נתן אשם לבני יהויריב וכסף לבני ידעיה בזמן משמרת יהויריב, יחזור הכסף לבני יהויריב, \u0003אם קדמו בני יהויריב והקריבו את האשם\u0004 קודם שהגיע לידם הכסף מידי ידעיה, \u0003יחזור ויביא אשם אחר ויקריבוהו בני ידעיה\u0004 שהכסף בידם, \u0003וזכו הללו\u0004 בני יהויריב \u0003במה שבידן\u0004 (באותו אשם שהקריבו).","על כך \u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה: \u0003למאי חזי\u0004 \u0005[למה ראויה]\u0006 זכיה זו? הלא \u0003אשם פסול הוא\u0004, שהלא הביאוהו שלא כראוי, וכולו נשרף! \u0003אמר רבא:\u0004 הכוונה היא \u0003לעורו,\u0004 שעל כל פנים בעורו זוכים בני יהויריב.","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: לדברי ר' יהודה, אם קיים\u0004 עדיין ה\u0003אשם,\u0004 שלא הקריבוהו בני יהויריב — \u0003יחזיר אשם אצל כסף\u0004 ויקריבוהו בני ידעיה.","ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהודה יחזיר כסף אצל אשם אית ליה\u0004 \u0005[יש לו,\u0006 כך הוא סבור\u0005]\u0006! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דנפק\u0004 \u0005[שיצאו]\u0006 \u0003משמרתו\u0004 של \u0003יהויריב ולא תבעו\u0004 את הכסף ממשמרת ידעיה, \u0003והא קא משמע לן דאחולי אחילו גבייהו\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו שמחלו להם\u0006 בני יהויריב את הכסף\u0005],\u0006 ומעתה, צריכים הם לתת את האשם שבידיהם לבני ידעיה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003אמר רבי: לדברי ר' יהודה, אם קיים\u0004 עדיין ה\u0003אשם\u0004 — \u0003יחזור כסף אצל אשם.\u0004 ותוהים: \u0003פשיטא, הכי אית ליה\u0004 \u0005[פשוט, כך יש לו],\u0006 הרי כך ר' יהודה אומר בפירוש ומה חידש רבי!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דנפיק\u0004 \u0005[שיצאו]\u0006 \u0003משמרתם דהני ודהני\u0004 \u0005[של אלה ושל אלה]\u0006 \u0003ולא תבעו\u0004 שניהם אלה מאלה, \u0003מהו דתימא אחולי גבי הדדי\u0004 \u0005[שתאמר מחלו זה לזה]\u0006 וישאר הכסף אצל בני ידעיה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003כיון\u0004 ש\u0003לא תבעי\u0004 \u0005[תבעו]\u0006 בני ידעיה מבני יהויריב את האשם לאחר שיצאו בני יהויריב, ואינם מממשים את זכותם, \u0003להדרו ברישא\u0004 \u0005[שיחזרו לתחילה]\u0006 ויחזור הכסף אצל האשם — לבני יהויריב.","שנינו במשנה: \u0003שהמביא גזילו עד שלא הביא אשמו\u0004 — יצא, אבל אם מביא קרבן אשם תחילה — לא יצא. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רבא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"האשם המושב לה' לכהן מלבד איל הכפרים אשר יכפר בו\"\u0004 (במדבר ה, ח), \u0003מכלל\u0004 הדברים אתה למד שה\u0003כסף\u0004 צריך להיות מושב \u0003ברישא\u0004 \u0005[בתחילה]\u0006 שכפי שדייקו לעיל \"אשם\" הוא הגזל, והוא נזכר תחילה בפסוק ואחריו נזכר קרבן האשם.","\u0003אמר ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003לרבא: אלא מעתה,\u0004 לפי שאתה מפרש ש\"מלבד\" פירושו מה שבא אחר כך, אם כך הכתוב בענין קרבן מוסף: \u0003\"מלבד עלת הבקר\"\u0004 (שם כח, כג) שהוא קרבן התמיד של שחר, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003תפרש\u0004 \u0003מכלל\u0004 ש\u0003מוספין\u0004 מקריבים \u0003ברישא\u0004 \u0005[בראש]\u0006 לפני תמיד של שחר?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין שלא יהא דבר קודם ל\u0004הקרבת \u0003תמיד של שחר?\u0004 — \u0003תלמוד לומר: \"וערך עליה העלה\u0004 והקטיר עליה חלבי השלמים\u0003\"\u0004 (ויקרא ו, ה), \u0003ואמר רבא: \"העולה\"\u0004 בהדגשה — היא \u0003עולה ראשונה,\u0004 וכוונתו לתמיד של שחר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: אני איני לומד מן המלה \"מלבד\", אלא \u0003אנא\u0004 \u0005[אני]\u0006 \u0003מ\"אשר יכפר בו\"\u0004 (במדבר ה, ח) \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר, שנאמר בלשון עתיד, לומר שלאחר מכן יכפר בקרבן, \u0003ועדיין\u0004 בזמן שמשיב את האשם (הגזל) \u0003לא כיפר\u0004 אותו איל.","שנינו במשנה: \u0003נתן לו את הקרן\u0004 ולא נתן לו את החומש — הריהו יכול להקריב את קרבן האשם, לפי שאין החומש מעכב. ומבררים את מקורו של דין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין אשם מעילה, שמביא מי שמעל בקודש, כלומר, שנהנה מן ההקדש שלא כדין, בנוסף לשווי ההנאה מן ההקדש, וחומשו: \u0003מנין שאם הביא מעילתו\u0004 (שווי מה שנהנה מן ההקדש), \u0003ולא הביא\u0004 קרבן \u0003אשמו,\u0004 או שהביא \u0003אשמו ולא הביא מעילתו, שלא יצא?\u0004","","— \u0003תלמוד לומר: \"באיל האשם ונסלח לו\"\u0004 (ויקרא ה, טז). ללמד שהסליחה והכפרה היא לאחר שיביא \"איל\" — קרבן, ו\"אשם\" — כסף המעילה. \u0003ומנין שאם הביא\u0004 קרבן \u0003אשמו עד שלא\u0004 (לפני) \u0003הביא מעילתו, שלא יצא?\u0004 — \u0003תלמוד לומר: \"באיל האשם\",\u0004 וה\"א הידיעה מורה שזהו \u0003האשם בכבר\u0004 שכבר הביא, ללמד שכסף המעילה קודם.","\u0003יכול כשם שאיל ואשם מעכבים, כך חומש מעכב? תלמוד לומר: \"באיל האשם ונסלח לו\",\u0004 לומר: \u0003איל ואשם מעכבים בהקדש, ואין חומש מעכב.\u0004","ומוסיפים לברייתא: \u0003וילמד הקדש\u0004 (דין מעילה) \u0003מהדיוט\u0004 (מדין גזל הגר) \u0003ו\u0004דין \u0003הדיוט מהקדש.\u0004 כיצד?","\u0003הקדש מהדיוט: מה \"אשם\" דהתם\u0004 \u0005[ששם]\u0006 שכתוב בהדיוט כוונתו ה\u0003קרן\u0004 (וכמבואר לעיל בבא קמא קי,א), \u0003אף אשם דהכא\u0004 \u0005[ש\u0006כתוב \u0005כאן]\u0006 במעילה כוונתו \u0003קרן,\u0004 סכום הכסף עצמו. \u0003ו\u0004נלמד \u0003הדיוט מהקדש: מה\u0004 ב\u0003הקדש אין\u0004 ה\u0003חומש מעכב, אף\u0004 ב\u0003הדיוט נמי\u0004 \u0005[גם כן]\u0006 \u0003אין\u0004 ה\u0003חומש מעכב.\u0004",""],["\u0003הגוזל ומאכיל את בניו,\u0004 שנתן להם לאכול את מה שגזל, \u0003ו\u0004כן אם \u0003הניח לפניהם\u0004 את הגזילה שגזל, ומת האב — הרי הבנים \u0003פטורין מלשלם\u0004 לנגזל את מה שגזל ממנו אביהם, \u0003ו\u0004אולם \u0003אם היה דבר שיש בו אחריות\u0004 — \u0003חייבין\u0004 הבנים \u0003לשלם.\u0004","ומביאים הלכה אשר עליה יקשו ממה ששנינו במשנתנו, \u0003אמר רב חסדא: גזל ולא נתייאשו הבעלים\u0004 מאותו חפץ שנגזל מהם, \u0003ובא אחר ואכלו ממנו\u0004 (מן הגזלן), \u0003רצה\u0004 הבעלים — \u0003מזה,\u0004 מן הגזלן, הוא \u0003גובה,\u0004 \u0003רצה\u0004 — \u0003מזה,\u0004 ממי שלקח ממנו הוא \u0003גובה,\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כל כמה\u0004 ש\u0003לא נתייאשו הבעלים\u0004 מן החפץ הגזול עדיין \u0003ברשותיה דמריה קאי\u0004 \u0005[ברשותו של בעליו\u0006 הוא \u0005עומד].\u0006 ונמצא שזה שאכלו — כאילו הוא גזלו מרשות בעליו. אבל כיון שהגזלן הראשון כבר התחייב להשיב לו — יכולים הבעלים לגבות ממנו, אם ירצו.","על דברי רב חסדא מביאים כי \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הגוזל ומאכיל את בניו, והניח לפניהם\u0004 — \u0003פטורין מלשלם.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב חסדא,\u0004 שהרי מן המשנה עולה שאם נותן לאחרים — הרי הם פטורים! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב חסדא\u0004 בתשובה: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 משנה\u0005],\u0006 הרי היא מדברת דווקא \u0003לאחר יאוש,\u0004 שאז גוף הגזילה כבר נקנה לגזלן, ושוב אינו נחשב ברשות הבעלים.","שנינו במשנה: \u0003אם הניח לפניהם\u0004 — \u0003פטורין מלשלם. אמר רמי בר חמא, זאת אומרת: רשות יורש כרשות לוקח\u0004 (קונה) \u0003דמי\u0004 \u0005[נחשבת],\u0006 שאף שהגזילה מונחת כפי שהיא לפני הבנים שלא אכלוה, מכל מקום כיון שירשו אותה הרי הם נחשבים כקונים את החפץ, והריהו יוצא מרשות הבעלים לגמרי.","ואילו \u0003רבא אמר: רשות יורש לאו\u0004 \u0005[לא]\u0006 \u0003כרשות לוקח דמי\u0004 \u0005[נחשבת],\u0006 \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003כשאכלום\u0004 לאחר שהניח לפניהם ולכן פטורים הבנים מלשלם, שאין הגזילה מצויה עוד בעין, ואין מה להשיב לבעלים.","ומקשים על רבא: \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנה\u0006 ב\u0005סופה\u0006 של המשנה\u0005]\u0006 \u0003אם היה דבר שיש בו אחריות\u0004 — \u0003חייבין לשלם, מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבראשה]\u0006 של המשנה גם כן \u0003בגזילה קיימת עסקינן\u0004 \u0005[עוסקים אנו],\u0006 אלא שהוא דבר שאין בו אחריות, שאינו ניכר ומובחן כחפץ של הנגזל. ומתרצים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא\u0004 בתשובה, כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם הניח להם אביהם אחריות נכסים,\u0004 כלומר, הניח בירושה קרקעות (שהן \"אחריות נכסים\"), הרי נכסים אלה משתעבדים לתשלום חובות האב, ולכן הבנים \u0003חייבין לשלם,\u0004 ואף שהגזילה אינה קיימת עוד.","ומקשים: \u0003והא מתני ליה\u0004 \u0005[והרי\u0006 היה \u0005שונה,\u0006 לומד, \u0005לו]\u0006 \u0003רבי לר' שמעון בריה\u0004 \u0005[בנו]\u0006 בפירוש משנה זו: \u0003לא דבר שיש בו אחריות ממש,\u0004 כגון קרקעות, נאמר במשנה שחייבים הבנים להחזיר, \u0003אלא אפילו פרה וחורש בה, חמור ומחמר אחריו\u0004 — \u0003חייבין להחזיר, מפני כבוד אביהן.\u0004 משמע שאין הכוונה פה לאחריות נכסים שהשאיר האב, אלא לנכסים הניכרים לעין, ואם כן בהכרח מדובר כגון כשהגזילה קיימת!","\u0003אלא אמר רבא: כי שכיבנא\u0004 \u0005[כאשר אמות]\u0006 \u0003ר' אושעיא נפיק לוותי\u0004 \u0005[יצא לקראתי],\u0006 ממקומו בגן העדן לכבדני, כפי שאני מכבד אותו בחיי \u0003דתריצנא מתניתין כוותיה\u0004 \u0005[שיישבתי\u0006 את \u0005משנתנו כשיטתו].\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' אושעיא: הגוזל ומאכיל את בניו\u0004 — \u0003פטורין מלשלם. הניח לפניהם,\u0004 אם עדיין ה\u0003גזילה קיימת\u0004 — \u0003חייבין,\u0004 ואם \u0003אין הגזילה קיימת\u0004 — \u0003פטורין. הניח להם אביהם אחריות נכסים\u0004 — ד\u0003חייבין לשלם,\u0004 ובאופן זה אפשר גם להסביר את משנתנו, למרות שרבי אינו סבור כן.","ודנים בברייתא זו של ר' אושעיא. \u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 \u0003אין הגזילה קיימת\u0004 — \u0003פטורין.\u0004 ושואלים: \u0003נימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003רב חסדא,\u0004 שהוא אמר לעיל שהבעלים רשאי לתבוע את תשלום הגזילה גם ממי שאכל את החפץ מן הגזלן, ואם כן אף יורשי הגזלן שאכלו חייבים! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב חסדא\u0004 בתשובה: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 של ר' אושעיא הרי היא מדברת \u0003לאחר יאוש,\u0004 שהבעלים התייאשו מן הגזילה קודם שהניח לפניהם אביהם, וכבר יצאה מרשותו, ואינו יכול לתובעם.","ועוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: אם ה\u0003גזילה קיימת\u0004 — \u0003חייבין לשלם. נימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003רמי בר חמא?\u0004 שהרי לדעת רמי בר חמא בכל מקרה, כיון שנעשה שינוי בעלים על ידי ירושה — פטורים. ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רמי בר חמא\u0004 בתשובה: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 —"],["\u0003לפני יאוש,\u0004 שכיון שאין פה יאוש, הרי שינוי רשות בלבד (של הירושה) אינו מפקיע אותו מרשות הבעלים הראשונים.","\u0003רב אדא בר אהבה מתני להא\u0004 \u0005[היה שונה את זו],\u0006 את הערתו של \u0003רמי בר חמא, אהא\u0004 \u0005[על\u0006 ברייתא \u0005זו],\u0006 ששנינו: \u0003הניח להן,\u0004 ליתומים, \u0003אביהן מעות של רבית\u0004 שלקח באיסור, \u0003אף על פי שיודעין שהן של רבית\u0004 — \u0003אין חייבין להחזיר.\u0004 ועל כך \u0003אמר רמי בר חמא, זאת אומרת: רשות יורש כרשות לוקח דמי\u0004 \u0005[נחשבת],\u0006 וקנו את כספי הריבית להיות כשלהם.","ואילו \u0003רבא אמר: לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003רשות יורש לאו\u0004 \u0005[לא]\u0006 \u0003כרשות לוקח דמי\u0004 \u0005[נחשבת]\u0006 ואין זה כשינוי רשות, \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 הדין לענין רבית משום ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אל תקח מאתו נשך ותרבית\u0004 ויראת מאלהיך וחי אחיך עמך\u0003\"\u0004 (ויקרא כה, לו), וההדגשה בכתוב באה לומר \u0003אהדר ליה כי היכי דנחי בהדך\u0004 \u0005[החזר לו כדי שיחיה עמך],\u0006 וכיון שדווקא מכך נובע חיוב ההשבה (ולא מחמת שממון זה גזול בידו) יש לומר כי \u0003לדידיה קא מזהר ליה רחמנא\u0004 \u0005[לו עצמו\u0006, למלוה בריבית, \u0005מזהירה אותו התורה],\u0006 \u0003לבריה לא מזהר ליה רחמנא\u0004 \u0005[את בנו אין מזהירה התורה].\u0006","ומעירים: \u0003מאן דמתני לה\u0004 \u0005[מי ששונה את זו],\u0006 הערתו של רמי בר חמא על ה\u0003ברייתא\u0004 ומדייק ממנה שרשות יורש כלוקח, למרות שיש הסבר אחר שניתן לתת לדבר, \u0003כל שכן\u0004 שהוא שונה אותה \u0003אמתניתין\u0004 \u0005[על משנתנו]\u0006 שאין לה הסבר אחר. ואולם \u0003מאן דמתני לה אמתניתין\u0004 \u0005[מי ששונה אותה על משנתנו],\u0006 יש לומר שדווקא ממנה הוא מדייק כך, \u0003אבל\u0004 על ה\u0003ברייתא\u0004 הוא סבור ש\u0003רמי בר חמא כ\u0004שיטת \u0003רבא מתני לה\u0004 \u0005[\u0006הוא \u0005שונה אותה].\u0006 שאין זה משום שרשות היורש כרשות לוקח, אלא משום שלענין ריבית אין הבנים מחוייבים בהשבה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הגוזל ומאכיל את בניו\u0004 את הגזילה שגזל — הרי הם \u0003פטורין מלשלם\u0004 לנגזל את דמי הגזילה. ואם \u0003הניח לפניהם\u0004 את הגזילה, אם היו הבנים \u0003גדולים\u0004 — \u0003חייבין לשלם,\u0004 ואם היו \u0003קטנים\u0004 — \u0003פטורין מלשלם. ואם אמרו\u0004 הבנים ה\u0003גדולים\u0004 לנגזל שתבעם: \u0003אין אנו יודעין חשבונות שחשב אבינו עמך\u0004 ואין אנו יודעים אם פרע לך את תשלום הגזילה בכסף — הרי הם \u0003פטורין.\u0004","ותוהים: \u0003משום דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003\"אין אנו יודעין\",\u0004 משום כך \u0003פטורים?!\u0004 הרי ברור שיש גזילת אביהם בידם, וכיצד נפטרים מלהחזירה בטענת ספק של שמא השיבה אביהם? \u0003אמר רבא:\u0004 אין מדובר בטענת ספק, אלא בטענת ודאי, ו\u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 בברייתא, \u0003גדולים שאמרו: יודעים אנו חשבונות שחשב אבינו עמך, ולא פש\u0004 \u0005[נשאר]\u0006 \u0003לך גביה\u0004 \u0005[אצלו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 שהוא פרע הכל — הרי הם \u0003פטורין.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הגוזל ומאכיל בניו\u0004 — הרי הם \u0003פטורין מלשלם.\u0004 אם \u0003הניח לפניהם ואכלום\u0004 — \u0003בין גדולים בין קטנים חייבין\u0004 לשלם. ותוהים: \u0003קטנים מי מיחייבי\u0004 \u0005[האם\u0006 הם \u0005חייבים]?\u0006 \u0003לא יהא\u0004 דינם \u0003אלא דאזיק אזוקי\u0004 \u0005[שהזיקו]\u0006 הם עצמם, והרי קטנים אינם חייבים לשלם מה שהזיקו! \u0003אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין את הברייתא: אם \u0003הניח לפניהם ועדיין לא אכלום\u0004 — \u0003בין גדולים בין קטנים חייבין\u0004 להחזיר.","\u0003אמר רבא: הניח להם\u0004 ליתומים \u0003אביהם פרה שאולה\u0004 — \u0003משתמשין בה\u0004 גם לאחר מותו \u0003כל ימי שאלתה,\u0004 ואולם אם \u0003מתה\u0004 הפרה במשך זמן זה — \u0003אין חייבין באונסיה\u0004 כדין שואל, שההתחייבות לשלם עבור האונס היתה רק של האב ולא של יורשיו. אם \u0003כסבורים\u0004 הם היתומים שפרה זו \u0003של אביהם היא, וטבחוה ואכלוה\u0004 — \u0003משלמין דמי בשר בזול\u0004 ולא את כל הנזק. ומוסיף רבא: אם \u0003הניח להם אביהם אחריות נכסים,\u0004 כלומר, קרקעות — \u0003חייבין לשלם.\u0004","הלכה אחרונה זו, \u0003איכא דמתני לה ארישא\u0004 \u0005[יש ששונה אותה,\u0006 מייחס אותה, \u0005על ראשית\u0006 דברי רבא\u0005],\u0006 לומר שאף שפטורים הבנים מאונסיה של פרה, אם השאיר אביהם אחריות נכסים — משלמים, שחובת התשלום חלה בזמן שאביהם שאל את הפרה, ונכסיו נשתעבדו לכך, \u0003ואיכא דמתני לה אסיפא\u0004 \u0005[ויש ששונה אותה על הסוף]\u0006 במקרה שטבחוה ואכלוה.","ומבררים את השיטות: \u0003מאן דמתני לה ארישא\u0004 \u0005[מי ששונה אותה על ראשה],\u0006 \u0003כל שכן\u0004 ששונה אותה גם \u0003אסיפא\u0004 \u0005[על סופה],\u0006 שהיורשים משלמים על האונס אם יש אחריות נכסים, וכל שכן שמשלמים על מה שאכלוה בעצמם. \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו על שיטת \u0003רב פפא\u0004 שיובאו דבריו להלן. ואולם \u0003מאן דמתני לה אסיפא\u0004 \u0005[מי ששונה אותה על סופה],\u0006 שכשטבחוה ואכלוה משלמים מנכסי אביהם, \u0003אבל ארישא\u0004 \u0005[על ראשה]\u0006 שמשלמים מנכסיו על אונסיה של הפרה — הוא \u0003לא\u0004 שונה אותה. \u0003והיינו\u0004 \u0005[והרי זו]\u0006 כשיטתו של \u0003רב פפא.\u0004 ומה עניינה?","— ש\u0003אמר רב פפא: היתה פרה גנובה לו,\u0004 שגנב פרה לפני שבת, \u0003וטבחה בשבת\u0004 — \u0003חייב\u0004 בתשלומים, משום \u0003שכבר חייב ב\u0004תשלום על ה\u0003גניבה קודם שיבא לידי איסור שבת\u0004 שבטביחה. אבל אם \u0003היתה פרה שאולה לו וטבחה בשבת\u0004 — \u0003פטור\u0004 מלשלם, משום \u0003שאיסור שבת\u0004 שבטביחה \u0003ואיסור גניבה\u0004 שנעשה גם הוא על ידי הטביחה, ומחייבו ממון, \u0003באין כאחד,\u0004 ואין אדם משלם ממון על מעשה שעשה שיש בו גם חיוב מיתה. ומכאן משמע שלדעת רב פפא אין חיוב האונסים חל על השואל משעת השאילה (שקדמה לשבת) אלא משעת האונס עצמה. ומשום כך אף לענייננו — אין נכסי האב משתעבדים מתחילה לתשלום אונסיה של הפרה.","הדעות החולקות בענין חיוב תשלום בנים קטנים של גזלן, שהובאו בשתי ברייתות שונות לעיל, מובאות יחד בברייתא נוספת ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על מה שנאמר \u0003\"והשיב את הגזילה אשר גזל\"\u0004 (ויקרא ה, כג): \u0003מה תלמוד לומר \"אשר גזל\"?\u0004 מדוע לא הסתפק הכתוב באומרו \"והשיב את הגזילה\"? — הכוונה היא ללמדנו: \u0003יחזיר כעין שגזל,\u0004 כלומר, את מה שגזל.","\u0003מכאן אמרו: הגוזל ומאכיל את בניו\u0004 — \u0003פטורין מלשלם,\u0004 כיון שגזילה שגזל אינה קיימת עוד. אם \u0003הניח לפניהן\u0004 את הגזילה — \u0003בין גדולים בין קטנים חייבין. משום\u0004 \u0005[בשם ]\u0006 \u0003סומכוס אמרו: גדולים חייבין, קטנים פטורין\u0004 וכפי שמוסבר להלן, טעמו הוא משום שכדי להוציא מידם צריך להעמידם בדין, וקטן אינו ראוי עדיין לכך.","מסופר \u0003: בר חמוה\u0004 \u0005[בן חמיו,\u0006 גיסו\u0005]\u0006 של \u0003ר' ירמיה\u0004 שהיה עדיין קטן, \u0003טרק גלי באפיה\u0004 \u0005[סגר\u0006 את \u0005דלתות\u0006 בית אביו \u0005בפני]\u0006 \u0003ר' ירמיה\u0004 ולא הניח לו להחזיק בבית או בחדר שטען עליו ר' ירמיה ששלו הוא, \u0003אתא לקמיה\u0004 \u0005[בא\u0006 ר' ירמיה \u0005לפני]\u0006 \u0003ר' אבין\u0004 בתביעה על גיסו,","\u0003אמר\u0004 לו ר' אבין: \u0003שלו הוא תובע,\u0004 ואין אתה יכול להוציא מידו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה: \u0003והא מייתינא סהדי דאחזקי ביה בחיי דאבוה\u0004 \u0005[והרי אני\u0006 יכול \u0005להביא עדים שהחזקתי בו\u0006 בדבר זה \u0005בחיי אביו],\u0006 משום שאביו מכר לי אותו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מקבלין\u0004 בית דין \u0003עדים\u0004"],["\u0003שלא בפני בעל דין?\u0004 וכיון שקטן הוא הרי זה נחשב כאילו שאינו נמצא! אמר לו ר' ירמיה: \u0003ולא?\u0004 וכי אין עושים כן? \u0003והא קתני\u0004 \u0005[והרי שנינו]\u0006 שגזלן שהניח גזילה לפני בניו \u0003בין גדולים בין קטנים חייבין.\u0004 משמע שמקבלים עדות בפני קטנים וגובים מהם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבין: \u0003הרי מחלוקת סומכוס בצידך,\u0004 הרי סומכוס חולק על כך וסבור שקטנים פטורים. \u0003אמר\u0004 לו ר' ירמיה: וכי \u0003איכפל כולי עלמא וקאי\u0004 \u0005[טרח כל העולם ועומד]\u0006 \u0003כ\u0004שיטת \u0003סומכוס\u0004 כדי \u0003לאפקוען לדידי\u0004 \u0005[להפקיע את\u0006 רכושי \u0005שלי]?\u0006","\u0003אדהכי איגלגל מילתא אתא ומטא לקמיה\u0004 \u0005[בתוך כך\u0006 בינתיים \u0005התגלגל הדבר\u0006 ו\u0005בא והגיע לפני]\u0006 \u0003ר' אבהו\u0004 והוא דן בו, \u0003אמר:\u0004 וכי \u0003לא שמיע לכו\u0004 \u0005[שמעתם]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמר \u0003רב יוסף בר חמא אמר ר' אושעיא?\u0004 ש\u0003אמר רב יוסף בר חמא אמר ר' אושעיא: תינוק שתקף\u0004 (החזיק) \u0003בעבדיו, וירד לתוך שדה של חבירו ואמר \"שלי הוא\", אין אומרים: נמתין עד שיגדיל\u0004 התינוק, \u0003אלא מוציאין מידו\u0004 את העבד והשדה \u0003מיד, ולכשיגדיל יביא עדים ונראה\u0004 למי שייך, ואף כאן, נוציא את הבית מידי הקטן וניתנו לר' ירמיה עד שיגדל הקטן!","ומקשים: \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דמפקינן מיניה\u0004 \u0005[שאנו מוציאים ממנו]\u0006 את השדה — משום \u0003דלא קיימא ליה אחזקה דאבוה\u0004 \u0005[שאינה עומדת לו חזקת אביו],\u0006 \u0003אבל היכא דאית ליה חזקה דאבוה\u0004 \u0005[במקום שיש לו חזקת אביו],\u0006 כגון בעניינו של ר' ירמיה — \u0003לא\u0004 מוציאים מידו.","אגב שהוזכרה מקודם קבלת עדות שלא בפני בעל דין — דנים בה לגופה. \u0003אמר רב אשי אמר ר' שבתאי: מקבלין עדים שלא בפני בעל דין. תהי\u0004 \u0005[תהה]\u0006 \u0003בה\u0004 על הלכה זו \u0003ר' יוחנן, וכי מקבלין עדים שלא בפני בעל דין?\u0004","\u0003קיבלה מיניה\u0004 \u0005[קיבל ממנו]\u0006 \u0003ר' יוסי בר חנינא\u0004 פירוש הדברים: מתי מקבלים — דווקא במקרים מיוחדים \u0003כגון שהיה הוא חולה או עדיו חולים, או שהיו עדיו מבקשין לילך למדינת הים ושלחו לו\u0004 לבוא לדין \u0003ולא בא,\u0004 שבמקרים אלה שיש חשש שלא יהיה עוד ניתן לקבל עדות זו בפני בין דין — מותר לקבל עדותם שלא בפני בעל דין.","וכדברי ר' שבתאי \u0003אמר רב יהודה אמר שמואל: מקבלין עדים שלא בפני בעל דין. אמר מר עוקבא: לדידי מיפרשא לי מיניה\u0004 \u0005[לי עצמי התפרש\u0006 הדבר \u0005ממנו],\u0006 מ\u0003שמואל\u0004 עצמו: \u0003כגון\u0004 ש\u0003פתחו ליה בדיניה\u0004 \u0005[לו בדינו]\u0006 \u0003ושלחו ליה\u0004 \u0005[לו]\u0006 לאותו בעל דין לבוא \u0003ולא אתא\u0004 \u0005[בא],\u0006 אז מקבלים עדות שלא בפניו, \u0003אבל\u0004 אם \u0003לא פתחו ליה בדינא\u0004 \u0005[לו בדין],\u0006 \u0003מצי אמר ליה\u0004 \u0005[יכול לומר להם]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לבית דין הגדול אזילנא\u0004 \u0005[אני הולך]\u0006 ושם ידונו בענין זה.","ומקשים: \u0003אי הכי, כי\u0004 \u0005[אם כך, כאשר]\u0006 \u0003פתחו ליה\u0004 \u0005[לו]\u0006 כבר בדין \u0003נמי מצי אמר ליה\u0004 \u0005[גם כן יכול לומר לו,\u0006 להם\u0005]:\u0006 \u0003לבית דין הגדול אזילנא\u0004 \u0005[הולך אני]!\u0006 \u0003אמר רבינא:\u0004 מדובר כאן \u0003כגון דנקט דיסקא\u0004 \u0005[ש\u0006בית הדין \u0005מחזיק\u0006 בידיו \u0005תעודה]\u0006 \u0003מבית דין הגדול\u0004 בה מסמיכים אותו לדון בענין זה.","ובענין דומה \u0003אמר רב: מקיימין את השטר\u0004 שבית דין בודק את כשרות חתימות העדים שבשטר ומאשר אותן גם \u0003שלא בפני בעל דין\u0004 (הלווה). \u0003ור' יוחנן אמר: אין מקיימין את השטר שלא בפני בעל דין. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת לר' יוסי בר אבהו: אסברה\u0004 \u0005[אסביר]\u0006 \u0003לך טעמיה\u0004 \u0005[\u0006את \u0005טעמו]\u0006 של \u0003ר' יוחנן\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בעניינו של שור שנגח: \u0003\"והועד בבעליו ולא ישמרנו\"\u0004 (שמות כא, כט), \u0003אמרה תורה: יבא בעל השור ויעמוד על שורו\u0004 בשעה שמעידים בו שנגח, שאינו נעשה מועד עד שיעידו עליו בפני בעליו. ואף כאן יש לומר אותו טעם: יבוא בעל השטר, כלומר, הלווה, ויעמוד על שטרו.","\u0003אמר רבא, הלכתא\u0004 \u0005[הלכה\u0006 פסוקה היא\u0005]:\u0006 \u0003מקיימין את השטר שלא בפני בעל דין, ואפילו\u0004 הוא \u0003עומד וצווח\u0004 שאין לקיימו משום שהוא מזוייף, \u0003ואי אמר\u0004 \u0005[ואם\u0006 הוא \u0005אומר]:\u0006 \u0003נקיטו\u0004 \u0005[החזיקו]\u0006 \u0003לי,\u0004 המתינו לי, \u0003זימנא\u0004 \u0005[זמן]\u0006 מסויים \u0003עד דמייתינא סהדי ומרענא ליה לשטרא\u0004 \u0005[שאביא עדים וארע את\u0006 תוקפו של \u0005השטר]\u0006 — \u0003נקטינן ליה\u0004 \u0005[מחזיקים,\u0006 ממתינים \u0005אנו\u0006 \u0005לו]\u0006 ואין גובים ממנו מיד. \u0003אי אתא\u0004 \u0005[אם בא]\u0006 עם עדיו בתוך הזמן שנקצב לו — \u0003אתא\u0004 \u0005[בא],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא אתא\u0004 \u0005[בא]\u0006 — \u0003נטרינן ליה\u0004 \u0005[מחכים אנו לו]\u0006 שלושה ימי דין נוספים שהם: \u0003שני וחמישי ושני,\u0004","\u0003אי\u0004 \u0005[אם]\u0006 עדיין \u0003לא אתא\u0004 \u0005[בא]\u0006 — \u0003כתבינן פתיחא עלויה תשעין יומין\u0004 \u0005[כותבים אנו שטר נידוי עליו\u0006 על שאינו פורע את חובו, למשך \u0005תשעים יום].\u0006 \u0003תלתין קמאי לא נחתינן לנכסיה\u0004 \u0005[שלושים\u0006 ימים \u0005ראשונים אין אנו יורדים\u0006 עדיין \u0005לנכסיו],\u0006 \u0003דאמר\u0004 \u0005[שאומר]\u0006 בית הדין: שמא \u0003קא טרח בזוזי וניזוף\u0004 \u0005[הוא טורח בכספים כדי ללוות]\u0006 לפרוע את חובו זה. בשלושים ימים \u0003מציעאי נמי\u0004 \u0005[אמצעיים גם כן]\u0006 עדיין \u0003לא נחתינן ליה לנכסיה\u0004 \u0005[יורדים אנו לו לנכסיו],\u0006 \u0003דאמר\u0004 \u0005[שאומר]\u0006 בית הדין: \u0003דלמא\u0004 \u0005[שמא]\u0006 עדיין \u0003לא אשכח למיזף וקא טרח ומזבין\u0004 \u0005[מצא ללוות והוא טורח ומוכר]\u0006 מנכסיו כדי לשלם. בשלושים ימים \u0003בתראי נמי\u0004 \u0005[גם כן]\u0006 \u0003לא נחתינן לנכסיה\u0004 \u0005[יורדים אנו לנכסיו],\u0006 \u0003דאמר\u0004 \u0005[שאומר\u0006 בית הדין\u0005]:\u0006 \u0003לוקח\u0004 זה שהוא מוכר לו את הקרקעות על מנת לפרוע, \u0003גופיה קא טרח בזוזי\u0004 \u0005[\u0006הוא \u0005עצמו טורח למצוא כסף]\u0006 כדי לשלם עבור הנכסים.","ואם \u0003לא אתא\u0004 \u0005[בא]\u0006 גם בסוף תשעים יום — \u0003כתבינן אדרכתא אניכסיה\u0004 \u0005[כותבים אנו שטר רדיפה על נכסיו],\u0006 כלומר, שמותר ללווה לגבות מהם בכל מקום שימצאם. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שקובעים לו זמן אחר זמן, אמורים דווקא בזמן \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003\"אתינא\"\u0004 \u0005[בא אני]\u0006 לבית דין \u0003\",\u0004 אבל בפועל הוא משתמט בטענות שונות. \u0003אבל\u0004 אם \u0003אמר \"לא אתינא\"\u0004 \u0005[איני בא]\u0006 — \u0003לאלתר\u0004 (מיד) \u0003כתבינן\u0004 \u0005[כותבים אנו]\u0006 שטר אדרכתא, ואין ממתינים תשעים יום.","ועוד: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שממתינים לו תשעים יום אמורים דווקא \u0003במלוה,\u0004 שנותנים זמן ללווה להשיג את הכסף, \u0003אבל בפקדון\u0004 שהוא נתבע להחזיר — \u0003לאלתר\u0004 (מיד) \u0003כתבינן\u0004 \u0005[כותבים אנו]\u0006 שטר אדרכתא לרדת לנכסיו, שהרי הפקדון צריך להיות שמור בידו, ואין סיבה להשהיה.","ופרט נוסף בענין זה: \u0003וכי כתבינן\u0004 \u0005[וכאשר אנו כותבים]\u0006 שטר אדרכתא — הרי זה דווקא \u0003אמקרקעי\u0004 \u0005[על הקרקעות]\u0006 של הלווה, \u0003אבל אמטלטלי\u0004 \u0005[על המיטלטלים]\u0006 — \u0003לא,\u0004 והטעם: \u0003דלמא שמיט ואכיל להו\u0004 \u0005[שמא ישמוט,\u0006 יבריח, \u0005או יאכל אותם]\u0006 ה\u0003מלוה למטלטלי\u0004 \u0005[את המיטלטלים]\u0006 של הלווה עד שיתברר הדבר. \u0003וכי אתי\u0004 \u0005[וכאשר יבוא]\u0006 ה\u0003לוה ומייתי סהדי ומרע ליה לשטרא\u0004 \u0005[ויביא עדים וירע את\u0006 כוחו של \u0005השטר],\u0006 \u0003לא משכח מידי למיגבה\u0004 \u0005[ימצא דבר לגבות\u0006 ממנו\u0005]\u0006 בחזרה את מה שלקח לעצמו המלווה.","\u0003ו\u0004אולם \u0003אי אית ליה מקרקעי\u0004 \u0005[אם יש לו קרקעות]\u0006 \u0003למלוה\u0004 — \u0003כתבינן\u0004 \u0005[כותבים אנו]\u0006 אדרכתא על מיטלטלים, שהרי גם אם יקח המלוה או יקלקל את המיטלטלים — יש ללווה עדיין ממה לגבות. על הלכה אחרונה זו אומרים: \u0003ולא היא\u0004 (ואין הדבר כן) שטר \u0003אדרכתא אמטלטלי לא כתבינן\u0004 \u0005[על מיטלטלים אין אנו כותבים]\u0006 כלל, \u0003אף על גב דאית ליה מקרקעי\u0004 \u0005[אף על פי שיש לו קרקעות,\u0006 למלווה\u0005],\u0006 כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תכסיף\u0004 \u0005[ירד ערכם]\u0006 ולא יהיה לו ממה לגבות.","והלכה נוספת בענין זה: \u0003וכי כתבינן\u0004 \u0005[וכאשר אנו כותבים]\u0006 את שטר ה\u0003אדרכתא\u0004 — \u0003מודעינן ליה\u0004 \u0005[מודיעים אנו לו]\u0006 לחייב, כהתראה אחרונה. \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים — \u0003דמיקרב\u0004 \u0005[\u0006כ\u0005שהוא קרוב],\u0006 \u0003אבל\u0004 אם הוא \u0003מירחק\u0004 \u0005[רחוק]\u0006 מאותו מקום — \u0003לא\u0004 צריך לטרוח כדי להודיע לו.","\u0003ואי מירחק ואיכא\u0004 \u0005[ואם הוא\u0006 עצמו \u0005רחוק ויש]\u0006 לו \u0003קרובים\u0004 כאן, \u0003אי נמי איכא שיירתא דאזלי ואתו התם\u0004 \u0005[או גם כן\u0006 אם \u0005יש שיירות שהולכות ובאות לשם]\u0006 למקום בו הוא נמצא, \u0003משהינן ליה תריסר ירחי שתא\u0004 \u0005[משהים אנו אותו\u0006 את כתיבת האדרכתא \u0005שנים עשר חדשי שנה]\u0006 \u0003עד דאזלא ואתי שיירתא\u0004 \u0005[שהולכת ובאה\u0006 חוזרת \u0005השיירה],\u0006 שאם היה לו מה לטעון יטען. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבינא שהא\u0004 \u0005[המתין]\u0006 \u0003למר אחא תריסר ירחי שתא\u0004 \u0005[שנים עשר חדשי שנה]\u0006 \u0003עד דאזלא ואתייא שיירתא מבי חוזאי\u0004 \u0005[שהלכה ובאה השיירה מבית חוזאי].\u0006","ואומרים: \u0003ולא היא\u0004 (אין הדבר כן), שכן \u0003התם איניש אלימא הוה\u0004 \u0005[שם אדם אלים היה]\u0006 המלוה, \u0003אי הויא מטיא אדרכתא לידיה לא הוה אפשר לאפוקי מיניה\u0004 \u0005[אם היה מגיע שטר אדרכתא לידו, אי אפשר היה\u0006 עוד \u0005להוציא ממנו].\u0006 \u0003אבל הכא לא נטרינן ליה\u0004 \u0005[כאן אין אנו מחכים לו]\u0006 \u0003אלא עד\u0004 מרחק כזה \u0003דאזיל שליחא בתלתא בשבתא ואתא בארבעה בשבתא, ולחמשא בשבתא קאי בדיניה\u0004 \u0005[שילך השליח ב\u0006יום \u0005שלישי בשבת\u0006 אחרי מושב בית דין ביום שני להודיע לו \u0005ויבוא\u0006 הנתבע \u0005ברביעי בשבת, ובחמישי בשבת יעמוד בדינו],\u0006 שזהו מרחק יום אחד.","ואגב ענין זה דנים בענין כללי יותר, הנוגע להזמנה לבית הדין. \u0003אמר רבינא: האי שלוחא דרבנן\u0004 \u0005[שליח חכמים,\u0006 שליח בית דין\u0005]\u0006 שנשלח לקרוא לאדם לבית הדין \u0003מהימנינן ליה כבי תרי\u0004 \u0005[מאמינים אנו אותו כשניים]\u0006 להעיד שהלה ביזהו, או שסירב לבוא. \u0003והני מילי לשמתא\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005ל\u0006ענין \u0005נידוי],\u0006 \u0003אבל לפתיחא\u0004 \u0005[ל\u0006כתוב עליו שטר \u0005פתיחה]\u0006 של נידוי, \u0003כיון דממונא קא מחסר ליה, דקא בעי ליה למיתב ליה זוזי לספרא\u0004 \u0005[שממון הוא מחסר אותו\u0006 בעדותו, \u0005שצריך הוא\u0006 הנתבע במקרה כזה \u0005לתת כסף לסופר]\u0006 הכותב את השטר — \u0003לא,\u0004 אינו נאמן.","ועוד בענין זה \u0003אמר רבינא: יהבינן זימנא אפומא דאיתתא ואפומא דשיבבי\u0004 \u0005[נותנים אנו זמן על פי אישה או על פי שכנים],\u0006 שמודיעים על ידם מתי קבעו מושב בית דין לענין זה. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כשהנתבע \u0003דליתיה במתא\u0004 \u0005[שאינו\u0006 מצוי \u0005בעיר],\u0006"],["\u0003אבל איתיה במתא\u0004 \u0005[\u0006כש\u0005ישנו בעיר]\u0006 — \u0003לא\u0004 מנדים אותו, משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 שמא \u0003אימר\u0004 \u0005[אמירה]\u0006 \u0003לא אמרו ליה\u0004 \u0005[לו],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 בליבם: כבר \u0003אשכחינהו שליחא\u0004 \u0005[מצא אותו שליח]\u0006 \u0003בית דין ואמר ליה\u0004 \u0005[לו]\u0006 ולכן הם לא אמרו.","\u0003ו\u0004כן \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שסומכים על אשה או שכן, ומנדים על סמך זה, \u0003אלא\u0004 כש\u0003לא חליף אבבא דבי דינא\u0004 \u0005[עובר על פתח בית הדין]\u0006 בדרכו לביתו, \u0003אבל\u0004 אם הוא \u0003חליף אבבא דבי דינא\u0004 \u0005[עובר על פתח בית הדין]\u0006 — \u0003לא\u0004 מנדים אותו, שכן \u0003אמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 בליבם: כבר \u0003אשכחוה בי דינא ואמרי ליה\u0004 \u0005[מצאוהו בית הדין ואמרו לו].\u0006","\u0003ו\u0004עוד \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא דאתי ביומיה\u0004 \u0005[\u0006כ\u0005שהוא בא ביומו],\u0006 כלומר, בכל יום לביתו, \u0003אבל\u0004 אם \u0003לא אתי ביומיה\u0004 \u0005[בא ביומו]\u0006 — \u0003לא,\u0004 אין מנדים אותו, \u0003אימא\u0004 \u0005[אמור]\u0006 שמא \u0003אישתלויי אשתלי\u0004 \u0005[שכחו\u0006 לומר לו\u0005].\u0006","\u0003אמר רבא: האי מאן דכתיב עליה פתיחא\u0004 \u0005[מי שכתבו עליו\u0006 כתב \u0005פתיחה\u0006 של נידוי\u0005]\u0006 \u0003על\u0004 ש\u0003לא אתי לדינא\u0004 \u0005[בא לדין]\u0006 — \u0003עד דאתי לדינא לא מקרעינן ליה\u0004 \u0005[ש\u0006הוא \u0005בא לדין אין אנו קורעים אותו].\u0006 ואם כתבו עליו שטר נידוי \u0003על\u0004 ש\u0003לא ציית לדינא\u0004 \u0005[לדין]\u0006 — \u0003עד דציית לא מקרעינן ליה\u0004 \u0005[ש\u0006הוא \u0005מציית\u0006 ועושה ממש כפסק הדין \u0005אין אנו קורעים אותו].\u0006 ומעירים: \u0003ולא היא\u0004 (אין הדבר כן), אלא \u0003כיון דאמר \"צייתנא\"\u0004 \u0005[ש\u0006הוא \u0005אומר \"אני מציית\"]\u0006 — מיד \u0003קרעינן ליה\u0004 \u0005[אנו קורעים אותו].\u0006","\u0003אמר רב חסדא: קובעים זמן\u0004 לאדם שיבוא לבית הדין, שלוש פעמים: בימים \u0003שני וחמישי ושני, זמנא וזמנא בתר זמנא\u0004 \u0005[פעם ופעם אחר פעם]\u0006 מזמינים אותו, \u0003ולמחר,\u0004 למחרת הפעם השלישית שלא בא, \u0003כתבינן\u0004 \u0005[כותבים אנו]\u0006 כתב נידוי (\"פתיחא\").","מסופר: \u0003רב אסי איקלע בי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב כהנא. חזא ההיא איתתא דאזמנה לדינא בפניא\u0004 \u0005[ראה אישה אחת שהזמין אותה לדין בערב]\u0006 ולא באה לפניו לדין, \u0003ובצפרא כתיב עלה פתיחא\u0004 \u0005[ובבוקר\u0006 שלמחרת \u0005כתב עליה כתב נידוי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אסי לרב כהנא: האם \u0003לא סבר לה מר להא\u0004 \u0005[סבור אדוני את\u0006 ההלכה \u0005הזו]\u0006 ש\u0003אמר רב חסדא: קובעים זמן שני וחמישי ושני?\u0004 ואיך אם כן כתבת עליה כתב נידוי מיד בבוקר המחרת?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003הני מילי גברא, דאניס וליתיה במתא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא ב\u0005איש, ש\u0006הוא \u0005אנוס\u0006 בעבודתו \u0005ואינו מצוי בעיר],\u0006 \u0003אבל איתתא\u0004 \u0005[אישה],\u0006 \u0003כיון דאיתה במתא ולא אתיא\u0004 \u0005[ש\u0006היא \u0005נמצאת בעיר ואינה באה]\u0006 — \u0003מורדת היא,\u0004 ולכן אפשר לכתוב עליה מיד.","ובענין זה של קביעת זמן לדין \u0003אמר רב יהודה: לא יהבינא זמנא\u0004 \u0005[אין אנו קובעים זמן]\u0006 לדין \u0003לא ביומי\u0004 \u0005[בימי]\u0006 \u0003ניסן ולא ביומי\u0004 \u0005[בימי]\u0006 \u0003תשרי,\u0004 שהטירדה בהם מרובה, ומאותה סיבה גם \u0003לא\u0004 קובעים זמן לדין \u0003במעלי יומא טבא\u0004 \u0005[בערב יום טוב]\u0006 \u0003ולא במעלי שבתא\u0004 \u0005[בערב שבת].\u0006 \u0003אבל מניסן לבתר יומי\u0004 \u0005[לאחר ימי]\u0006 \u0003ניסן,\u0004 \u0003וביומי\u0004 \u0005[ובימי]\u0006 \u0003תשרי לבתר\u0004 \u0005[לאחר]\u0006 \u0003תשרי\u0004 — \u0003קבעינן\u0004 \u0005[קובעים אנו]\u0006 דין. ואולם \u0003ממעלי שבתא לבתר מעלי שבתא לא קבעינן\u0004 \u0005[מערב שבת לאחר ערב שבת אין אנו קובעים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003בעבידתיה דשבתא טריד\u0004 \u0005[בעבודתו של שבת\u0006 הוא \u0005טרוד]\u0006 ושמא ישכח.","\u0003אמר רב נחמן: לא יהבינן זמנא\u0004 \u0005[אין אנו קובעים זמן]\u0006 לדין \u0003לא לבני כלה\u0004 שבאים ללמוד \u0003ב\u0004ירחי \u0003כלה\u0004 \u0003ולא לבני ריגלא\u0004 \u0005[לאלה שבאים לשמוע\u0006 את \u0005דרשת הרגל]\u0006 \u0003בריגלא\u0004 \u0005[ברגל].\u0006 ומסופר: \u0003כי הוו אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003רב נחמן\u0004 בזמן הכלה והיו רוצים לתבוע בעלי דינים לדין, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003וכי לדידכו כנופייכו\u0004 \u0005[בשבילכם הקהלתי אתכם]\u0006 כדי לסייע לכם בדין? הרי ללמוד תורה הקהלתי אתכם! ומעירים: \u0003והאידנא דאיכא רמאי\u0004 \u0005[ובזמן הזה שיש רמאים]\u0006 שבאים רק לצורך זה — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא מפני רמאות באו.","שנינו במשנה: הגוזל ומניח לפני בניו את הגזילה, \u0003אם היה דבר שיש בו אחריות\u0004 — \u0003חייב\u0004 היורש \u0003לשלם. מתני ליה\u0004 \u0005[היה משנה לו,\u0006 מלמד אותו\u0005]\u0006 \u0003רבי לר' שמעון בריה\u0004 \u0005[בנו]\u0006 ומסבירו משנה זו: \u0003לא דבר שיש בו אחריות ממש,\u0004 כלומר, קרקעות דווקא, \u0003אלא אפילו פרה וחורש בה, חמור ומחמר אחריו\u0004 — \u0003חייבין להחזיר מפני כבוד אביהן,\u0004 שלא יאמרו הבריות: הרי דבר זה שנגזל על ידי פלוני, ומזכירים תמיד את חטאו.","\u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב כהנא מרב:\u0004 אם היתה זו \u0003מטה ומיסב עליה, שולחן ואוכל עליו, מהו? אמר לו\u0004 בלשון הכתוב: \u0003\"תן לחכם ויחכם עוד\"\u0004 (משלי ט, ט) כלומר, הוא הדין גם למיטה ושולחן.","\u0003אין פורטין\u0004 (מחליפים כספים) \u0003לא מ\u0004כסף הנמצא ב\u0003תיבת המוכסין\u0004 (גובי מכס), שחזקה שכסף זה שגבוהו גזל הוא, שנלקח על ידי המוכס שלא כדין, \u0003ולא מכיס\u0004 (ארנק) \u0003של גבאין\u0004 שגובים מיסים, שאף הם נוטלים ממון שלא כדין, \u0003ואין נוטלין מהם,\u0004 מתיבת המוכסים ומכיס הגבאים, \u0003צדקה\u0004 מפני שכסף זה הוא כסף של גזל, \u0003אבל נוטל הוא מתוך ביתו\u0004 של המוכס \u0003או מן השוק,\u0004 מכסף אחר שלו שאינו בתיבת המוכסים.","ועוד בענין זה ששנינו במשנה. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: אף שאין פורטים מתיבת המוכס \u0003אבל נותן לו\u0004 למוכס \u0003דינר, ונותן לו\u0004 המוכס \u0003את השאר,\u0004 כלומר, עודף.","שנינו במשנתנו: \u0003ומוכסין.\u0004 מכאן משמע שכסף שנגבה על ידי המוכסים דינו ככסף גזול. ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: דינא דמלכותא דינא\u0004 \u0005[דין המלכות דין\u0006 הוא\u0005]\u0006 וצריך לשלם את המכס, ומדוע רואים את המוכסים כגזלנים, והרי הם גובים במצות המלכות?","\u0003אמר רב חנינא בר כהנא אמר שמואל:\u0004 מדובר כאן \u0003במוכס שאין לו קצבה,\u0004 שלא קצב המלך סכום מסויים כמה לשלם, אלא הוא לוקח כמה שרוצה. חכמים \u0003דבי\u0004 \u0005[של בית מדרשו]\u0006 של \u0003ר' ינאי אמרי\u0004 \u0005[היו אומרים]:\u0006 מדובר כאן \u0003במוכס העומד מאליו\u0004 שלא קבעתו המלכות, אלא הוא אונס אנשים לשלם לו בלא סמכות.","\u0003איכא דמתני לה אהא\u0004 \u0005[יש ששונים\u0006 את הדיון \u0005הזה על\u0006 הלכה \u0005זו],\u0006 ששנינו בענין איסור לבישת כלאיים: \u0003לא ילבש אדם כלאים אפילו על גבי עשרה בגדים\u0004 על מנת \u0003להבריח בו את המכס,\u0004 להסתיר את הבגד מן המכס. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 זו היא ש\u0003לא כ\u0004דעת \u0003ר' עקיבא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אסור להבריח את המכס\u0004 בדרך זו של לבישת כלאיים, \u0003ר' שמעון אומר משום\u0004 \u0005[בשם ]\u0006 \u0003ר' עקיבא: מותר להבריח את המכס.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לענין כלאים בהא קמיפלגי\u0004 \u0005[ב\u0006נושא \u0005זה חלוקים\u0006 הם\u0005],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' עקיבא, \u0005סבור]:\u0006 \u0003דבר שאין מתכוין מותר,\u0004 וכיון שאינו מתכוין לצורך לבישה מותר לו לעשות זאת, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 סתם ברייתא, \u0005סבור]:\u0006 \u0003דבר שאין מתכוין אסור. אלא להבריח בו את המכס מי שרי\u0004 \u0005[האם מותר]\u0006 בכלל להבריח ממכס? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: דינא דמלכותא דינא\u0004 \u0005[דין המלכות דין\u0006 הוא\u0005]!\u0006","\u0003אמר ר' חנינא בר כהנא אמר שמואל:\u0004 מדובר כאן \u0003במוכס שאין לו קצבה.\u0004 חכמים \u0003דבי\u0004 \u0005[של בית מדרשו]\u0006 של \u0003ר' ינאי אמרי\u0004 \u0005[היו אומרים]:\u0006 מדובר כאן \u0003במוכס העומד מאליו.\u0004","\u0003ואיכא דמתני אהא\u0004 \u0005[ויש ששונים\u0006 את הדיון הזה \u0005על\u0006 ההלכה \u0005הזו]:\u0006 \u0003נודרין להרגין\u0004 (רוצחים), \u0003ולחרמין\u0004 (אנשים קשים שמחרימים נכסי אחרים), \u0003ולמוכסין,\u0004 ואומרים לכל אלו בלשון נדר על דבר מסויים — \u0003שהיא של תרומה\u0004 ולכן אסורה להם, או \u0003שהיא של בית\u0004 ה\u0003מלך\u0004 ואין גובים ממנה מוכסים, \u0003אף על פי ש\u0004באמת \u0003אינה של תרומה,\u0004 וכן \u0003אף על פי שאינה של מלך. ו\u0004שאלו: וכי מותר לעשות כן אף \u0003למוכסין? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: דינא דמלכותא דינא\u0004 \u0005[דין המלכות דין\u0006 הוא\u0005]!\u0006","\u0003אמר ר' חנינא בר כהנא אמר שמואל:\u0004 מדובר כאן \u0003במוכס שאין לו קצבה.\u0004 חכמים \u0003דבי\u0004 \u0005[של בית מדרשו]\u0006 של \u0003ר' ינאי אמרי\u0004 \u0005[היו אומרים]:\u0006 מדובר כאן \u0003במוכס העומד מאליו.\u0004","\u0003רב אשי אמר: במוכס גוי\u0004 מדובר כאן, שאין איסור לרמות אותו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ישראל וגוי שבאו לדין, אם אתה,\u0004 הדיין, \u0003יכול לזכהו\u0004 את היהודי \u0003בדיני ישראל\u0004 — \u0003זכהו ואמור לו\u0004 לגוי: \u0003כך דינינו.\u0004 אם יכול אתה לזכהו \u0003בדיני גוים\u0004 — \u0003זכהו ואמור לו: כך דינכם, ואם לאו\u0004 \u0005[לא],\u0006 שאי אפשר לזכותו לא בדיני ישראל ולא בדיני גויים — \u0003באין עליו בעקיפין\u0004 בתחבולות ובערמה עד שמזכים את היהודי, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: אין באין עליו בעקיפין, מפני קידוש השם.\u0004","ושואלים: מכאן נדייק שאף לדעת \u0003ר' עקיבא, טעמא\u0004 \u0005[הטעם]\u0006 דווקא, \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003קידוש השם, הא ליכא\u0004 \u0005[הרי\u0006 במקום ש\u0005אין]\u0006 \u0003קידוש השם\u0004 — \u0003באין\u0004 עליו בעקיפין, ויש לשאול:","\u0003ו\u0004כי \u0003גזל גוי מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' שמעון, דבר זה דרש ר' עקיבא כשבא מזפירין: מנין לגזל גוי שהוא אסור?\u0004 — \u0003תלמוד לומר\u0004 באיש עברי הנמכר לגוי כעבד: \u0003\"אחרי נמכר גאלה תהיה לו\"\u0004 (ויקרא כה, מח), לומר שיש לגאול (לקנות אותו בכסף) מידו,"],["\u0003שלא ימשכנו\u0004 בכוח \u0003ויצא\u0004. \u0003יכול יגלום\u0004 (יערים) \u0003עליו\u0004 על הגוי באיזו שהיא צורה? — \u0003תלמוד לומר: \"וחשב עם קנהו\"\u0004 (ויקרא כה, נ), כלומר, \u0003ידקדק\u0004 בחשבון מדוייק \u0003עם קונהו!\u0004","\u0003אמר רב יוסף, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמותר לגוזלו (אלמלא חילול השם), מדובר \u0003בגוי, הא\u0004 \u0005[זה]\u0006 שאסור לגוזלו מדובר \u0003בגר תושב\u0004 שצריך לנהוג בו ביושר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 איך אפשר להבדיל בין גוי ובין גר תושב, \u0003והא תרוייהו גבי הדדי כתיבי\u0004 \u0005[והרי שניהם זה ליד זה\u0006 הם \u0005כתובים]\u0006 והדין שייך בשניהם, שנאמר במדרש ההלכה הנוגע לאותה פרשה: \u0003לא לך\u0004 בלבד עתיד להימכר אותו איש שעבר על מצות שביעית, האמורה קודם לכן, \u0003אלא לגר, שנאמר:\u0004 \u0003\"\u0004ונמכר \u0003לגר\"\u0004 (ויקרא כה, מז), \u0003ולא לגר צדק אלא לגר תושב, שנאמר: \"לגר תושב\"\u0004 (ויקרא כה, מז).","\u0003\"משפחת גר\"\u0004 (ויקרא כה, מז) — \u0003זה הגוי, כשהוא אומר \"או לעקר\"\u0004 (ויקרא כה, מז) — \u0003זה הנמכר לעבודה זרה.\u0004 ועל כולם נאמר \"גאולה תהיה לו... וחשב עם קונהו\"!","\u0003אלא אמר רבא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאסור — הרי זה \u0003בגזילו\u0004 של גוי, \u0003וכאן\u0004 שמותר הדבר, אלמלא חילול השם — הרי זה \u0003בהפקעת הלוואתו\u0004 שאין בה איסור, לפי שאין הדבר כנטילת כסף ממש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 והלא בפדיון \u0003עבד עברי\u0004 שאסר ר' עקיבא להערים — \u0003הפקעת הלוואתו הוא,\u0004 שהרי העבד הוא המשכון עבור הסכום ששולם עבורו, ומדוע יהיה אסור לרמותו לדרך זו? ומשיבים: \u0003רבא\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: עבד עברי גופו קנוי\u0004 לגוי, וכאשר מוציאו מידו הרי זה כגזל ממש.","ועוד בענין זה \u0003אמר רב ביבי בר גידל אמר ר' שמעון חסידא: גזל גוי\u0004 — \u0003אסור, אבידתו\u0004 — \u0003מותרת.\u0004 ומבררים כל הלכה בפני עצמה: \u0003גזילו אסור,\u0004 ש\u0003אמר רב הונא: מנין לגזל הגוי שהוא אסור?\u0004 — \u0003שנאמר: \"ואכלת את כל העמים אשר ה' אלהיך נתן לך\"\u0004 (דברים ז, טז), \u0003בזמן שהן מסורים בידך,\u0004 במלחמת כיבוש, מותר לך לאוכלם, \u0003ולא בזמן שאינם מסורין בידך.\u0004","\u0003אבידתו מותרת,\u0004 ש\u0003אמר רב חמא בר גוריא אמר רב: מנין לאבידת הגוי שהיא מותרת?\u0004 — \u0003שנאמר\u0004 במצות השבת אבידה: \u0003\"לכל אבדת אחיך\"\u0004 (דברים כב, ג), לומר: \u0003לאחיך\u0004 ליהודי \u0003אתה מחזיר, ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחזיר לגוי.\u0004","ומקשים: \u0003ואימא הני מילי\u0004 \u0005[ואמור\u0006 כי \u0005דברים אלה]\u0006 שאינו עדיין מחוייב בדבר אמורים דווקא \u0003היכא\u0004 \u0005[במקום]\u0006 באופן ש\u0003לא אתי\u0004 \u0005[הגיעה]\u0006 עדיין האבידה \u0003לידיה, דלא מחייב לאהדורי בתרה\u0004 \u0005[לידו, שאינו צריך לחזר אחריה],\u0006 \u0003אבל היכא דאתי לידיה אימא ליהדרה\u0004 \u0005[במקום שהגיעה לידו אמור שיחזיר אותה]\u0006 לבעליה הגוי! \u0003אמר רבינא:\u0004 נאמר \u0003\"\u0004וכן תעשה לכל אבידת אחיך אשר תאבד ממנו \u0003ומצאתה\"\u0004 (דברים כב, ג) והכוונה — אבידה \u0003דאתאי לידיה\u0004 \u0005[שהגיעה לידו]\u0006 \u0003משמע\u0004. ואם כן אף במקרה שכבר באה האבידה לידו — חלה חובת השבתה רק על \"אבידת אחיך\" ולא של גוי. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' פנחס בן יאיר אומר: במקום שיש חילול השם\u0004 אם לא יחזיר, \u0003אפילו אבידתו\u0004 של גוי \u0003אסור.\u0004","ועוד פרט בעניינים אלה. \u0003אמר שמואל: טעותו\u0004 של גוי \u0003מותרת.\u0004 ומעירים: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003שמואל זבן\u0004 \u0005[קנה]\u0006 \u0003מכותי לקנא דדהבא במר דפרזלא\u0004 \u0005[כלי זהב במחיר של ברזל]\u0006 \u0003בארבע זוזי\u0004 \u0005[זוזים],\u0006 \u0003ואבלע ליה חד זוזא\u0004 \u0005[והבליע\u0006 הוסיף \u0005לו\u0006 עוד \u0005זוז אחד]\u0006 על הכסף שקנה בו, כדי שלא ירגיש שהטעהו.","ועוד מסופר: \u0003רב כהנא זבן\u0004 \u0005[קנה]\u0006 \u0003מכותי מאה ועשרים חביתא\u0004 \u0005[חביות]\u0006 \u0003במאה, ואבלע ליה חד זוזא\u0004 \u0005[והבליע לו זוז אחד],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי, דעלך קא סמיכנא\u0004 \u0005[ראה, שעליך אני סומך].\u0006 \u0003רבינא זבן\u0004 \u0003דיקלא\u0004 \u0005[קנה דקל]\u0006 \u0003הוא וכותי\u0004 אחד \u0003לצלחא\u0004 \u0005[לביקוע]\u0006 לשם עצים, ולחלוק ביניהם את גזירי העץ, \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003קדם ואייתי\u0004 \u0005[הקדם והבא]\u0006 את גזירי העץ \u0003מעיקרו\u0004 מקרוב לשורשו, ששם הוא עבה יותר. שה\u0003כותי\u0004 רק \u0003מניינא ידע\u0004 \u0005[מנין\u0006 הוא \u0005יודע]\u0006 ולא ישים לב לזה שאתה לוקח חתיכות עבות יותר.","ועוד מסופר: \u0003רב אשי הוה קאזיל באורחא\u0004 \u0005[היה מהלך בדרך],\u0006 \u0003חזא שיבשא דגופנא בפרדיסא\u0004 \u0005[ראה זמורה של גפן בפרדס]\u0006 \u0003ותלי\u0004 \u0005[ותלויים]\u0006 \u0003בה קיטופי דעינבי\u0004 \u0005[אשכולות ענבים],\u0006 \u0003אמר ליה לשמעיה\u0004 \u0005[לו לשמשו]:\u0006 \u0003זיל חזי אי\u0004 \u0005[לך תראה אם]\u0006 של ה\u0003כותי נינהו\u0004 \u0005[הם]\u0006 — \u0003אייתי\u0004 \u0005[הבא\u0006 לי\u0005],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 של \u0003ישראל נינהו\u0004 \u0005[הם]\u0006 — \u0003לא אייתי לי\u0004 \u0005[אל תביא לי].\u0006 \u0003שמע ההוא\u0004 \u0005[אותו]\u0006 \u0003כותי דהוה יתיב בפרדיסא\u0004 \u0005[שהיה יושב בפרדס],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי את ה\u0003כותי שרי\u0004 \u0005[מותר]\u0006 לגזול? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כותי שקיל דמי\u0004 \u0005[לוקח כסף]\u0006 עבור הענבים וסמכתי על כך שאשלם על הענבים, \u0003ישראל לא שקיל דמי\u0004 \u0005[אינו לוקח כסף]\u0006 ובאופן כזה איני רוצה ליטול ממה שאינו שלי.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר שמואל: דינא דמלכותא דינא\u0004 \u0005[דין המלכות דין\u0006 הוא\u0005].\u0006 \u0003אמר רבא: תדע\u0004 שכן הוא, \u0003דקטלי דיקלי וגשרי גישרי ועברינן עלייהו\u0004 \u0005[שהם,\u0006 אנשי העיר, \u0005קוצצים דקלים וגושרים\u0006 מעציהם \u0005גשרים ואנו עוברים עליהם]\u0006 ואין אנו אומרים שגזלו את העצים מבעליהם ואסור להשתמש בהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: מכאן אין ראיה. \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003משום דאייאוש להו מינייהו מרייהו\u0004 \u0005[שהתייאשו מהם בעליהם]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בתשובה לכך: \u0003אי לא דינא דמלכותא דינא היכי מייאשי\u0004 \u0005[אם אין דין המלכות דין איך מתייאשים]?\u0006","\u0003והא לא קא עבדי כדאמר מלכא\u0004 \u0005[והרי אין הם,\u0006 אנשי העיר, \u0005עושים כמו שאומר המלך],\u0006 שכן \u0003מלכא אמר\u0004 \u0005[המלך אומר]:\u0006 \u0003זילו וקטלו מכל באגי\u0004 \u0005[לכו וקצצו מכל השדות]\u0006 מעט מכל אחד, \u0003ואינהו אזלו וקטלו מחד באגא\u0004 \u0005[והם הולכים וקוצצים משדה אחד]!\u0006","ומשיבים: \u0003שלוחא דמלכא כמלכא\u0004 \u0005[שליח המלך כמלך],\u0006 \u0003ולא טרח\u0004 \u0005[טורח]\u0006 לקחת מכל שדה ושדה, \u0003ואינהו אפסיד אנפשייהו\u0004 \u0005[והם,\u0006 הבעלים של אותו שדה אחד, \u0005הפסידו לעצמם],\u0006 \u0003דאיבעי להו דאינקוט מכוליה באגי ומשקל דמי\u0004 \u0005[שהיו צריכים להחזיק מ\u0006נכסי \u0005כל\u0006 בעלי \u0005השדות ולקחת כסף]\u0006 תמורת מה שנלקח ממנו.","ובדומה לכך \u0003אמר רבא: מאן דמשתכח בבי דרי, פרע מנתא דמלכא\u0004 \u0005[מי שנמצא בגורן,\u0006 ולא בביתו, כשבאים שליחי המלך, הוא ה\u0005פורע\u0006 את \u0005מס המלך]\u0006 בשביל כולם, והרי זה בכלל דין המלכות. \u0003והני מילי שותפא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא ב\u0005שותף],\u0006 שפורע עבור שותפים האחרים, וחוזר ולוקח מהם מה ששילם עבורם. \u0003אבל אריסא\u0004 \u0005[אריס]\u0006 — \u0003אריסותיה\u0004 \u0005[אריסותו]\u0006 \u0003הוא דקא מפיק\u0004 \u0005[שהוא מוציא\u0006 מן השדה\u0005]\u0006 ואינו צריך להשתתף בתשלום הזה, והנוטל ממנו — הרי זה גזל ולא דין המלכות.","\u0003ואמר רבא: בר מתא אבר מתא מיעבט\u0004 \u0005[בן עיר על בן עיר\u0006 אחר \u0005ממשכנים\u0006 אותו\u0005]\u0006 בשביל מס שלא שילם האחר. \u0003והני מילי דברלא ארעא וכרגא דהאי שתא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005במס הקרקעות ומיסי גולגולת של שנה זו],\u0006 \u0003אבל\u0004 של \u0003שתא דחליף\u0004 \u0005[השנה שעברה],\u0006 \u0003הואיל ואפייס מלכא\u0004 \u0005[והתפייס המלך]\u0006 — \u0003חליף\u0004 \u0005[עברה\u0006 כבר\u0005],\u0006 ואין הגובה רשאי למשכן אחד עבור האחר.","\u0003ואמר רבא: הני דדיירי דרי\u0004 \u0005[אלה\u0006 הגויים \u0005שעושים דירים]\u0006 \u0003בתוך התחום\u0004 של העיר, שמזבלים שדותיהם של אנשי העיר בשכר על ידי הכנסת בהמותיהם לתוכן — \u0003אסור ליקח\u0004 (לקנות) \u0003מהן, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003משום דמערבא חיותא דמתא בהדייהו\u0004 \u0005[שמתערבות בהמות\u0006 של ישראלים בני \u0005העיר איתם]\u0006 ונמצא קונה מהם גזל.","אבל אם מדיירים \u0003חוץ לתחום\u0004 — \u0003מותר ליקח מהם,\u0004 שאין חוששים שהן של ישראל, אלא הולכים אחר הרוב. \u0003אמר רבינא: אם היו בעלים מרדפים אחריהם, אפילו חוץ לתחום\u0004 — \u0003אסור.\u0004","\u0003מכריז רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב הונא,\u0004 והיה אומר כך: \u0003דסלקין לעילא ודנחתין לתתא\u0004 \u0005[\u0006אלה \u0005שעולים למעלה ושיורדים למטה],\u0006 כלומר, העולים לארץ ישראל מבבל והבאים ממנה, כולם מסכימים בדין זה: \u0003האי בר ישראל דידע סהדותא\u0004 \u0005[בן ישראל זה שיודע עדות]\u0006 \u0003לכותי ולא תבעו מיניה\u0004 \u0005[אותו]\u0006 שיבוא להעיד, \u0003ואזל ואסהיד ליה\u0004 \u0005[והלך והעיד לו]\u0006 \u0003בדיני דכותי על ישראל חבריה\u0004 \u0005[חבירו]\u0006 — \u0003משמתינן ליה\u0004 \u0005[מנדים אנו אותו].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דאינהו מפקי ממונא\u0004 \u0005[שהם,\u0006 הגויים בדיניהם, \u0005מוציאים ממון]\u0006"],["\u0003אפומא דחד\u0004 \u0005[על פי\u0006 עד \u0005אחד]\u0006 ונמצא שהוא מפסיד שלא כדין. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כשהיה זה \u0003חד\u0004 \u0005[\u0006איש \u0005אחד],\u0006 \u0003אבל בתרי\u0004 \u0005[בשניים]\u0006 \u0003לא\u0004 — אין מנדים אותם אם העידו כנגד הישראל, שהרי כדין ישראל הם עושים, ולא הפסידוהו ממון שלא כדין. \u0003וחד נמי\u0004 \u0005[ואחד גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא בדיני\u0004 \u0003דמגיסתא\u0004 \u0005[של כפריים],\u0006 \u0003אבל\u0004 בדין הנערך \u0003בי דוואר\u0004 \u0005[בבית השלטון],\u0006 \u0003אינהו נמי חד אמומתא שדו ליה\u0004 \u0005[הם גם כן\u0006 כשיש עד \u0005אחד בשבועה מטילים עליו],\u0006 מחייבים אותו כדין תורה.","\u0003אמר רב אשי: כי הוינא בי\u0004 \u0005[כאשר הייתי בבית\u0006 המדרש\u0005]\u0006 של \u0003רב הונא\u0004 ללמוד, \u0003איבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שאלה זו: \u0003אדם חשוב דסמכי עליה כבי תרי\u0004 \u0005[שסומכים עליו\u0006 דייני הגויים \u0005כעל שניים]\u0006 מהו דינו לענין זה? וצדדי השאלה: האם כיון שהם \u0003מפקי ממונא אפומיה\u0004 \u0005[מוציאים ממון על פיו]\u0006 רשאי, \u0003ולא איבעי ליה לאסהודי\u0004 \u0005[ואינו צריך,\u0006 נאסר הדבר, \u0005להעיד\u0006 בדיני גויים\u0005].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003אדם חשוב הוא, לא מצי משתמיט להו\u0004 \u0005[אינו יכול להשתמט מהם]\u0006 \u0003ומצי לאסהודי\u0004 \u0005[ויכול להעיד]?\u0006 שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר רב אשי: האי בר ישראל דזבין ליה ארעא\u0004 \u0005[בן ישראל המוכר לו קרקע]\u0006 \u0003לגוי אמצרא דבר\u0004 \u0005[על המיצר של בן]\u0006 \u0003ישראל חבריה\u0004 \u0005[חבירו]\u0006 — \u0003משמתינן ליה\u0004 \u0005[מנדים אנו אותו].\u0006 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שהוא \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן המיצר]\u0006 שיש זכות קדימה למי שיש לו שדה על המיצר, \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003זבין\u0004 \u0005[קונה]\u0006 \u0003מגוי וזבין\u0004 \u0005[ומוכר]\u0006 \u0003לגוי,\u0004 \u0003ליכא\u0004 \u0005[אין\u0006 בהם\u0005]\u0006 \u0003משום דינא דבר מצרא\u0004 \u0005[דין בן המיצר]!\u0006","\u0003אלא דאמרינן ליה\u0004 \u0005[שאומרים אנו לו,\u0006 למוכר\u0005]\u0006 כך: \u0003ארבעית\u0004 \u0005[הרבצת]\u0006 \u0003לי אריא אמצראי\u0004 \u0005[אריה על המיצר שלי],\u0006 שעכשיו יש לי שכן גוי והוא יציק לי. ומשום כך \u0003משמתינן ליה\u0004 \u0005[מנדים אנו אותו]\u0006 \u0003עד דקביל עליה\u0004 \u0005[שיקבל עליו]\u0006 \u0003כל אונסא דאתי מחמתיה\u0004 \u0005[אונס שיבוא מחמתו]\u0006 של הגוי.","\u0003נטלו מוכסין את חמורו ונתנו לו חמור\u0004 שנטלו מישראל \u0003אחר\u0004 תמורתו, או \u0003נטלו לסטים את כסותו ונתנו לו כסות אחרת\u0004 תמורתה — \u0003הרי אלו,\u0004 מה שקיבל, \u0003שלו, מפני שהבעלים\u0004 הקודמים שלהם \u0003מתייאשין מהן. המציל\u0004 דבר מה \u0003מן הנהר או מן הגייס\u0004 (של צבא) \u0003או מן הלסטין, אם נתייאשו\u0004 ממנו \u0003הבעלים\u0004 — \u0003הרי אלו שלו. וכן נחיל של דבורים, אם נתייאשו\u0004 הבעלים ממנו — \u0003הרי אלו שלו.\u0004","ובענין זה \u0003אמר ר' יוחנן בן ברוקה: נאמנת אשה, או קטן\u0004 אף על פי שאינם כשרים בעדות, \u0003לומר: מכאן יצא נחיל זה\u0004 והוא שייך לאדם מסויים. \u0003ומהלך\u0004 אדם \u0003בתוך שדה חבירו להציל את נחילו\u0004 שהתמקם באותה שדה, \u0003ואם הזיק\u0004 בדרך הילוכו — \u0003משלם מה שהזיק, אבל לא יקוץ את סוכו\u0004 (הענף של חבירו) שעליו נמצא הנחיל \u0003על מנת ליתן\u0004 לו אחר כך \u0003את הדמים,\u0004 כלומר, את מחיר הענף. \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: אף קוצץ\u0004 את הענף של חבירו \u0003ונותן\u0004 לו \u0003את הדמים.\u0004","על המשנה שאמרו שאם המוכסים או הליסטים נתנו לו דבר תמורת דבר שנטלו ממנו הרי זה שלו, \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003אם נטל\u0004 — \u0003מחזיר לבעלים הראשונים.\u0004 ומסבירים: \u0003קסבר\u0004 \u0005[סבור\u0006 חכם זה\u0005]:\u0006 \u0003יאוש כדי\u0004 \u0005[בלבד]\u0006 \u0003לא קני\u0004 \u0005[קונה]\u0006 והחפץ אינו קנוי למוכס שגזלו, \u0003ו\u0004לכן \u0003מעיקרא באיסורא אתא לידיה\u0004 \u0005[מתחילה באיסור בא לידו]\u0006 של המקבל, ולכן לא קנהו בשינוי רשות.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שכך שנו בברייתא: \u0003אם בא להחזיר\u0004 — \u0003יחזיר לבעלים ראשונים. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003יאוש כדי\u0004 \u0005[בלבד]\u0006 \u0003קני\u0004 \u0005[קונה].\u0006 \u0003מיהו אי אמר\u0004 \u0005[\u0006ו\u0005אולם אם אומר]\u0006 המקבל: \u0003אי אפשי\u0004 \u0005[אין אני רוצה]\u0006 ליהנות \u0003בממון שאינו שלי\u0004 — \u0003מחזיר לבעלים הראשונים.\u0004","שנינו במשנה: \u0003הרי אלו שלו, מפני שהבעלים\u0004 מתייאשים מהם. \u0003אמר רב אשי: לא שנו\u0004 שבוודאי מתייאש הבעלים מיד \u0003אלא\u0004 ב\u0003ליסטים גוי, אבל ליסטים ישראל\u0004 — \u0003לא,\u0004 ומדוע? \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003למחר נקיטנא ליה בדינא\u0004 \u0005[אביא אותו בדין].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: אדרבה, איפכא מסתברא\u0004 \u0005[ההיפך מסתבר],\u0006 \u0003גוים דדייני בגיתי\u0004 \u0005[שדנים בכוח]\u0006 ויש בידם לאכוף דיניהם — \u0003לא מייאש\u0004 \u0005[מתייאש]\u0006 הנגזל, וסבור שיוכל לתבוע את הליסטים בדיניהם ולקבל בחזרה את גזילתו. אבל אם היה זה ליסטים \u0003ישראל, כיון\u0004 שבית דין של ישראל \u0003דאמרי מימר\u0004 \u0005[ש\u0006רק \u0005אומרים]\u0006 ואין בידם כוח כפייה — \u0003מייאש\u0004 \u0005[\u0006הריהו \u0005מתייאש]\u0006 מהגזל!","\u0003אלא אי איתמר, אסיפא איתמר\u0004 \u0005[אם נאמרו\u0006 הדברים הללו, \u0005על סופה\u0006 של המשנה \u0005נאמרו]:\u0006 \u0003המציל מן הגוים ומן הלסטים, אם נתייאשו הבעלים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ומכאן יש לדייק: אבל \u0003סתמא\u0004 \u0005[סתם]\u0006 שאין ידוע שנתייאשו — \u0003לא.\u0004","ועל כך אמר רב אשי: \u0003לא שנו אלא\u0004 כשהיה זה ליסטים \u0003גוי, משום דדייני בגיתי\u0004 \u0005[שדנים בכוח],\u0006 \u0003אבל\u0004 אם היה זה \u0003לסטים ישראל, כיון דאמרי מימר\u0004 \u0005[שהם\u0006 רק \u0005אומרים]\u0006 — \u0003מייאש\u0004 \u0005[מתייאש]\u0006 הנגזל, וממילא יכול אדם אחר לקחת ממנו, והרי זה שלו.","בענין זה של יאוש \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת כלים: \u0003עורות של בעל הבית,\u0004 כלומר, כשבעל העורות בעצמו מעבד אותם ומטפל בהם — \u0003מחשבה מטמאתן.\u0004 כשהוא חושב עליהם שאינו רוצה עוד לעשות בהם עיבוד נוסף — הרי הם נחשבים כדברים גמורים, וראויים לקבל טומאה.","\u0003ושל עבדן\u0004 (מעבד עורות) — \u0003אין מחשבה מטמאתן,\u0004 משום שאומנותם לעבד עורות, והם עושים את הכל לפי דעת הקונים. ושמא יהיו מן הקונים שירצו לעשות בהם עיבוד נוסף, ולכן אין הם נחשבים כדבר גמור, ואין ראויים לקבל טומאה.","עורות \u0003של גזלן\u0004 — \u0003אין מחשבה\u0004 שחשב עליהם ככלי גמור \u0003מטמאתן,\u0004 שאין הגזלן קונה את גוף החפץ שייחשב שלו לענין זה. \u0003ושל גנב\u0004 — \u0003מחשבה מטמאתן,\u0004 שאין הבעלים יודעים מי גנב מהם, ומתייאשים, ונקנה גוף החפץ לגנב.","ואילו \u0003ר' שמעון אומר: חילוף הדברים; של גזלן\u0004 שגזל בזרוע ואין מי שיעכבנו — \u0003מחשבה מטמאתן, של גנב\u0004 — \u0003אין מחשבה מטמאתן, לפי שלא נתייאשו הבעלים.\u0004","\u0003אמר עולא: מחלוקת בסתם,\u0004 שאין אנו יודעים אם התייאשו הבעלים או לא, \u0003אבל בידוע\u0004 שהתייאש — \u0003דברי הכל יאוש קני\u0004 \u0005[קונה].\u0006 \u0003רבה אמר: בידוע\u0004 שנתייאשו הבעלים \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מחלוקת,\u0004 שבמקרים אלה (כל אחד לשיטתו) אין אדם מתייאש באמת מן החפץ, אף שהוא אומר כן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: לא תיפלוג עליה\u0004 \u0005[אל תחלוק עליו],\u0006 על \u0003עולא,\u0004 \u0003דתנן במתניתין כוותיה\u0004 \u0005[ש\u0006כן \u0005שנינו במשנתנו כשיטתו].\u0006 ששנינו בה במשנה זו בענין עורות, שלדעת ר' שמעון אין מחשבת הגנב מטמאתן \u0003לפי שלא נתייאשו הבעלים,\u0004 ומכאן נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005],\u0006 משום ש\u0003לא נתייאשו הבעלים, אבל\u0004 אם \u0003נתייאשו הבעלים\u0004 — \u0003הרי אלו שלו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003אנן\u0004 \u0005[אנו]\u0006 בלשון \u0003\"לפי שאין יאוש לבעלים\" מתנינן לה\u0004 \u0005[שונים אנו אותה]\u0006 שאין הדבר תלוי באם נתייאשו, אלא בשאלה מהותית: האם יש יאוש במקרה כזה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שלנו: \u0003נטלו מוכסין חמורו\u0004 ונתנו לו חמור אחר תמורתו, נטלו ליסטים את כסותו ונתנו לו כסות אחרת — הרי אלו שלו, מפני שהבעלים מתייאשים מהן. ונברר: \u0003מני\u0004 \u0005[כ\u0006שיטת \u0005מי היא]\u0006 משנתנו?","\u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים]\u0006 — \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003גזלן,\u0004 שהמוכס — גזלן הוא, והוא קונה את הגזילה. \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' שמעון קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003גנב\u0004 שהלסטים — גנב הוא וקונה!","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003עולא\u0004 ש\u0003אמר: בידוע\u0004 שנתייאשו \u0003קני\u0004 \u0005[קונה],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לפרש שמדובר \u0003בידוע, ודברי הכל\u0004 היא.","\u0003אלא ל\u0004שיטת \u0003רבה\u0004 ש\u0003אמר: בידוע\u0004 שנתייאשו — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מחלוקת, הא מני\u0004 \u0005[זו\u0006 משנתנו כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ולא\u0004 כשיטת \u0003ר' שמעון!\u0004 ומשיבים: כאן במשנתנו שמדובר בליסטים שקונה — מדובר \u0003בלסטים\u0004 (גנב) \u0003מזויין,\u0004 שלוקח בכוח, כגזלן (אבל מתחבא מן הבריות), \u0003ו\u0004שיטת \u0003ר' שמעון היא\u0004 שלשיטתו גזלן קונה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בליסטים מזויין, אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003גזלן\u0004 ומדוע לכפול את דינו? ומשיבים: אכן, הרי זה כעין גזלן ושנה במשנה \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003גזלן,\u0004 מוכס ולסטים מזויין.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003הגנב והגזלן והאנס\u0004 (שמכריח אחרים למכור לו) — באותם הדברים שלקחו שלא כדין \u0003הקדשן הקדש, ותרומתן תרומה, ומעשרותן מעשר.\u0004","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים]\u0006 — \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003גזלן,\u0004 שלדעתם אינו קונה! \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' שמעון\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003גנב!\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003עולא\u0004 ש\u0003אמר: בידוע\u0004 שנתייאשו \u0003קני\u0004 \u0005[קונה]\u0006 — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בידוע, ודברי הכל היא. אלא ל\u0004דעת \u0003רבה\u0004 ש\u0003אמר\u0004 ש\u0003בידוע\u0004 שנתייאשו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מחלוקת, הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ולא\u0004 כשיטת \u0003ר' שמעון!\u0004","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 כאשר שנו בברייתא גנב — מדובר \u0003בלסטים מזויין, ו\u0004שיטת \u0003ר' שמעון היא.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 בדיוק \u0003גזלן!\u0004 ומשיבים: \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003גזלן\u0004 שנה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא מתניתא\u0004 \u0005[ברייתא זו]\u0006 כשיטת \u0003רבי היא,\u0004 שיש לו שיטה אחרת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אמר: גנב\u0004 דינו \u0003כגזלן,\u0004"],["\u0003וקימא לן\u0004 \u0005[ומוחזק בידינו],\u0006 כמסקנת הגמרא להלן, שכוונתו היתה שדינו \u0003כגזלן ל\u0004דעת \u0003ר' שמעון,\u0004 ואם כן לשיטתו גם גנב וגם גזלן קונים את הנכסים.","כיון שהזכרנו את דברי רבי דנים בהם עתה \u0003גופא\u0004 \u0005[לגופם].\u0006 \u0003רבי אומר, אומר אני: גנב\u0004 דינו \u0003כגזלן. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 כוונת דברי רבי: האם \u0003כגזלן דרבנן קאמר\u0004 \u0005[\u0006לשיטתם \u0005של\u0006 \u0005חכמים\u0006 בענין עורות \u0005הוא אומר],\u0006 וכוונתו — \u0003ו\u0004הוא \u0003לא קני\u0004 \u0005[קונה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כגזלן\u0004 לשיטתו של \u0003ר' שמעון קאמר\u0004 \u0005[הוא אומר]\u0006 \u0003וקני\u0004 \u0005[ו\u0006הוא \u0005קונה]?\u0006","ומציעים פתרון לשאלה זו: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003נטלו מוכסין\u0004 את \u0003חמורו\u0004 ולסטים את כסותו, ונתנו לו אחר — הרי אלו שלו, שהמוכס שהוא גזלן, והלסטים שהוא גנב — קנה את החפץ ביאוש.","ונברר: משנה זו \u0003מני\u0004 \u0005[כ\u0006שיטת \u0005מי היא]?\u0006 \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים],\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003גזלן! אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' שמעון, קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003גנב!\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003רבי כגזלן\u0004 של \u0003ר' שמעון קאמר וקני\u0004 \u0005[הוא אומר, וקונה]\u0006 הגנב ביאוש, \u0003הא מני\u0004 \u0005[זו,\u0006 משנתנו, כשיטת \u0005מי היא]?\u0006 — שיטת \u0003רבי היא,\u0004 ו\u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003קני\u0004 \u0005[קונה]\u0006 הלסטים,","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שדעתו שגנב דינו \u0003כגזלן דרבנן\u0004 \u0005[של\u0006 שיטת \u0005חכמים]\u0006 \u0003קאמר\u0004 \u0005[הוא אומר],\u0006 \u0003ולא קני\u0004 \u0005[ואינו קונה],\u0006 \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 שלסטים, שהוא גנב, קונה, שיטת \u0005מי היא]?\u0006 — \u0003לא\u0004 כשיטת \u0003רבי ולא\u0004 כשיטת \u0003ר' שמעון ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]!\u0006","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בלסטים מזויין, ו\u0004שיטת \u0003ר' שמעון היא\u0004 שגזלן קונה ביאוש. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 בדיוק \u0003גזלן?\u0004 ומשיבים: \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003גזלן\u0004 שנה במשנה.","ומציעים עוד פתרון: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת לדבר ממה ששנינו בברייתא: \u0003הגנב והגזלן והאנס\u0004 — קנו את הגזילה שבידם, ולכן \u0003הקדשן הקדש, ותרומתן תרומה, ומעשרותן מעשר.\u0004","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003גזלן\u0004 שלדעתם אינו קונה! \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' שמעון, קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003גנב\u0004 שלדעתו אינו קונה!","ומעתה: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שדין \u0003גנב כ\u0004דין \u0003גזלן\u0004 של שיטת \u0003ר' שמעון קאמר\u0004 \u0005[הוא אומר],\u0006 \u0003משום הכי קני\u0004 \u0005[משום כך קונה],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003גנב כגזלן דרבנן\u0004 \u0005[של\u0006 שיטת \u0005חכמים]\u0006 שגזלן אינו קונה, \u0003הא מני\u0004 \u0005[ברייתא זו\u0006 כדעת \u0005מי היא]?\u0006","ומשיבים: אף כאן מדובר \u0003ב\u0004גנב שהוא \u0003לסטים מזויין, ו\u0004שיטת \u0003ר' שמעון היא\u0004 שגזלן קונה. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003גזלן?\u0004 ומשיבים: \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003גזלן\u0004 שנו בברייתא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרבה: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר מדברי רבי עצמו, \u0003דמתני\u0004 \u0005[שהיה משנה,\u0006 מלמד\u0005]\u0006 \u0003רבי לר' שמעון בריה\u0004 \u0005[בנו]\u0006 בענין מה ששנינו שבמשנה שכל דבר שיש בו אחריות וגנבו האב, ומת האב, שחייבים הבנים להשיבו לבעליו מפני כבוד אביהם: \u0003לא דבר שיש בו אחריות ממש, אלא אפילו פרה וחורש בה, חמור ומחמר אחריו\u0004 — \u0003חייבין\u0004 הבנים \u0003להחזיר מפני כבוד אביהן\u0004 שגזלם.","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 בגלל הטעם של \u0003מפני כבוד אביהן, הא לאו\u0004 \u0005[הרי\u0006 אם \u0005לא]\u0006 טעם זה של \u0003כבוד אביהן\u0004 — \u0003לא\u0004 היו צריכים להחזיר מן הדין. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכוונת דברי \u0003רבי\u0004 היא שגנב דינו כ\u0003גזלן\u0004 של שיטת \u0003ר' שמעון קאמר\u0004 \u0005[אומר],\u0006 וקונה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003וכן נחיל של דבורים\u0004 אם נתייאשו הבעלים ממנו ונטלו אחר — הרי אלו שלו. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"וכן\"?\u0004 מדוע יש צורך להוסיף במשנה דוגמא זו?","ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אפילו נחיל של דבורים,\u0004 ש\u0003קנין דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 \u0003הוא,\u0004 שאין לאיש קנין מן התורה בדבורים, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003כיון דרבנן בעלמא\u0004 \u0005[ש\u0006מדברי \u0005חכמים בלבד]\u0006 \u0003הוא דקני ליה\u0004 \u0005[שקונה אותו],\u0006 \u0003אפילו סתמא נמי מייאש\u0004 \u0005[בסתם גם כן מתייאש],\u0006 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו]\u0006 משנתנו ש\u0003אם נתייאשו הבעלים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא.\u0004","עוד שנינו במשנה, ש\u0003אמר ר' יוחנן בן ברוקה: נאמנת אשה ו\u0004כן \u0003קטן\u0004 לומר: מכאן יצא נחיל זה ולכן שייך הוא לבעלי מקום זה.","ותוהים: וכי \u0003אשה וקטן בני עדות נינהו\u0004 \u0005[הם]?\u0006 והרי פסולים הם לעדות! \u0003אמר רב יהודה אמר שמואל: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהיו בעלים מרדפין אחריהם,\u0004 כלומר, אחרי הדבורים, \u0003ואשה וקטן מסיחין לפי תומם ואומר\u0004 הקטן: \u0003מכאן יצא נחיל זה.\u0004","ובענין זה מסופר ש\u0003אמר רב אשי: אין מסיח לפי תומו כשר\u0004 להעיד על כך, \u0003אלא לעדות אשה בלבד,\u0004 שתיקנו חכמים שמי שהיה מסיח לפי תומו שמת בעלה של אשה, אף על פי שהוא פסול לגמרי לעדות, כגון גוי, יהא נאמן, אבל לדבר אחר לא תיקנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ו\u0004האם \u0003לא\u0004 סומכים גם בדברים אחרים? \u0003והרי נחיל של דבורים מסיח לפי תומו הוא\u0004 ואשה וקטן נאמנים! ענה לו: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003נחיל של דבורים,\u0004 ש\u0003קנין דרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים]\u0006 \u0003הוא\u0004 מעיקרו, ולכן סמכו חכמים גם על אלה.","ושואלים: \u0003ודאורייתא\u0004 \u0005[ו\u0006בדבר \u0005שמן התורה]\u0006 \u0003לא? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל: מעשה באדם אחד שהיה מסיח לפי תומו ואומר: זכורני כשאני תינוק ומורכבני\u0004 (הייתי מורכב) \u0003על כתיפו של אבא, והוציאוני מבית הספר והפשיטוני את כתנתי והטבילוני לאכול בתרומה לערב,\u0004","\u0003ור' חנינא\u0004 היה \u0003מסיים בה\u0004 בהרצאת דבריו \u0003הכי\u0004 \u0005[כך]:\u0006 שאותו אדם הוסיף וסיפר \u0003וחבירי\u0004 היו \u0003בדילין\u0004 (נבדלים) \u0003ממני,\u0004 \u0003והיו קורין אותי \"יוחנן אוכל חלות\", והעלהו רבי לכהונה על פיו.\u0004 ואם כן, הרי שהעלהו לכהונה, והתיר לו לאכול תרומה שהיא מן התורה, על סמך סיפור שסיפר לפי תומו!","ענה לו רב אשי: מדובר פה \u0003בתרומה דרבנן\u0004 \u0005[שמ\u0006 דברי \u0005חכמים]\u0006 שבזמן הזה, לאחר חורבן, אבל בדין תורה אין סומכים על מסיח לפי תומו.","ושואלים עוד: \u0003ואכתי דאורייתא\u0004 \u0005[ועדיין\u0006 בדברים \u0005שמן התורה]\u0006 \u0003לא? והא\u0004 \u0005[והרי]\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר רב חנא קרטיגנא\u0004 (מקרטגו), \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בנוסח זה: \u0003רב אחא קרטיגנא משתעי\u0004 \u0005[היה מספר]:\u0006 \u0003מעשה בא לפני ר' יהושע בן לוי ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 ש\u0003מעשה\u0004 זה \u0003בא לפני רבי, בתינוק אחד שהיה מסיח לפי תומו ואמר: אני ואמי נשבינו לבין הגוים, יצאתי לשאוב מים\u0004 — \u0003דעתי\u0004 היתה באותה שעה \u0003על אמי, ללקוט עצים\u0004 — \u0003דעתי על אמי,\u0004 משמע שהיה עם אימו כל הזמן, ולא נבעלה לגוי ונפסלה בכך לכהונה,","\u0003והשיאה רבי על פיו לכהונה.\u0004 ואם כן סומכים על כך אפילו בדבר שיש בו צד איסור מן התורה!","ומשיבים: \u0003בשבויה הקילו,\u0004 שכיון שאין איסורה ברור, אלא רק חשש חכמים הוא, לכן הקלו בכך.","שנינו במשנה: \u0003אבל לא יקוץ את סוכו\u0004 של חבירו כדי להציל את הנחיל שלו שנמצא עליו, ואף לא על מנת ליתן לו את הדמים. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: תנאי בית דין הוא, שיהא\u0004 אדם \u0003יורד לתוך שדה של חבירו וקוצץ סוכו\u0004 (ענפו) \u0003של חבירו\u0004 כדי \u0003להציל\u0004 בכך \u0003את נחילו, ונוטל\u0004 בעל השדה \u0003דמי סוכו מתוך נחילו של חבירו. ו\u0004כן","\u0003תנאי בית דין הוא, שיהא\u0004 אדם שרואה חבית דבש של חבירו נשברת \u0003שופך\u0004 את \u0003יינו\u0004 מן החבית שלו \u0003ומציל\u0004 לתוכה \u0003את דובשנו של חבירו,\u0004 שדבר יקר הוא בהרבה מן היין, \u0003ונוטל דמי יינו מתוך דובשנו של חבירו. ו\u0004כן \u0003תנאי בית דין הוא, שיהא\u0004 אדם \u0003מפרק את עציו\u0004 שהוא נושא על חמורו \u0003וטוען\u0004 במקומם את \u0003פשתנו של חבירו\u0004 שחמורו נפל, \u0003ונוטל דמי עציו מתוך פשתנו של חבירו, שעל מנת כן\u0004 שיעשו דברים אלה אף שאינם בעצם מן הדין, \u0003הנחיל יהושע לישראל את הארץ.\u0004","\u0003המכיר כליו\u0004 \u0003ו\u0004כן \u0003ספריו ביד אחר, ויצא לו שם גניבה בעיר,\u0004 כלומר, יצאה שמועה קודם לכן שנגנבו מאיתו דברים אלה — \u0003ישבע לו לוקח\u0004 (הקונה שקנה אותם מן הגנב ומחזיק כעת בכלים או בספרים) \u0003כמה נתן\u0004 (שילם) בעד אלה \u0003ויטול\u0004 ממנו, מבעל הכלים או הספרים את מה ששילם, ויחזיר את הכלים או הספרים לבעליהם. \u0003ואם לאו\u0004 \u0005[לא]\u0006 יצא לו שם גניבה — \u0003לאו כל המנו\u0004 (אין זה בכוחו) לטעון שחפץ זה נגנב ממנו, וליטול אותו (ואף בתשלום), אף שיכול להוכיח שהחפץ היה פעם שלו, \u0003שאני אומר:\u0004 שמא \u0003מכרן לאחר ולקחן\u0004 (קנאם) \u0003זה\u0004 (המחזיק בספרים) \u0003הימנו\u0004 (ממנו), מאותו אדם שקנה אותם מבעליהם.","ושואלים על השנוי במשנתנו: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003יצא לו שם גניבה בעיר מאי הוי\u0004 \u0005[מה היה\u0006 בכך\u0005]?\u0006 \u0003ליחוש דילמא זבנינהו\u0004 \u0005[נחשוש שמא\u0006 הוא עצמו \u0005מכר אותם],\u0006 \u0003והוא ניהו קא מפיק שמא\u0004 \u0005[זה שמוציא את השם]\u0006 שהיתה גניבה כדי לקבל את ספריו!","\u0003אמר רב יהודה אמר רב: כגון שבאו בני אדם בתוך ביתו, ועמד והפגין\u0004 (וצעק) \u0003בלילה, ואמר: נגנבו כליי.\u0004 ואומרים: \u0003כל שכן עילא\u0004 (תואנה) \u0003מצא\u0004 שמצא לעצמו עילה טובה יותר להיתלות באנשים אלה, ולטעון טענת גניבה שלא כדין!","\u0003רב כהנא\u0004 היה \u0003מסיים בה\u0004 בהלכה זו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 מדובר כאן \u0003כגון שהיתה מחתרת חתורה בתוך ביתו, ובני אדם שלנו בתוך ביתו יצאו ואנבורקראות\u0004 (חבילות) \u0003של כלים על כתפיהם, והכל אומרים \"נגנבו כליו של פלוני\",\u0004 ואין אנו סומכים על צעקותיו וטענותיו.","ושואלים: אף שאנשים כך אומרים \"נגנבו כליו של פלוני\" מדוע נאמין לו גם על גניבת הספרים? \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003כלים\u0004 בלבד \u0003הוו\u0004 \u0005[היו],\u0006 \u0003ספרים לא הוו\u0004 \u0005[היו שם]\u0006 בתוך מה שגנבו ממנו! \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כגון דקאמרי נמי\u0004 \u0005[ש\u0006הכל \u0005אומרים גם כן]\u0006 ש\u0003ספרים\u0004 נגנבו לו.","ושואלים: \u0003וליחוש דלמא זוטרי\u0004 \u0005[ונחשוש שמא\u0006 נגנבו ספרים \u0005קטנים],\u0006 \u0003וקא טעין רברבי\u0004 \u0005[והוא טוען בגדולים],\u0006 כלומר, על ספרים אחרים! \u0003אמר ר' יוסי בר חנינא: דקאמרי\u0004 \u0005[שאומרים]\u0006 \u0003ספר פלוני ופלוני\u0004 נגנבו, שנוקב בשמות הספרים שאכן היו באותן חבילות שנלקחו מביתו.","ושואלים: \u0003ודלמא הוו עתיקי\u0004 \u0005[ושמא היו\u0006 ספרים אלה \u0005ישנים]\u0006 שהם זולים יותר, \u0003וקא טעין חדתי\u0004 \u0005[והוא טוען\u0006 על ספרים \u0005חדשים]\u0006 שהם יקרים יותר! \u0003אמר רב: כגון דאמרי\u0004 \u0005[שאומרים\u0006 אנשים\u0005]\u0006 במפורש \u0003\"הללו כליו של פלוני, הללו ספריו של פלוני\".\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]\u0006 כפי שמסר בשמו רב כהנא? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב\u0004 עצמו: מי ש\u0003בא במחתרת ונטל כלים ויצא\u0004 — \u0003פטור\u0004 מלשלם. \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 — \u0003בדמי קננהו\u0004 \u0005[בדם קנה אותם]\u0006 שהרי בעל הבית רשאי להרוג את הגונב במחתרת, ואם לא נהרג — אין מענישים אותו עונש אחר, ואם הגנב עצמו פטור מלהחזיר את הכלי, כיצד נוכל לחייב את הקונה ממנו לעשות זאת?","ומשיבים: \u0003הני מילי דקננהו\u0004 \u0005[דברים אלה\u0006 אמורים \u0005שקנה אותם]\u0006 \u0003ב\u0004גנב ה\u0003בא במחתרת, דמעיקרא מסר נפשיה לקטלא\u0004 \u0005[שמתחילה מוסר את עצמו למיתה\u0006 עליהם\u0005],\u0006 \u0003אבל הני\u0004 \u0005[אלה]\u0006 \u0003כיון\u0004 ש\u0003לא מסרו נפשייהו לקטלא\u0004 \u0005[עצמם למיתה],\u0006 שהרי לא חתרו מתחילה, אלא באו כאוהבים לביתו ולנו שם אצלו — \u0003לא.\u0004","\u0003אמר רבא: לא שנו\u0004 שזקוק בעל הבית לכל ההוכחות הללו, \u0003אלא\u0004 ב\u0003בעל הבית העשוי\u0004 המסוגל \u0003למכור\u0004 את \u0003כליו,\u0004 שצריך להוכיח שנגנבו, \u0003אבל בעל הבית שאינו עשוי למכור\u0004 את \u0003כליו\u0004 —"],["\u0003לא צריך לאהדורי עליה כולי האי\u0004 \u0005[לחזר עליו כל זאת]\u0006 ולדקדק בכל הפרטים וההוכחות הללו.","ושואלים: ומדוע? \u0003ודלמא איצטריך ליה זוזי וזבין\u0004 \u0005[ושמא הצטרכו לו כספים ומכר]\u0006 בכל זאת, למרות שאינו רגיל בכך! \u0003אמר רב אשי: הרי יצא לו שם גניבה בעיר,\u0004 ועל כך בעיקר אנו סומכים.","ועוד בענין זה הנזכר במשנה \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003גנב ומכר\u0004 את החפצים שגנב לאחר, \u0003ואחר כך הוכר הגנב\u0004 שנודע מי הוא, נחלקו חכמים עם מי מתדיין הבעלים, האם עם הגנב או עם הקונה. \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' חייא אמר: הדין\u0004 (ההתדיינות) של הבעלים שנגנב ממנו החפץ, הוא \u0003עם הראשון,\u0004 כלומר, עם הגנב, וממנו הוא תובע את הגניבה, ולא עם הקונה מהגנב. \u0003ר' יוחנן משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' ינאי אמר: הדין עם השני,\u0004 כלומר, עם הקונה.","\u0003אמר רב יוסף: לא פליגי\u0004 \u0005[נחלקו]\u0006 בעצם ההלכה, אלא שדברו במקרים שונים: \u0003כאן\u0004 בדברי ר' יוחנן מדובר \u0003לפני יאוש\u0004 הבעלים — \u0003הדין\u0004 של הבעלים הוא \u0003עם השני,\u0004 שהרי החפץ שלו הוא עדיין. \u0003כאן\u0004 בדברי רב מדובר \u0003לאחר יאוש\u0004 — \u0003הדין\u0004 של הבעלים הוא \u0003עם הראשון.\u0004","\u0003ותרוייהו אית להו\u0004 \u0005[ושניהם,\u0006 רב ור' יוחנן, \u0005יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003רב חסדא,\u0004 שאם גזל ולא נתייאשו הבעלים, ובא אחר ונטל את החפץ מן הגזלן — יכול לגבות ממי שירצה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ו\u0004האם \u0003לא\u0004 \u0003פליגי\u0004 \u0005[נחלקו]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מתנות כהונה כלפני יאוש דמי\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 \u0003ופליגי\u0004 \u0005[ונחלקו]\u0006 באותו ענין, שרב סבור שדינו עם הראשון! \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר לו\u0004 לטבח \u0003\"מכור לי מעיה של פרה\", והיו בהן מתנות\u0004 כהונה, שהרי חלק מהמעיים הוא הקיבה, שהיא מתנה הניתנת לכהן מכל בהמת חולין — \u0003נותנן\u0004 את המתנות \u0003לכהן, ואינו מנכה לו\u0004 למוכר הבהמה \u0003מן הדמים\u0004 ששילם לו את שווי הקיבה. אם \u0003לקח\u0004 (קנה) \u0003הימנו\u0004 (ממנו) את המעיים \u0003במשקל\u0004 — אמנם \u0003נותנו לכהן\u0004 את מה שמגיע לו, \u0003ו\u0004אולם \u0003מנכה לו\u0004 למוכר \u0003מן הדמים.\u0004","\u0003ואמר\u0004 על זה \u0003רב: לא שנו\u0004 שנותן לכהן, ואינו מנכה לטבח מן הדמים \u0003אלא ששקל לעצמו\u0004 את בני המעיים. שכיון שהוא עצמו נטל את בני המעיים הרי הוא החייב לכהן, \u0003אבל\u0004 אם \u0003שקל לו הטבח\u0004 שנמצא אז שהטבח הוא שנטל את המתנות — \u0003הדין\u0004 של הכהן הוא \u0003עם הטבח.\u0004 משמע שאף במתנות כהונה, שאין הכהן מתייאש מהן, ודינן כגזילה לפני יאוש, סבור רב שהדין הוא עם הראשון דווקא!","ודוחים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אף דין עם הטבח,\u0004 כלומר, אמור שבמקרה כזה הדין גם עם הטבח אם ירצה הכהן להתדיין איתו. והחידוש בדבר הוא, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אין מתנות כהונה נגזלות,\u0004 וכאילו לא עשה הטבח דבר במה שמסרן לקונה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיש בהן דין גזילה.","ושואלים: \u0003ול\u0004שיטת \u0003אביי\u0004 ש\u0003אמר: פליגי\u0004 \u0005[נחלקו]\u0006 רב ור' יוחנן, \u0003במאי פליגי\u0004 \u0005[במה\u0006 באיזה ענין \u0005נחלקו]?\u0006 ומשיבים: הם חולקים \u0003ב\u0004דברי \u0003רב חסדא,\u0004 האם לקבל את שיטתו או לא. שלדעת רב אף לפני יאוש — אין דינו של הבעלים אלא עם הגזלן.","\u0003רב זביד אמר:\u0004 אם לפני יאוש — לדעת כולם יכול הבעלים לדון עם הלוקח, ולהוציא מידו את החפץ, ובמה נחלקו? — \u0003כגון שנתייאשו הבעלים\u0004 אלא שנתייאשו משעה שהיו החפצים \u0003ביד\u0004 ה\u0003לוקח, ולא נתייאשו\u0004 כשהיו עדיין \u0003ביד\u0004 ה\u0003גנב,\u0004","\u0003ובהא פליגי\u0004 \u0005[וב\u0006נושא \u0005זה נחלקו],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]:\u0006 \u0003יאוש ואחר כך שינוי רשות\u0004 — \u0003קני\u0004 \u0005[קונה]\u0006 הלוקח. אבל \u0003שינוי רשות ואחר כך יאוש\u0004 — \u0003לא קני\u0004 \u0005[קונה],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 ובכל מקרה הוא קונה.","\u0003רב פפא אמר: בגלימא\u0004 שנגנבה \u0003דכולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 \u0003דהדר למריה\u0004 \u0005[שחוזר לבעליו],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003עשו בו\u0004 בלוקח, במקרה שהוכר הגנב \u0003תקנת השוק קמיפלגי\u0004 \u0005[חלוקים\u0006 \u0005הם]:\u0006","האם גם כאן תיקנו שהקונה בתום לב מן הגנב מקבל מן הבעלים את הכסף ששילם לגנב, כשמחזיר את החפץ, \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' חייא אמר: הדין עם הראשון, דינא\u0004 \u0005[הדין]\u0006 שה\u0003לוקח דלישקול זוזי\u0004 \u0005[יקח את הכסף]\u0006 מן ה\u0003גנב,\u0004 \u0003ולא עשו בו תקנת השוק\u0004 שיטול מן הבעלים. \u0003ור' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' ינאי אמר: הדין עם השני\u0004 — \u0003דינא\u0004 \u0005[הדין]\u0006 של ה\u0003לוקח דלישקול\u0004 \u0005[שיטול]\u0006 \u0003מבעל הבית\u0004 את כספו, \u0003ועשו בו תקנת השוק.\u0004","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003רב\u0004 ש\u0003לא עשו בו תקנת השוק? והא\u0004 \u0005[והרי]\u0006 \u0003רב הונא תלמידיה\u0004 \u0005[תלמידו]\u0006 של \u0003רב הוה\u0004 \u0005[היה],\u0006 \u0003ו\u0004מסופר שאדם אחד שמפני רשעותו היה נקרא \u0003חנן בישא\u0004 \u0005[הרע],\u0006 \u0003גנב גלימא וזבנה\u0004 \u0005[ומכר אותה],\u0006 ונודע אחר כך שחנן בישא הוא הגנב. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב הונא, אמר ליה לההוא גברא\u0004 \u0005[לו לאותו אדם]\u0006 שנגנב לו: \u0003זיל שרי עביטך\u0004 \u0005[לך פדה\u0006 את \u0005משכונך],\u0006 כלומר, שלם לקונה מה שנתן לגנב, ואז תקבל את שלך!","ומשיבים: אין מכאן ראיה, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003חנן בישא\u0004 \u0005[הרע],\u0006 \u0003כיון דליכא לאישתלומי מיניה\u0004 \u0005[שאי אפשר לקבל תשלומים ממנו],\u0006 שלא היה לו כסף, הרי זה \u0003כ\u0004גנב ש\u0003לא הוכר דמי\u0004 \u0005[נחשב].\u0006","ובענין זה של תקנת השוק \u0003אמר רבא: אם גנב מפורסם הוא, לא עשו בו תקנת השוק.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חנן בישא\u0004 \u0005[הרע]\u0006 ש\u0003מפורסם הוה\u0004 \u0005[היה]\u0006 \u0003ו\u0004בכל זאת \u0003עשו בו תקנת השוק!\u0004 ומשיבים: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003מפורסם\u0004 היה \u0003לבישותא\u0004 \u0005[לרוע],\u0006 אבל \u0003לגניבותא\u0004 \u0005[לגניבה]\u0006 \u0003לא\u0004 היה \u0003מפורסם,\u0004 ולכן אינו נכנס בכלל זה.","ועוד בענין תקנת השוק. \u0003איתמר\u0004 \u0005[נאמר]:\u0006 מי ש\u0003גנב ופרע\u0004 מן הגניבה את \u0003חובו,\u0004 שהיה חייב למי שהלווהו קודם לכן, או \u0003גנב ופרע בהיקיפו,\u0004 שקנה דבר מה בהקפה, ושילם בחפץ הגנוב — \u0003לא עשו בו תקנת השוק\u0004 לתת תמורתם למלווה או למי שנתן לו בהקפה, \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 לו: \u0003לא אדעתא דהנהו יהיבת ליה מידי\u0004 \u0005[על דעת\u0006 הדברים \u0005האלה\u0006 הגנובים \u0005נתת לו\u0006 \u0005דבר],\u0006 שהרי האמנת לו מקודם ונתת לו בהלוואה או בהקפה, ולכן אפשר לקחת את החפץ מידך, וגבה את חובך ממנו באופן אחר.","ועוד בענין תקנת השוק: אם נתן הגנב את הגניבה כ\u0003משכנתא\u0004 \u0005[משכון\u0006 כנגד הלוואה\u0005],\u0006 וקיבל עבור החפץ הגנוב שהוא \u0003שוי מאתן\u0004 \u0005[שווה מאתיים]\u0006 \u0003במאה,\u0004 כלומר, הלוואה בגובה מחצית ערך המשכון — \u0003עשו בו תקנת השוק,\u0004 אבל אם היה זה \u0003שוה בשוה\u0004 — נחלקו בדבר חכמים, \u0003אמימר אמר: לא עשו בו תקנת השוק,\u0004 שאין רגילים אנשים להלוות סכום כסף בשוויה של המשכנתא אלא פחות מזה, ולכן מה שהלוה לגנב אינו בגלל החפץ הגנוב אלא מטעם אחר. \u0003מר זוטרא אמר: עשו בו תקנת השוק.\u0004","ואומרים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003עשו בו תקנת השוק.\u0004","במקרה של \u0003זבינא\u0004 \u0005[מכר]\u0006 הרי אם היה \u0003שוה בשוה\u0004 — \u0003עשו בו תקנת השוק,\u0004 אבל אם מכר \u0003שוה מאה,\u0004 שהיה שווה החפץ הגנוב מאה דינרים, \u0003במאתן\u0004 \u0005[במאתיים],\u0006 ערך המכירה — \u0003רב ששת אמר: לא עשו בו תקנת השוק, רבא אמר: עשו בו תקנת השוק.\u0004","\u0003והלכתא\u0004 \u0005[וההלכה\u0006 היא\u0005]:\u0006 \u0003בכולהו\u0004 \u0005[בכולם]\u0006 \u0003עשו בו תקנת השוק, לבר\u0004 \u0005[חוץ]\u0006 מהמקרה ש\u0003גנב ופרע בחובו,\u0004 או ש\u0003גנב ופרע בהיקיפו.\u0004","מסופר: \u0003אבימי בר נאזי חמוה\u0004 \u0005[חמיו]\u0006 של \u0003רבינא הוה מסיק בההוא גברא\u0004 \u0005[היה נושה באדם אחד]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים].\u0006 \u0003גנב\u0004 אותו אדם \u0003גלימא אתיא ניהליה\u0004 \u0005[\u0006ו\u0005הביא לו]\u0006 כפרעון חובו, \u0003אוזפיה\u0004 \u0005[הלווה לו]\u0006 אבימי \u0003ארבעה זוזי אחריני\u0004 \u0005[זוזים אחרים].\u0006 \u0003לסוף הוכר הגנב. אתא לקמיה\u0004 \u0005[בא\u0006 בעל החפץ הגנוב \u0005לפני]\u0006","\u0003רבינא, אמר\u0004 לו: \u0003קמאי\u0004 \u0005[\u0006על הזוזים \u0005הראשונים]\u0006 הרי הוא בגדר \u0003גנב ופרע בחובו, ולא בעי למיתב ליה\u0004 \u0005[צריך לתת לו]\u0006 לאבימי חותני \u0003ולא מידי\u0004 \u0005[\u0006\u0005דבר],\u0006 ולחותנו אמר: \u0003הנך\u0004 \u0005[אותם]\u0006 \u0003ארבעה זוזי אחריני\u0004 \u0005[זוזים אחרים]\u0006 שנתת לגנב על סמך אותה גלימה שהביא לך — \u0003שקול זוזך והדר גלימי\u0004 \u0005[קח\u0006 את \u0005כספך והחזר\u0006 את \u0005הגלימה].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב כהן: ודלמא גלימא בהני זוזי קמאי יהבה ניהליה\u0004 \u0005[ושמא הגלימה בעד אלה\u0006 ארבעת \u0005הזוזים הראשונים נתן לו],\u0006 והרי זה, כדברי רבינא, \u0003גנב ופרע בחובו גנב ופרע בהיקיפו, ו\u0004אולם \u0003ארבעה זוזי בתראי\u0004 \u0005[זוזים אחרונים]\u0006 \u0003הימוני הימניה\u0004 \u0005[האמין לו],\u0006 ונתנם לו בהלואה בלי קשר לגניבה, \u0003כי היכי דהימניה מעיקרא\u0004 \u0005[כמו שהאמין לו מההתחלה]\u0006 לפני שהביא לו את הגלימה, ונמצא שאין הבעלים צריך לשלם לו דבר! \u0003איגלגל מילתא\u0004 \u0005[התגלגל הדבר]\u0006 בין חכמים שונים, \u0003מטא לקמיה\u0004 \u0005[בא\u0006 הדבר הזה \u0005לפני]\u0006 \u0003ר' אבהו, אמר: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב כהן.\u0004","מסופר: \u0003נרשאה\u0004 \u0005[איש מ\u0006המקום \u0005נרש]\u0006 \u0003גנב ספרא\u0004 \u0005[ספר],\u0006 \u0003זבניה לפפונאה בתמנן זוזי\u0004 \u0005[\u0006ו\u0005מכר אותו לאיש מפפוניא בשמונים זוז],\u0006 \u0003אזל פפונאה זבניה לבר מחוזאה במאה ועשרין זוזי\u0004 \u0005[הלך האיש מפפוניא\u0006 ו\u0005מכר אותו לבן מחוזא במאה ועשרים זוז],\u0006 \u0003לסוף הוכר הגנב, אמר אביי: ליזיל מרי דספרא\u0004 \u0005[שילך בעל הספר]\u0006 \u0003ויהב ליה לבר מחוזא תמנן זוזי ושקיל ספריה\u0004 \u0005[ויתן לבן מחוזא שמונים זוז ויקח את ספרו],\u0006 \u0003ואזיל בר מחוזאה ושקיל ארבעין מפפונאה\u0004 \u0005[וילך בן מחוזא ויקח ארבעים מבן פפוניא].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003לוקח מגנב עשו בו תקנת השוק, לוקח מלוקח\u0004 שלא התעסק כלל עם הגנב \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","\u0003אלא אמר רבא:\u0004 כך יעשה: \u0003ליזיל מריה דספרא ויהיב ליה לבר מחוזאה מאה ועשרין זוזי\u0004 \u0005[שילך בעל הספר ויתן לו לבן מחוזא מאה ועשרים זוז\u0006 ששילם\u0005]\u0006 \u0003ושקיל ספריה\u0004 \u0005[ויקח את ספרו],\u0006 \u0003וליזיל מרי דספרא\u0004 \u0005[וילך בעל הספר]\u0006 \u0003ולישקול ארבעין מפפונאה ותמנן מנרשאה\u0004 \u0005[ויקח ארבעים מבן פפוניא\u0006 שמכר והרויח סכום זה, \u0005ושמונים מבן נרש\u0006 שגנב\u0005].\u0006","\u0003זה בא בחביתו של יין וזה בא בכדו של דבש\u0004 ונפגשו, אירע ש\u0003נסדקה חבית של דבש, ושפך זה\u0004 בעל היין \u0003את יינו\u0004 \u0003ו\u0004על ידי כך \u0003הציל את הדבש,\u0004 ששווה יותר מן היין, בכך שהעביר את הדבש \u0003לתוכו,\u0004 לתוך החבית ששפך ממנה את היין —"],["\u0003אין לו אלא שכרו,\u0004 כלומר, שכר עבודה של מילוי הדבש ושכר שימוש בכלי, ואולם אינו מקבל עבור יינו ששפך. \u0003ואם אמר\u0004 בעל היין לבעל הדבש לפני ששפך את יינו: \u0003\"אציל את\u0004 הדבש \u0003שלך ואתה נותן לי\u0004 את \u0003דמי\u0004 היין \u0003שלי\"\u0004 — \u0003חייב ליתן לו.\u0004","כיוצא בזה: \u0003שטף נחל\u0004 את \u0003חמורו ו\u0004את \u0003חמור חבירו\u0004 ועומדים הם לטבוע בו, חמורו \u0003שלו\u0004 היה \u0003יפה\u0004 (שווה) \u0003מנה\u0004 (מאה דינרים) \u0003ושל חבירו מאתים, והניח זה את\u0004 הצלת חמורו \u0003שלו והציל את של חבירו\u0004 — \u0003אין לו אלא שכרו\u0004 על מה שעבד. \u0003ואם אמר לו\u0004 לפני כן: \u0003\"אני אציל את\u0004 החמור \u0003שלך ואתה נותן לי את\u0004 דמי החמור \u0003שלי\"\u0004 — \u0003חייב ליתן לו.\u0004","על מה שאמרו במשנה שאין לבעל היין אלא שכרו בלבד, שואלים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 לבעל הדבש: \u0003מהפקירא קא זכינא\u0004 \u0005[מההפקר זכיתי],\u0006 שהרי הדבש היה הולך לאיבוד ואני זכיתי בו מן ההפקר! \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה טעון כדי יין וכדי שמן וראה שהן משתברות, לא יאמר\u0004 אז \u0003\"הרי זה תרומה ומעשר על פירות\u0004 (יין או שמן) \u0003שיש לי בתוך ביתי\", ואם אמר\u0004 כך — \u0003לא אמר כלום.\u0004 משמע שדבר שהולך לאיבוד כבר אינו נחשב כשלו אלא כהפקר, אם כן גם כאן ייחשב הדבש כהפקר!","ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003ר' ירמיה\u0004 במקרה אחר, שמדובר \u0003כשעקל\u0004 (חבל, עטיפה) של \u0003בית הבד כרוך עליה\u0004 שאינה נשברת לגמרי, \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כשעקל בית הבד כרוך עליה,\u0004 ואין חבית הדבש הולכת בהכרח לאיבוד, ואין זה כהפקר.","ושואלים על מה ששנינו בברייתא: \u0003ואם אמר\u0004 — \u0003לא אמר כלום? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שבא בדרך ומעות בידו ואנס\u0004 בא \u0003כנגדו,\u0004 והוא סבור שהאנס יקח ממנו את הכסף, \u0003לא יאמר \"הרי פירות\u0004 מעשר שני \u0003שיש לי בתוך ביתי מחוללים על מעות הללו\", ואם אמר\u0004 — \u0003דבריו קיימין!\u0004 משמע שבמקרה כזה הקדשו חל!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשיכול להציל\u0004 מן האנס. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בשיכול להציל, לכתחלה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יאמר\u0004 כן? ומשיבים: מדובר \u0003ב\u0004אופן \u0003שיכול להציל על ידי הדחק.\u0004 ולכן לכתחילה לא יאמר כן, אבל בדיעבד אם אמר, כיון שלא יצא הדבר לגמרי מרשותו הקדשו חל.","ושואלים: \u0003וכל היכא דאיכא הפסידא\u0004 \u0005[מקום שיש הפסד],\u0006 שיש חשש שמא ייפסד הדבר שבידו, \u0003לכתחלה לא יאמר\u0004 שמה שעומד להיפסד יהיה הקדש או תרומה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיו לו עשר חביות\u0004 יין \u0003של טבל טמא, וראה אחת מהן שנשברה, או שנתגלתה\u0004 ועכשיו אי אפשר לשתות ממנה מחשש ארס נחש שהוטל בה, \u0003אומר: \"הרי היא תרומת מעשר על תשע חברותיה\". ובשמן לא יעשה כן, מפני הפסד כהן!\u0004 משמע שיש מקרים שיכול לעשות אפילו לכתחילה כך!","\u0003אמר ר' ירמיה:\u0004 לא מדובר כאן בנשברה לגמרי, אלא \u0003כשעקל בית הבד כרוך עליה\u0004 ונוטפת מעט מעט. ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה \u0003שנשברה חזיא\u0004 \u0005[ראויה\u0006 היא לשימוש\u0005]\u0006 אם יכרוך עליה העקל, \u0003אלא\u0004 אם \u0003נתגלתה למאי חזיא\u0004 \u0005[למה\u0006 היא \u0005ראויה]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהיא \u0003חזיא\u0004 \u0005[ראויה]\u0006 \u0003לזילוף\u0004 שהיין הזה אפשר להשתמש בו כדי לזלף אותו, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מים שנתגלו\u0004 ויש לחשוש שנחש שתה מהם ויש בהם ארס — \u0003הרי זה לא ישפכם ברשות הרבים, ולא יגבל בהן את הטיט, ולא ירבץ בהן את הבית, ולא ישקה מהם את בהמתו ולא\u0004 את \u0003בהמת חבירו,\u0004 שכל אלה הפעולות יש בהן סיכון ואף זילוף היין יהיה אסור!","ומשיבים: יש תיקון לדבר — \u0003דעבר לה\u0004 \u0005[שמעביר אותה],\u0006 את היין שבחבית, \u0003במסננת.\u0004 ו\u0003כ\u0004דברי \u0003ר' נחמיה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מסננת יש בה משום\u0004 חשש \u0003גילוי\u0004 שמא שתה נחש מן היין והטיל בו ארס ואין המסננת מועילה להציל את היין. \u0003אמר ר' נחמיה: אימתי? בזמן שהתחתונה,\u0004 החלק התחתון שלתוכו יורד היין דרך המסננת, \u0003מגולה, אבל בזמן שהתחתונה מכוסה\u0004 שאין הנחש יכול לגשת אליה, \u0003אף על פי שהעליונה\u0004 הכלי העליון, ממנו יורד היין \u0003מגולה\u0004 — \u0003אין בה משום גילוי, לפי שארס של נחש דומה לספוג, וצף ועומד במקומו,\u0004 ולא ירד הארס לכלי התחתון וניתן להשתמש ביין שבו.","ומקשים: \u0003לאו איתמר עלה\u0004 \u0005[וכי לא נאמר עליה],\u0006 \u0003אמר ר' סימון אמר ר' יהושע בן לוי: לא שנו אלא שלא טרקו\u0004 (ערבבו), \u0003אבל\u0004 אם \u0003טרקו\u0004 ליין — ירד מן הארס עמו לכלי התחתון ו\u0003אסור,\u0004 ואף כאן כששופך מן החבית מתערב הארס ביין!","ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003אפשר דמנח מידי אפומא דחביתא דשפי ליה\u0004 \u0005[שיניח דבר על פי החבית\u0006 באופן \u0005שיסנן אותו\u0006 לאט לאט\u0005]\u0006 ולא יכנס הארס בכלי האחר.","ושואלים: אם מעמיד אתה את הברייתא לעיל, שניתן לכתחילה לתרום את החבית העומדת להישבר, כדברי ר' נחמיה — על כך יש לשאול: \u0003ו\u0004לדעת \u0003ר' נחמיה, מ\u0004דבר \u0003טמא\u0004 על \u0003טמא מי תרמינן\u0004 \u0005[האם אנו תורמים]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תורמין מן הטמא על הטמא, ומן הטהור על הטהור, ומן הטהור על הטמא, אבל לא\u0004 יתרום \u0003מן הטמא על הטהור. ר' נחמיה אומר: אף מן הטמא על הטמא לא התירו לתרום אלא בשל דמאי!\u0004 ולשיטתו כיצד אמר כאן שתורם מן הטמא על הטמא? ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בשל דמאי.\u0004","וממשיכים לדון בדברי הברייתא, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ובשמן לא יעשה כן, מפני הפסד כהן.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003שמן\u0004 שאסור — מפני ש\u0003ראוי\u0004 לכהן \u0003להדליק\u0004 בו? \u0003יין נמי\u0004 \u0005[גם כן]\u0006 \u0003ראוי לזילוף! וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003זילוף לאו מילתא היא\u0004 \u0005[לא דבר\u0006 חשוב \u0005הוא],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל משום\u0004 \u0005[בשם]\u0006 \u0003ר' חייא: שותין מ\u0004יין שקונים ב\u0003לוג בסלע, ומזלפין מ\u0004יין שקונים ב\u0003לוג בשתים\u0004 (שני סלעים)! משמע שזילוף הוא דבר חשוב ומשלמים הרבה עבורו!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004יין \u0003חדש\u0004 שעדיין אין לו ריח ערב ואינו ראוי לזילוף. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ראוי לישנו\u0004 עד שיהיה ראוי לזילוף! ומשיבים: \u0003אתי ביה\u0004 \u0005[\u0006יכול \u0005לבוא בו]\u0006 \u0003לידי תקלה\u0004 במשך הזמן עד שיתיישן, שישכחו שטמא הוא וישתמשו בו, ולכן לא משהים אותו.","ומקשים: \u0003שמן נמי אתי ביה\u0004 \u0005[גם כן\u0006 יכול \u0005לבוא בו]\u0006 \u0003לידי תקלה,\u0004 ומדוע אמרנו שמשאירים אותו להדליק בו! ומשיבים: מדובר באופן \u0003דמנח\u0004 \u0005[שמונח]\u0006 \u0003בכלי מאוס,\u0004 ואז לא ישתמשו בו לאכילה אלא רק להדלקה. ואומרים: \u0003יין נמי מנח ליה\u0004 \u0005[גם כן יניח אותו]\u0006 \u0003בכלי מאוס!\u0004 ודוחים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003לזילוף קא בעי ליה\u0004 \u0005[\u0006הוא \u0005צריך אותו]\u0006 שיהיה ריחו ערב, וכי \u0003בכלי מאוס קא מנח ליה\u0004 \u0005[יניח אותו]?\u0006 והרי בכך יבאיש ריחו!","ומעירים: \u0003ותקלה עצמה,\u0004 האם יש לחשוש להשאיר דבר שמא יבואו בו לידי תקלה, \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חבית של יין של תרומה שנטמאת\u0004 — \u0003בית שמאי אומרים:\u0004"],["\u0003תשפך הכל, ובית הלל אומרים:\u0004 אינו צריך לשפוך, אלא \u0003תעשה זילוף. אמר ר' ישמעאל בר' יוסי: אני אכריע,\u0004 בשיטה ממוצעת: אם נטמאה חבית יין התרומה \u0003בבית\u0004 — \u0003תעשה זילוף,\u0004 שיכול להשתמש בה מיד לכך, \u0003ובשדה\u0004 שצריך למשך זמן כדי להעבירה, ויש לחשוש לתקלה — \u0003תשפך הכל.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להכריע ביניהם באופן אחר: \u0003ב\u0004יין \u0003ישן\u0004 — \u0003תעשה זילוף, ובחדש\u0004 שצריך להמתין הרבה עד שיקבל ריח טוב ויהיה ראוי לזילוף — \u0003תשפך הכל. אמרו לו:\u0004 אין סומכים עליך בזה כי \u0003אין הכרעה שלישית מכרעת.\u0004 שהכרעה כזו, שיש בה נימוק חדש שלא הוזכר במחלוקת הבסיסית — אין סומכים עליה. ומכל מקום רואים שיש מחלוקת תנאים אם חוששים לתקלה, שמא ישתה ממנה במשך הזמן או לא.","שנינו במשנה שאף שהשופך את יינו להציל את דבשו של חבירו — אין לו אלא שכרו, ו\u0003אם אמר לו: \"אציל את שלך\u0004 ואתה נותן לי דמי שלי \u0003\"\u0004— חייב לתת לו. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 חייב בעל הדבש לתת לו? \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]:\u0006 \u0003משטה\u0004 הייתי \u0003אני בך!\u0004 כלומר, לא התחייבתי ברצינות, אלא רק כדי שתציל את דבשי, ואיני משלם לך אלא את המגיע לך — שכרך בלבד.","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה בורח מבית האסורין והיתה מעבורת לפניו,\u0004 והוא, כמובן, ממהר לעבור את הנהר, \u0003אמר לו\u0004 לבעל המעבורת: \u0003טול דינר\u0004 שהוא סכום גבוה מאד עבור העברת אדם במעבורת את הנהר, \u0003והעבירני\u0004 את הנהר, והעבירו — \u0003אין לו אלא שכרו\u0004 הרגיל, ואינו יכול לתבוע ממנו דינר. \u0003אלמא\u0004 \u0005[מכאן יוצא]\u0006 ש\u0003אמר ליה\u0004 \u0005[ש\u0006יכול \u0005לומר לו]:\u0006 \u0003משטה אני בך, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הדבש לבעל היין: \u0003משטה אני בך!\u0004","ומשיבים: \u0003הא לא דמי\u0004 \u0005[אין זה\u0006 כלומר, דין משנתנו \u0005דומה]\u0006 \u0003אלא לסיפא\u0004 \u0005[לסופה\u0006 של אותה ברייתא\u0005]\u0006 שכך שנו בה: \u0003ואם אמר לו \"טול דינר זה בשכרך והעבירני\"\u0004 — \u0003נותן לו שכרו משלם.\u0004","ויש לשאול: \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[\u0006ב\u0005מה שונה תחילת\u0006 הברייתא \u0005ובמה שונה סופה]?\u0006 \u0003אמר רמי בר חמא:\u0004 בסוף הברייתא מדובר לא בבעל מעבורת העוסק תדיר בכך, אלא \u0003בצייד\u0004 (דייג) \u0003השולה דגים מן הים, ואמר ליה\u0004 \u0005[לו]\u0006 הדייג לבורח מבית האסורים: \u0003אפסדתני כוורי בזוזא\u0004 \u0005[הפסדת לי דגים ב\u0006שווי \u0005זוז,\u0006 דינר\u0005]\u0006 כשנתבטלתי מעבודתי כדי להעבירך, ולכן מגיע לו דינר זה בשכרו. וכל שכן הדין כן במשנתנו שהלה שופך את יינו ומפסידו כדי להציל את דבשו של חבירו.","שנינו במשנה: \u0003שטף נהר\u0004 את \u0003חמורו ו\u0004את \u0003חמור חבירו,\u0004 החמור \u0003שלו יפה\u0004 (שווה) \u0003מנה\u0004 (מאה דינרים) ושל חבירו שווה מאתיים, והציל את חמור חבירו, אם התנה איתו מראש שישלם לו תמורת חמורו — מקבל ממנו את דמי חמורו. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 לשנות במשנה גם דין זה, למרות שלכאורה הוא זהה לדין הקודם השנוי במשנה בדבש וביין. משום \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק את ההלכה \u0005הראשונה],\u0006 היינו אומרים: דווקא \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 הדין כן \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003פירש\u0004 בעל היין שעל מנת כן הוא עושה \u0003יהיב ליה\u0004 \u0005[נותן לו\u0006 בעל הדבש\u0005]\u0006 \u0003דמי כוליה\u0004 \u0005[הכל],\u0006 \u0003משום\u0004 ש\u0003בידים קא פסיד\u0004 \u0005[הוא מפסיד],\u0006 שהרי שופך את יינו שלו ומפסידו, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשטיפת נהר את החמור ש\u0003ממילא\u0004 נגרם הנזק לחמורו, ולא בא על ידי מעשהו שלו, \u0003נימא\u0004 \u0005[נאמר]\u0006 ש\u0003אין לו אלא שכרו.\u0004","ולהיפך: \u0003ואי אשמעינן סיפא\u0004 \u0005[ואם היה משמיע לנו\u0006 רק את \u0005הסוף],\u0006 כלומר, בדין החמור, הייתי אומר: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003הוא דבסתמא\u0004 \u0005[שבסתם]\u0006 \u0003אין לו אלא שכרו, משום\u0004 ש\u0003ממילא,\u0004 שבא הדבר מעצמו, \u0003אבל התם\u0004 \u0005[שם]\u0006 ביין ודבש, ש\u0003בידים\u0004 הפסיד את שלו, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003אפילו בסתמא יהיב ליה\u0004 \u0005[בסתם,\u0006 בלא התנייה מפורשת, \u0005נותן לו]\u0006 \u0003דמי כולה,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 לשנות במשנתנו שייאמרו שני המקרים.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב כהנא מרב: ירד\u0004 בעל החמור הזול \u0003להציל\u0004 את החמור היקר, על תנאי שיתן לו בעל החמור היקר דמי חמורו, \u0003ו\u0004בינתיים \u0003עלה\u0004 חמורו \u0003שלו מאליו, מהו\u0004 הדין? האם צריך בעל החמור היקר לשלם לו דמי חמורו, או יכול לומר לו: הרי לא הפסדת, וקיבלת את שלך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בתשובה: \u0003משמיא רחימו עליה\u0004 \u0005[מן השמים ריחמו עליו]\u0006 על המציל, אבל מה שהתנה איתו בעל החמור היקר — צריך לשלם.","ומוסיפים: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב ספרא הוה קא אזיל בשיירתא\u0004 \u0005[היה הולך בשיירה],\u0006 וכל עוד היו הולכים \u0003לוינהו ההוא ארי\u0004 \u0005[ליוה אותם אריה אחד].\u0006 \u0003כל לילא קא שדר ליה חמרא דחד מינייהו וקא אכיל\u0004 \u0005[כל לילה היו שולחים לו חמור של אחד מהם והיה אוכל\u0006 אותו\u0005]\u0006 כדי שלא יתנפל האריה על השיירה, \u0003כי מטא זמניה\u0004 \u0005[כאשר הגיע זמנו]\u0006 של \u0003רב ספרא\u0004 לתת את חמורו, \u0003שדר ליה חמרא\u0004 \u0005[שלח לו\u0006 לאריה \u0005חמור]\u0006 \u0003ולא אכליה\u0004 \u0005[אכלו],\u0006 \u0003קדים\u0004 \u0005[הקדים]\u0006 \u0003רב ספרא וזכה ביה\u0004 \u0005[בו\u0006 לעצמו מחדש\u0005].\u0006","לגופו של מעשה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: למה\u0004 היה \u0003ליה למיזכי ביה\u0004 \u0005[לו,\u0006 לרב ספרא, \u0005לזכות בו]?\u0006 \u0003נהי דכי אפקריה\u0004 \u0005[אם אמנם שהפקיר אותו]\u0006 — \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003אריה אפקריה\u0004 \u0005[הפקיר אותו],\u0006 ואולם \u0003אדעתא דכולי עלמא\u0004 \u0005[על דעת\u0006 שיהא \u0005של הכל]\u0006 \u0003לא אפקריה\u0004 \u0005[הפקיר אותו],\u0006 ואם כן שלו הוא! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רב ספרא לרווחא דמילתא\u0004 \u0005[לרווח הדברים]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה],\u0006 כלומר, באמת מצד הדין לא היה זקוק לכך, אבל כדי שלא יבואו לטעון כנגדו עשה מעשה של זכייה.","ועוד על דין משנתנו \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב מרבי:\u0004 אם \u0003ירד להציל\u0004 את חמור חבירו \u0003ולא הציל, מהו\u0004 דינו? \u0003אמר לו: ו\u0004כי \u0003זו שאילה?\u0004 ברור שלא מגיע לו, ו\u0003אין לו אלא שכרו\u0004 (שכר עבודתו).","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב ממה ששנינו: \u0003השוכר את הפועל\u0004"],["\u0003להביא כרוב ודורמסקנין\u0004 (שזיפים) \u0003ל\u0004מאכלו של \u0003חולה, והלך\u0004 השליח \u0003ומצאו שמת\u0004 החולה \u0003או שהבריא\u0004 ואינו זקוק עוד לאלה — \u0003נותן לו\u0004 המשלח \u0003שכרו משלם.\u0004 משמע שאף על פי שלא הועיל, מכל מקום צריך לשלם לו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם עביד\u0004 \u0005[שם עשה]\u0006 \u0003שליח שליחותיה\u0004 \u0005[\u0006את \u0005שליחותו],\u0006 שהרי נשלח להביא את הדברים וכך עשה, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא עביד\u0004 \u0005[עשה]\u0006 \u0003שליח שליחותיה\u0004 \u0005[\u0006את \u0005שליחותו]\u0006 שהרי לא הציל את מה שהיה צריך להציל.","ועוד בענין הדומה למה שסופר מקודם על רב ספרא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שיירא שהיתה מהלכת במדבר ועמד עליה גייס\u0004 של אנשי צבא או שודדים \u0003לטורפה\u0004 (לבזוז אותם) וצריכים לרצות אותם בממון — \u0003מחשבין\u0004 את חלקו של כל אחד בסכום הנדרש \u0003לפי\u0004 כמות ה\u0003ממון\u0004 שכל אחד נושא עימו, \u0003ואין מחשבין לפי\u0004 מספר \u0003נפשות\u0004 משפחתו של כל אחד.","\u0003ו\u0004אולם \u0003אם שכרו תייר ההולך לפניהם\u0004 שצריך להראותם את הדרך — \u0003מחשבין\u0004 את שכרו \u0003אף לפי נפשות, ו\u0004מכל מקום \u0003לא ישנו\u0004 בענין זה \u0003ממנהג החמרין,\u0004 כפי שהם נוהגים באותו מקום בדבר זה.","\u0003רשאין החמרין להתנות, שכל מי שיאבד לו חמורו יעמיד\u0004 ו\u0003לו חמור אחר.\u0004 ואם איבד את החמור \u0003בכוסיא\u0004 \u0005[בפשיעה]\u0006 — \u0003אין מעמידין\u0004 לו חמור אחר, \u0003שלא בכוסיא\u0004 \u0005[בפשיעה]\u0006 — \u0003מעמידין לו. ואם אמר\u0004 האיש שאבד חמורו: \u0003תנו לי\u0004 כסף במקום זה \u0003ו\u0004גם כך \u0003אני אשמור\u0004 עמכם בשיירה — \u0003אין שומעין לו\u0004 אלא יקבל מהם חמור.","ושואלים על כך: \u0003פשיטא\u0004 \u0005[פשוט\u0006\u0005,\u0006 מובן מאליו\u0005]\u0006 הוא שכך הדין ומה צורך יש להשמיענו זאת. ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר אלא במקרה \u0003דאית ליה חמרא אחרינא\u0004 \u0005[שיש לו חמור אחר],\u0006 והוא ממילא שומר. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הא קא מינטר ליה\u0004 \u0005[הרי הוא שומר אותו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 כי \u0003שאני נטירותא דחד מנטירותא דבי תרי\u0004 \u0005[שונה שמירה של אחד משמירה של שנים],\u0006 שבשנים שומר יותר.","ובדומה לכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ספינה שהיתה מהלכת בים,\u0004 ו\u0003עמד עליה נחשול\u0004 (גל) \u0003לטובעה והקילו ממשאה\u0004 על ידי שהשליכו ממנה לים — \u0003מחשבין\u0004 כמה כל אחד מהנוסעים צריך להשליך \u0003לפי משאוי,\u0004 שכל אחד משליך לפי משאו, \u0003ואין מחשבין לפי ממון\u0004 שמפסיד כל אחד, שיש כאלו שסחורתם יקרה יותר משל האחרים, \u0003ו\u0004מקום מקום \u0003לא ישנו ממנהג הספנים.\u0004","\u0003ורשאין הספנים להתנות, שכל מי שאבדה לו ספינה יעמיד לו ספינה אחרת. אבדה לו בכוסיא\u0004 \u0005[בפשיעה]\u0006 — \u0003אין מעמידין, שלא בכוסיא\u0004 \u0005[בפשיעה]\u0006 — \u0003מעמידין לו. ואי\u0004 \u0005[ואם]\u0006 \u0003פירש\u0004 (הפליג) \u0003למקום שאין הספינות הולכין\u0004 ואבדה ספינתו — \u0003אין מעמידין\u0004 לו ספינה אחרת.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא שאם עשה דבר שלא כראוי אין משלמים לו, ומה צורך יש להשמיענו זאת! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו להיאמר אלא במקרה שהספנים נוהגים ש\u0003ב\u0004חודש \u0003ניסן מרחקי\u0004 \u0005[מתרחקים]\u0006 מן החוף מלוא \u0003חד אשלא\u0004 \u0005[חבל אחד],\u0006 \u0003וב\u0004חודש \u0003תשרי מרחקי תרי אשלי\u0004 \u0005[מתרחקים שני חבלים],\u0006 \u0003וקא אזיל ביומי\u0004 \u0005[והוא הולך בימי]\u0006 \u0003ניסן למקום\u0004 שהולכים לו ב\u0003תשרי, מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003דוושיה נקיט ואזיל\u0004 \u0005[בדרכו\u0006 הוא \u0005אוחז והולך]\u0006 וזו עדיין דרך שרגילים ללכת בה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שאין הולכים כך בימים אלה הרי זה כפשיעה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שיירא שהיתה מהלכת במדבר ועמד גייס וטרפה, ועמד אחד מהן והציל\u0004 את בני השיירה מן הגייס — \u0003הציל לאמצע,\u0004 כלומר, מחלקים ביניהם את מה שהציל. \u0003ואם אמר \"אני אציל לעצמי\"\u0004 — \u0003הציל לעצמו.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003יכול\u0004 כל אחד מהם \u0003להציל, אפילו סיפא נמי\u0004 \u0005[\u0006ב\u0005סופה גם כן]\u0006 שאמר שמציל לעצמו היה צריך להיות \u0003לאמצע,\u0004 שהרי לא נתייאש חבירו! \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר באופן ש\u0003לא יכול להציל,\u0004 אם כן \u0003אפילו רישא נמי\u0004 \u0005[בתחילה גם כן]\u0006 צריך הכל להיות \u0003לעצמו\u0004 מאחר שחבירו מתייאש מחפציו!","\u0003אמר רמי בר חמא:\u0004 מדובר כשאין השני יכול להציל, ו\u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בשותפין עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ו\u0004אף שבדרך כלל לא ניתן לחלק נכס משותף שלא מדעת כל השותפים, \u0003כגון זה\u0004 שהממון המשותף אובד ואחד מצילו, \u0003שותף חולק שלא לדעת חבירו.\u0004 ולכן, אם \u0003אמר\u0004 מראש שהוא נוטל לעצמו — \u0003פליג\u0004 \u0005[מתחלק]\u0006 משותפו ונוטל לעצמו, אם \u0003לא אמר\u0004 — \u0003לא פליג\u0004 \u0005[מתחלק]\u0006 אלא נשאר בשותפות.","\u0003רבא אמר: הכא\u0004 \u0005[כאן]\u0006 \u0003בפועלין\u0004 שנשכרו לשמור את השיירה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וכ\u0004דברי \u0003רב,\u0004 ש\u0003אמר רב: פועל יכול לחזור בו אפילו בחצי היום,\u0004","\u0003ו\u0004כל \u0003כמה\u0004 זמן ש\u0003לא הדר ביה כברשותיה\u0004 \u0005[חזר בו כברשותו]\u0006 של \u0003בעל הבית דמי\u0004 \u0005[נחשב],\u0006 וכל שמציל כמציל לכולם. \u0003וכי הדר ביה\u0004 \u0005[וכאשר חוזר בו]\u0006 ואומר שלעצמו הוא מציל — \u0003טעמא אחרינא\u0004 \u0005[טעם אחר]\u0006 \u0003הוא,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לי בני ישראל עבדים\"\u0004 (ויקרא כה, נה), לומר: \u0003ולא עבדים לעבדים,\u0004 שאין אדם מישראל משועבד לעבודה כעבד.","\u0003רב אשי אמר:\u0004 מדובר \u0003כשיכול\u0004 חבירו \u0003להציל על ידי הדחק,\u0004 ובאופן כזה אם \u0003גלי דעתיה\u0004 \u0005[גילה דעתו]\u0006 שרצונו לזכות לעצמו, וחבירו שתק — הרי זה הולך \u0003לעצמו,\u0004 ואם \u0003לא גלי דעתיה\u0004 \u0005[גילה דעתו]\u0006 — הרי זה הולך \u0003לאמצע.\u0004","\u0003הגוזל שדה מחבירו ונטלוה מסיקין\u0004 (אנסים) מן הגזלן, \u0003אם מכת מדינה היא,\u0004 שגזלו מכולם — \u0003אומר לו\u0004 הגזלן \u0003\"הרי שלך לפניך\",\u0004 כלומר, אני יצאתי מן השדה ואתה לך וקח אותה מהם. \u0003אם מחמת הגזלן\u0004 לקחו אותה — \u0003חייב\u0004 הגזלן \u0003להעמיד לו שדה אחר\u0004 באותה ערך.","\u0003אמר רב נחמן בר יצחק: מאן דתני\u0004 \u0005[מי ששונה]\u0006 את משנתנו בלשון \u0003\"מסיקין\"\u0004 — \u0003לא משתבש\u0004 (טועה), \u0003ומאן דתני\u0004 \u0005[ששונה]\u0006 בלשון \u0003\"מציקין\"\u0004 גם כן \u0003לא משתבש\u0004. ומסבירים: \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 בלשון \u0003\"מציקין\" לא משתבש, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"במצור ובמצוק\u0004 אשר יציק לך אויבך\" \u0005(דברים כח, נה)\u0006.","\u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 בלשון \u0003\"מסיקין\" לא משתבש דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004כל עצך ופרי אדמתך \u0003יירש הצלצל\"\u0004 (דברים כח, מב), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים אנו\u0006 כתוב זה\u0005]:\u0006 \u0003יחסניניה סקאה\u0004 \u0005[יירש אותו הארבה].\u0006","שנינו במשנה: הגוזל שדה ונטלוה ממנו מסיקים, \u0003אם מחמת הגזלן\u0004 — \u0003חייב.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה בדיוק הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דאנסוה לארעא דידיה\u0004 \u0005[שלקחו\u0006 המסיקים רק \u0005את הקרקע שלו]\u0006 \u0003ולא אנסוה כולי ארעתא\u0004 \u0005[לקחו את כל הקרקעות],\u0006 מקרה זה אין צורך להשמיענו, שכן \u0003הא מרישא שמעת מינה\u0004 \u0005[הרי מתחילת\u0006 המשנה \u0005שמעת אותה]\u0006 ששנינו: \u0003אם מכת מדינה היא,\u0004 ומכאן נדייק: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 היתה זו מכת מדינה — \u0003לא\u0004 יכול לומר לו הגזלן \"הרי שלך לפניך\" וחייב להעמיד לו שדה אחר.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו במקרה של גוזל שדה מחבירו לעצמו, אלא כגון \u0003דאחוי אחוויי\u0004 \u0005[שהראה]\u0006 הגזלן למסיקין. \u0003לישנא אחרינא\u0004 \u0005[\u0006ב\u0005לשון אחרת]\u0006 אמרו כך בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דאנסוה\u0004 \u0005[שכפוהו]\u0006 \u0003גויים ואמרי ליה אחויי ארעתיה\u0004 \u0005[ואמרו לו שיראה\u0006 להם את \u0005קרקעותיו\u0006 שלו\u0005]\u0006 כדי לקחתן, \u0003ואחוי ההוא בהדייהו\u0004 \u0005[והראה\u0006 להם גם את \u0005זו יחד איתן].\u0006","מסופר: \u0003ההוא גברא דאחוי אכריא דחטי דבי ריש גלותא\u0004 \u0005[אדם אחד שהראה\u0006 למסיקים \u0005את כרי החיטים של בית ראש הגולה]\u0006 ולקחו את הכרי, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב נחמן\u0004 לדין, \u0003חייביה\u0004 \u0005[חייב אותו]\u0006 \u0003רב נחמן לשלומי\u0004 \u0005[לשלם].\u0006 \u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רב יוסף אחוריה\u0004 \u0005[אחוריו]\u0006 של \u0003רב הונא בר חייא, ויתיב\u0004 \u0005[ויושב היה]\u0006 \u0003רב הונא בר חייא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר חייא לרב נחמן:\u0004 האם דבר זה שעשית הוא \u0003דינא או קנסא\u0004 \u0005[דין או קנס]\u0006 שקנסת אותו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם מחמת הגזלן\u0004 — \u0003חייב להעמיד לו שדה\u0004 אחרת, \u0003ואוקימנא דאחוי אחוויי\u0004 \u0005[והעמדנו\u0006 זאת כשמדובר \u0005שהראה],\u0006 הרי שדין ממש הוא. \u0003בתר דנפק\u0004 \u0005[אחרי שיצא]\u0006 רב נחמן משם, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לרב הונא בר חייא: מאי נפקא\u0004 \u0005[מה יוצא]\u0006 \u0003לך מיניה\u0004 \u0005[מזה]\u0006 מה זה משנה להלכה"],["\u0003אי דינא אי קנסא\u0004 \u0005[אם דין אם קנס\u0006 הוא\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי דינא\u0004 \u0005[אם דין\u0006 הוא\u0005]\u0006 — \u0003גמרינן מיניה\u0004 \u0005[למדים אנו ממנו]\u0006 לשאר דברים, \u0003אי קנסא\u0004 \u0005[אם קנס\u0006 הוא\u0005]\u0006 — \u0003לא גמרינן מיניה\u0004 \u0005[אין אנו למדים ממנו]\u0006 לעניינים אחרים, שאולי קנסו רב נחמן מפני סיבה מיוחדת שהיתה לו לקנוס אדם זה.","\u0003ומנא תימרא דמקנסא לא גמרינן\u0004 \u0005[ומנין אומר אתה שמקנס אין אנו למדים]\u0006 למקרים אחרים? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בראשונה היו אומרים המטמא\u0004 טהרות של חבירו ונפסד ערכם בכך, \u0003ו\u0004כן \u0003המנסך\u0004 יין של חבירו לעבודה זרה ואסרו בכך בהנאה, אף על פי שהנזק שעשה אינו ניכר לעין — מכל מקום צריך לשלם לחבירו, \u0003חזרו לומר\u0004 שצריך לשלם לחבירו \u0003אף המדמע,\u0004 כלומר, מי שמערב את התרומה בחולין, וגרם להפסד ממון, שמחיר החולין יורד, משום שאי אפשר לאכול את הכל אלא בתורת תרומה ששווייה בשל מיעוט האוכלים אותה נמוך.","ויש לדייק: \u0003חזרו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 שהיה צריך לחזור ולהחליט על כך, אבל אם \u0003לא חזרו\u0004 והחליטו — \u0003לא\u0004 היה חייב המדמע בתשלום, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 הרי לכאורה אותו טעם הוא, כמו המטמא והמנסך שדינם שמשלמים, הגם שהוא היזק שאינו ניכר! \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דקנסא\u0004 \u0005[שקנס]\u0006 \u0003הוא, וקנסא לא גמרינן מיניה\u0004 \u0005[וקנס אין למדים ממנו],\u0006 ולכן מה שגזרו — גזרו, ואין למדים לדברים אחרים?","ודוחים: \u0003לא,\u0004 אפשר לומר שמה שהוצרכו לחזור ולחייב אף את המדמע אינו משום שאין למדים מקנס, אלא מפני שהיה טעם לחלק בין מדמע לדין מטמא ומנסך: \u0003מעיקרא סברי\u0004 \u0005[מתחילה סברו]\u0006 כי \u0003להפסד מרובה חששו,\u0004 שהמטמא טהרות מפחית את ערכם כמעט לגמרי, והמנסך אוסר את הכל בהנאה, ולכן גזרו עליהם שישלמו, אבל \u0003להפסד מועט\u0004 שבא על ידי המדמע \u0003לא חששו, ולבסוף סברי\u0004 \u0005[סברו]\u0006 ש\u0003להפסד מועט נמי\u0004 \u0005[גם כן]\u0006 \u0003חששו.\u0004","ומקשים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 וכי למדים מקנס? \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' אבין\u0004 אותה ברייתא באופן שונה: \u0003בראשונה היו אומרים המטמא והמדמע\u0004 חייבים לשלם, \u0003חזרו לומר אף המנסך.\u0004 ונדייק: \u0003חזרו\u0004 וקנסו — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא חזרו\u0004 — \u0003לא\u0004 היו קונסים מאליו גם במנסך,","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דלא גמרינן מקנסא\u0004 \u0005[שאין אנו למדים מקנס]?\u0006 שהרי לגרסה זו, את הטעם שאמרנו קודם, שלהפסד מועט לא חששו אי אפשר לומר כאן, שהרי אף בתחילה חששו גם להפסד מרובה של מטמא וגם להפסד מועט של מדמע.","ודוחים: \u0003לא,\u0004 אף כאן היה מקום להבחין בין המטמא והמדמע לבין המנסך, \u0003מעיקרא סברי\u0004 \u0005[מתחילה סברו]\u0006 \u0003כ\u0004דעת \u0003ר' אבין, ולבסוף סברי\u0004 \u0005[סברו]\u0006 \u0003כ\u0004דעת \u0003ר' ירמיה.\u0004 ומסבירים מה עניינן של דעות אלה.","\u0003מעיקרא סברי\u0004 \u0005[בתחילה סברו]\u0006 \u0003כ\u0004דעת \u0003ר' אבין,\u0004 ש\u0003אמר ר' אבין:\u0004 היה עומד ברשות הרבים בשבת ו\u0003זרק חץ מתחילת ארבע\u0004 אמות \u0003ולבסוף ארבע,\u0004 שעל ידי כך עבר עבירה של טלטול ארבע אמות ברשות הרבים בשבת, \u0003וקרע\u0004 החץ \u0003שיראין\u0004 (בגד משי) \u0003בהליכתו\u0004 — \u0003פטור\u0004 מלשלם לבעליו, \u0003שהרי עקירה צורך הנחה היא,\u0004 שאף על פי שהעבירה לא נגמרה אלא בזמן שהחץ נח לאחר ארבע אמות, מכל מקום מאז שנעקר החץ בתחילת ארבע אמות עד שנח היא פעולה אחת. \u0003ו\u0004משום כך הריהו \u0003מתחייב בנפשו\u0004 עליה, משום שעבר על איסור שבת, והמתחייב בנפשו פטור מן התשלומים. וכך הבינו שיש לדון בענין זה של מנסך, שמתחייב על הניסוך מיתה כעובד עבודה זרה משעה שהגביה את היין, ומשום כך שוב אינו חייב לשלם על היין שהפסיד.","\u0003ולבסוף סברי\u0004 \u0005[סברו]\u0006 \u0003כ\u0004דעת \u0003ר' ירמיה,\u0004 ש\u0003אמר ר' ירמיה\u0004 בענין של מנסך: \u0003משעת הגבהה\u0004 של היין הזה כבר \u0003קנייה\u0004 \u0005[קנה אותו]\u0006 בכך ו\u0003איחייב ליה\u0004 \u0005[התחייב לו]\u0006 ב\u0003ממון\u0004 כגזלן, ואולם \u0003מתחייב בנפשו\u0004 כעובד עבודה זרה \u0003לא הוי\u0004 \u0005[איננו]\u0006 \u0003עד שעת ניסוך.\u0004 ומשום כך חזרו לומר שאף המנסך חייב לשלם, משום שמעשה הגניבה היה קודם למעשה העבירה.","ושבים לדון בדין המראה את ממונו של חבירו לגויים. מסופר: \u0003רב הונא בר יהודה איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום שנקרא \u0003בי אביוני,\u0004 לאחר מכן \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כלום מעשה בא לידך\u0004 לפסוק בו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מקרה של \u0003ישראל שאנסוהו גוים\u0004 שרצו לקחת ממונו, \u0003והראה\u0004 להם את \u0003ממון חבירו\u0004 ולקחוהו \u0003בא לידי, וחייבתיו\u0004 שישלם על הנזק שגרם,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב הונא: \u0003אהדר עובדא למריה\u0004 \u0005[החזר\u0006 את \u0005המעשה,\u0006 את מה שגבית, \u0005לבעליו]\u0006 משום שאינו חייב על כך. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ישראל שאנסוהו גוים והראה\u0004 להם את \u0003ממון חבירו\u0004 — \u0003פטור,\u0004 משום שהיה רק גורם, \u0003ו\u0004אולם \u0003אם נטל ונתן ביד\u0004 שעשה מעשה בפועל — \u0003חייב.\u0004","\u0003אמר רבה:\u0004 מכל מקום \u0003אם הראה מעצמו\u0004 ולא באונס, הרי הוא \u0003כנשא ונתן ביד דמי\u0004 \u0005[נחשב]\u0006 וחייב.","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אנסוהו גוים, ואחוי אחמרא\u0004 \u0005[והראה\u0006 להם \u0005על היין]\u0006 של \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב פנחס בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא, אמרו ליה\u0004 \u0005[לו]\u0006 הגויים: \u0003דרי ואמטי בהדן\u0004 \u0005[שא והבא יחד איתנו]\u0006 את היין\u0005,\u0006 \u0003דרא ואמטי בהדייהו\u0004 \u0005[נשא והביא יחד איתם].\u0006 לסוף \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב אשי, פטריניה\u0004 \u0005[ופטר אותו]\u0006 את האיש שהראה.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב אשי\u0004 בשאלה: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אם נשא ונתן ביד\u0004 — \u0003חייב,\u0004 ואף כאן נשא ונתן ביד! \u0003אמר להו\u0004 \u0005[להם]\u0006 בתשובה: \u0003הני מילי היכא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום]\u0006 ש\u0003לא אוקמיה עילויה מעיקרא\u0004 \u0005[העמיד אותו,\u0006 את הגוי האנס, \u0005עליו\u0006 על ממון חבירו \u0005בתחילה],\u0006 ועדיין לא היה הדבר ברשות הגויים, \u0003אבל היכא דאוקמיה עילויה מעיקרא\u0004 \u0005[במקום שהעמיד אותו,\u0006 את הגוי, \u0005עליו מתחילה]\u0006 — הרי זה כאילו כבר \u0003מיקלי קלייה\u0004 \u0005[שרפו],\u0006 כלומר, הנזק נגרם על ידי מה שאמר, וכפי שאמרנו, על אמירה בלבד אינו מתחייב, ומה שעשה אחר כך בידים כבר לא שינה את המצב.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבהו לרב אשי\u0004 על שיטתו זו ממה ששנינו בברייתא: \u0003אמר לו אנס \"הושיט לי פקיע עמיר\u0004 (צרור, פקעת תבואה) \u0003זה, או אשכול ענבים זה\", והושיט לו\u0004 — \u0003חייב\u0004 לשלם לבעלים, למרות שהאנס נמצא ליד הדבר והריהו כבידו, ואין אנו אומרים שהוא כשרוף. השיב רב אשי: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דקאי בתרי עברי נהרא\u0004 \u0005[שעומדים\u0006 הנותן והאנס \u0005בשני עברי הנהר],\u0006 שאם לא היה נותן לאנס — לא היה הדבר מגיע לו.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 כפירוש זה, \u0003דקתני\u0004 \u0005[ששנה]\u0006 בברייתא שמצווה אותו האנס: \u0003\"הושיט\" ולא תני\u0004 \u0005[שנה]\u0006 \u0003\"תן\",\u0004 משמע שנמצא האנס במקום מרוחק במקצת. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ועוד מסופר בענין מוסר: \u0003ההוא שותא\u0004 \u0005[מכמורת אחת]\u0006 \u0003דהוו מנצו עלה בי תרי\u0004 \u0005[שהיו רבים עליה שניים].\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003אמר: דידי\u0004 \u0005[שלי]\u0006 \u0003הוא, והאי\u0004 \u0005[וזה]\u0006 \u0003אמר: דידי\u0004 \u0005[שלי]\u0006 \u0003הוא,\u0004 \u0003אזל חד מנייהו\u0004 \u0005[הלך אחד מהם]\u0006 \u0003ומסרה לפרהגנא דמלכא\u0004 \u0005[לפקיד המלכות].\u0006 \u0003אמר אביי, יכול לומר: אנא כי מסרי\u0004 \u0005[אני כאשר מסרתי]\u0006 — \u0003דידי מסרי\u0004 \u0005[\u0006את \u0005שלי מסרתי],\u0006 שהרי אני טוען ששלי הוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ו\u0004כי \u0003כל כמיניה\u0004 (ברשותו) לעשות כן? \u0003אלא אמר רבא: משמתינן ליה\u0004 \u0005[מנדים אנו אותו],\u0006 את המוסר \u0003עד דמייתי ליה וקאי בדינא\u0004 \u0005[שיביא\u0006 את המכמורת \u0005הזו\u0006 חזרה \u0005ויעמוד בדין]\u0006 כדי לברר למי היא שייכת.","ועוד מסופר בענין מוסר: \u0003ההוא גברא דהוה בעי אחוויי אתיבנא דחבריה\u0004 \u0005[אדם אחד שהיה רוצה להראות\u0006 לגוים \u0005על תבן של חבירו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא תחוי ולא תחוי\u0004 \u0005[אל תראה ואל תראה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מחוינא ומחוינא\u0004 \u0005[מראה ומראה אני],\u0006 שלא רצה לשמוע לדברי רב. \u0003יתיב\u0004 \u0005[ישב]\u0006 אז \u0003רב כהנא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב,\u0004 וכששמע שהאיש מתחצף ואינו מקבל את הדין קם ו\u0003שמטיה לקועיה מיניה\u0004 \u0005[שמט את צווארו ממנו]\u0006 במכה והרגו.","\u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רב עילויה\u0004 \u0005[עליו]\u0006 את הפסוק: \u0003\"בניך עלפו שכבו בראש כל חוצות כתוא מכמר\"\u0004 (ישעיה נא, כ). וכך למד: \u0003מה תוא זה כיון שנפל במכמר\u0004 — \u0003אין מרחמין עליו, אף ממון של ישראל כיון שנפל ביד גוים\u0004 — \u0003אין מרחמין עליו,\u0004 ולפיכך מה שעשה רב כהנא, כדין עשה.","אחר כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב\u0004 לרב כהנא: \u0003כהנא, עד האידנא הוו פרסאי\u0004 \u0005[עכשיו היו\u0006 שליטים \u0005פרסיים]\u0006 ש\u0003לא קפדי\u0004 \u0005[היו מקפידים]\u0006 על \u0003שפיכות דמים, והשתא איכא יוונאי דקפדו\u0004 \u0005[ועכשיו יש יוונים שמקפידים]\u0006 על \u0003שפיכות דמים, ואמרי \"מרדין, מרדין\"\u0004 \u0005[ואומרים: \"רצח, רצח\"]\u0006 ויאשימוך על מה שעשית בהריגה, \u0003קום סק לארעא\u0004 \u0005[עלה לארץ]\u0006 \u0003ישראל, וקביל עלך\u0004 \u0005[וקבל עליך]\u0006 ש\u0003לא תקשי\u0004 \u0005[תקשה]\u0006 \u0003לר' יוחנן\u0004 החי בארץ ישראל \u0003שבע שנין\u0004 \u0005[שבע שנים].\u0006","ומספרים: \u0003אזיל\u0004 \u0005[הלך]\u0006 רב כהנא, ובארץ ישראל \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 את \u0003ריש לקיש דיתיב וקא מסיים מתיבתא דיומא לרבנן\u0004 \u0005[כש\u0006הוא \u0005יושב\u0006 וחוזר \u0005ומסכם את ישיבת היום לחכמים].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רב כהנא: \u0003ריש לקיש\u0004 \u0003היכא\u0004 \u0005[היכן\u0006 הוא\u0005]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רב כהנא בלי לשמוע את הדרשה: \u0003האי קושיא והאי קושיא, והאי פירוקא והאי פירוקא\u0004 \u0005[זו קושיה וזו קושיה, וזה תירוצה וזה תירוצה],\u0006 שמפני חריפותו וידיעתו כיוון לכל מה שנידון בבית המדרש. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לריש לקיש\u0004 שהגיע אדם גדול בתורה. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ריש לקיש אמר ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן: ארי\u0004 (כינוי לאדם גדול) \u0003עלה מבבל, לעיין מר במתיבתא דלמחר\u0004 \u0005[שיעיין אדוני\u0006 בדברים שיאמר \u0005בישיבה מחר]\u0006 כדי שלא יבוש מפני אדם גדול זה.","\u0003למחר אותבוה בדרא קמא קמיה\u0004 \u0005[הושיבו אותו בשורה הראשונה\u0006 ממש \u0005לפני]\u0006 \u0003ר' יוחנן, אמר\u0004 ר' יוחנן \u0003שמעתתא\u0004 \u0005[שמועה]\u0006 \u0003ולא אקשי\u0004 \u0005[הקשה]\u0006 רב כהנא דבר, כפי שהורה לו רב, אמר ר' יוחנן \u0003שמעתתא\u0004 \u0005[שמועה]\u0006 נוספת \u0003ולא אקשי\u0004 \u0005[הקשה],\u0006 \u0003אנחתיה אחורי שבע דרי\u0004 \u0005[הוריד אותו אחורנית\u0006 משורה לשורה \u0005שבע שורות]\u0006 \u0003עד דאותביה בדרא בתרא\u0004 \u0005[שהושיב אותו בשורה האחרונה],\u0006 משום שסבר שאין הוא תלמיד חכם המבין מספיק כדי לשאול ולברר את הדברים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש: ארי שאמרת נעשה שועל!\u0004 שמתברר שאינו אדם גדול.","\u0003אמר\u0004 רב כהנא בליבו: \u0003יהא רעוא דהני\u0004 \u0005[רצון שאותן]\u0006 \u0003שבע דרי\u0004 \u0005[שורות]\u0006 שהורידוני \u0003להוו\u0004 \u0005[תהיינה]\u0006 \u0003חילוף\u0004 תמורת אותן \u0003שבע שנין\u0004 \u0005[שנים]\u0006 ש\u0003אמר לי רב\u0004 שלא אקשה בהן לר' יוחנן. \u0003קם אכרעיה\u0004 \u0005[עמד על רגליו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' יוחנן: \u0003נהדר מר ברישא\u0004 \u0005[שיחזור אדוני מתחילת\u0006 דרשתו\u0005],\u0006 \u0003אמר שמעתתא ואקשי\u0004 \u0005[אמר\u0006 שוב \u0005את השמועה והקשה]\u0006 רב כהנא, \u0003אוקמיה בדרא קמא\u0004 \u0005[העמידו,\u0006 הושיבו \u0005אותו\u0006 שוב \u0005בשורה הראשונה],\u0006 \u0003אמר\u0004 ר' יוחנן שוב \u0003שמעתתא ואקשי\u0004 \u0005[שמועה והקשה לו\u0006 רב כהנא\u0005].\u0006","ומספרים: \u0003ר' יוחנן הוה יתיב אשבע בסתרקי\u0004 \u0005[היה יושב על שבעה כרים]\u0006 כדי שייראה לכל. \u0003שלפי ליה חדא בסתרקא מתותיה\u0004 \u0005[הורידו לו מצע אחד מתחתיו]\u0006 שמשום שלא יכול היה לענות, הראה שהוא מקטין עצמו בפניו. שוב \u0003אמר\u0004 ר' יוחנן \u0003שמעתתא ואקשי ליה\u0004 \u0005[שמועה והקשה לו\u0006 רב כהנא\u0005],\u0006 \u0003עד דשלפי ליה כולהו בסתרקי מתותיה\u0004 \u0005[שהורידו לו את כל המצעים מתחתיו]\u0006 \u0003עד דיתיב\u0004 \u0005[ש\u0006נשאר \u0005יושב]\u0006 \u0003על ארעא\u0004 \u0005[על הארץ].\u0006 ומספרים: \u0003ר' יוחנן גברא סבא הוה ומסרחי גביניה\u0004 \u0005[אדם זקן היה והיו גביני עיניו יורדים למטה]\u0006 עד שלא היה יכול לראות לפניו היטב, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דלו\u0004 \u0005[הגביהו]\u0006 \u0003לי\u0004 את \u0003עיני ואחזייה\u0004 \u0005[ואראה אותו]\u0006 את האדם הגדול הזה. \u0003דלו ליה במכחלתא דכספא\u0004 \u0005[הרימו לו\u0006 את גביניו \u0005במכחול של כסף].\u0006","\u0003חזא דפרטיה שפוותיה\u0004 \u0005[ראה אותו שהיו שפתיו פרודות,\u0006 פשוקות\u0005]\u0006 כאילו היה מחייך, ולכן \u0003סבר\u0004 ר' יוחנן: \u0003אחוך קמחייך ביה\u0004 \u0005[מחייך\u0006 צוחק הוא \u0005עליו].\u0006 \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו]\u0006 של ר' יוחנן, ועל ידי הקפדתו גרם ש\u0003נח נפשיה\u0004 \u0005[נפטר]\u0006 רב כהנא מפני הקפדה זו. \u0003למחר אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יוחנן לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003חזיתו לבבלאה היכי עביד\u0004 \u0005[ראיתם את הבבלי איך הוא עושה]\u0006 שלא זו בלבד שהקשה עלי אלא גם עמד וצחק בפני! \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דרכיה הכי\u0004 \u0005[כך דרכו],\u0006 כך עשויות פניו שהוא נראה כצוחק, אבל באמת הוא לא צחק. שמע ר' יוחנן והתחרט מאד על מה שגרם, \u0003על לגבי מערתא\u0004 \u0005[נכנס לתוך המערה\u0006 של קבורה\u0005]\u0006 שבה הניחו את רב כהנא, \u0003חזא דהוה\u0004 \u0005[ראה\u0006 אותו \u0005שהיה]\u0006"],["\u0003הדרא ליה עכנא\u0004 \u0005[מסובב על ידי נחש]\u0006 שזנבו בפיו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עכנא, עכנא\u0004 \u0005[נחש, נחש],\u0006 \u0003פתח פומיך\u0004 \u0005[פיך]\u0006 \u0003ויכנס הרב אצל תלמיד, ולא פתח\u0004 הנחש. אמר לנחש: \u0003יכנס חבר אצל חבר, ולא פתח.\u0004 אמר: \u0003יכנס תלמיד אצל הרב,\u0004 ואז \u0003פתח ליה\u0004 \u0005[לו]\u0006 הנחש ונכנס. \u0003בעא רחמי ואוקמיה\u0004 \u0005[ביקש\u0006 ר' יוחנן \u0005רחמים,\u0006 התפלל על רב כהנא \u0005והקימו\u0006 לתחיה\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אי הוה ידענא דדרכיה דמר הכי\u0004 \u0005[אילו ידעתי שדרכו של אדוני כך],\u0006 שכך מראה פניו, \u0003לא חלשא דעתי\u0004 \u0005[היתה נחלשת דעתי],\u0006 \u0003השתא ליתי מר בהדן\u0004 \u0005[עכשיו שיבוא אדוני איתי]\u0006 ויצא מן המערה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי מצית למיבעי רחמי דתו\u0004 \u0005[אם יכול אתה לבקש רחמים\u0006 להתפלל \u0005ששוב]\u0006 \u0003לא שכיבנא\u0004 \u0005[אמות]\u0006 — \u0003אזילנא\u0004 \u0005[אלך\u0006 איתך\u0005],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא אזילנא\u0004 \u0005[אלך].\u0006 ומספרים: \u0003הואיל וחליף שעתא, חליף\u0004 \u0005[ועברה השעה, עברה]\u0006 וכבר קם.","\u0003תייריה, אוקמיה\u0004 \u0005[העיר אותו\u0006 ר' יוחנן, \u0005העמיד אותו]\u0006 \u0003שייליה\u0004 \u0005[שאלו אותו]\u0006 ר' יוחנן \u0003כל ספיקא דהוה ליה ופשטינהו ניהליה\u0004 \u0005[הספיקות שהיו לו ופתר אותם לו].\u0006 ומסכמים: \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003אמר ר' יוחנן\u0004 בכמה מקומות: \u0003דילכון אמרי, דילהון\u0004 \u0005[\u0006מה \u0005שאני אומר שלכם, שלהם,\u0006 של בני בבל\u0005]\u0006 \u0003היא\u0004 שהם הדברים שלמד מרב כהנא באותו זמן.","ועוד בענין מציל עצמו בממון חבירו, מסופר: \u0003ההוא דאחוי אמטכסא\u0004 \u0005[אדם אחד שהראה\u0006 לגוי \u0005על המשי]\u0006 של \u0003ר' אבא,\u0004 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' אבהו ור' חנינא בר פפי ור' יצחק נפחא\u0004 ודנו בדינו של אותו אדם, \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' אילעא גבייהו\u0004 \u0005[אצלם].\u0006","\u0003סבור לחיוביה מהא דתנן\u0004 \u0005[סבורים\u0006 היו \u0005לחייב אותו מזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003דן\u0004 הדיין \u0003את הדין\u0004 וטעה, \u0003זיכה את החייב וחייב את הזכאי, טימא את הטהור וטיהר את הטמא\u0004 — \u0003מה שעשה עשוי\u0004 שפסק הדין הוא פסק, \u0003וישלם\u0004 הדיין את מה שטעה \u0003מביתו,\u0004 כלומר, מממונו, הרי שעל פי דיבור בלבד של הדיין הוא מתחייב לשלם.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אילעא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: והוא שנשא ונתן\u0004 הדיין \u0003ביד.\u0004 אבל אם רק פסק הלכה בדיבור — אינו חייב. כיון שכך היו צריכים לפטור את האיש, \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 לר' אבא: אם ברצונך שישלם לך אותו אדם את נזק המשי שגרם לך, \u0003זיל לגבי\u0004 \u0005[לך אצל]\u0006 \u0003ר' שמעון בן אליקים ור' אלעזר בן פדת, דדייני דינא דגרמי\u0004 \u0005[שהם דנים\u0006 גם \u0005דיני גורמים\u0006 לנזק\u0005]\u0006 ולא רק נזק שעושה בעצמו, ולדעתם גם במקרה כזה משלם המזיק.","\u0003אזל לגבייהו, חייביה ממתניתין\u0004 \u0005[הלך אצלם,\u0006 ו\u0005חייבו\u0006 את האיש ההוא \u0005מ\u0006תוך \u0005משנתנו],\u0006 ששנינו בה: גזל שדה מחבירו וגזלוה ממנו אחרים, \u0003אם מחמת הגזלן\u0004 גזלו אותה, שאינה מכת מדינה — \u0003חייב להעמיד לו שדה אחר, ואוקימנא\u0004 \u0005[והעמדנו,\u0006 הסברנו זאת\u0005]\u0006 במקרה \u0003דאחוי אחוויי\u0004 \u0005[ש\u0006רק \u0005הראה\u0006 את הדבר\u0005]\u0006 למציקים. משמע שיש מקור במשנה שאפילו על גרם כזה של נזק חייב לשלם.","ועוד מסופר: \u0003ההוא גברא דהוה מפקיד ליה כסא דכספא\u0004 \u0005[אדם אחד שהיתה מופקדת בידו כוס כסף].\u0006 \u0003סליקו גנבי עילויה\u0004 \u0005[באו גנבים עליו,\u0006 לביתו\u0005],\u0006 \u0003שקלה יהבה להו\u0004 \u0005[לקח\u0006 את הכוס ו\u0005נתן אותה להם],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רבה, פטריה\u0004 \u0005[\u0006ו\u0005פטר אותו\u0006 את האיש\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 הלא \u0003האי\u0004 \u0005[זה]\u0006 \u0003מציל עצמו בממון חבירו הוא,\u0004 ועליו לשלם לחבירו! \u0003אלא אמר רב אשי:\u0004 בדין זה \u0003חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי איניש אמיד\u0004 \u0005[אם אדם עשיר]\u0006 \u0003הוא\u0004 בעצמו — \u0003אדעתא דידיה אתו\u0004 \u0005[על דעתו שלו באו]\u0006 שממנו באו לגנוב והוא באמת מציל עצמו בממון חבירו, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 עשיר הוא — \u0003אדעתא דכספא אתו\u0004 \u0005[על דעת\u0006 כוס \u0005הכסף\u0006 הזו \u0005באו]\u0006 וכיון שלשם כך באו, נמצא שלא הציל עצמו בממון זה.","ועוד מספרים, \u0003ההוא גברא דהוה מפקיד גביה ארנקא\u0004 \u0005[אדם אחד שהיה מופקד אצלו ארנק]\u0006 של כסף צדקה שהקדישו ל\u0003פדיון שבויים, סליקו גנבי עילויה\u0004 \u0005[באו גנבים עליו\u0006 לביתו\u0005],\u0006 \u0003שקלה יהבה ניהלייהו\u0004 \u0005[לקח\u0006 את הארנק \u0005נתן אותו להם],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רבא, פטריה\u0004 \u0005[\u0006ו\u0005פטר אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003מציל עצמו בממון חבירו הוא! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין לך פדיון שבויים גדול מזה,\u0004 שהרי פדה עצמו מנזקים או ממיתה על ידי הכסף שהופקד לצורך זה.","ועוד מסופר: \u0003ההוא גברא דאקדים ואסיק חמרא למברא, קמי דסליקו אינשי במברא\u0004 \u0005[אדם אחד שהקדים והעלה את חמורו למעבורת, לפני שעלו אנשים במעבורת]\u0006 והחמור השתולל \u0003בעי לאטבועי\u0004 \u0005[רצה להטביע\u0006 את המעבורת\u0005],\u0006 \u0003אתא ההוא גברא מלח ליה לחמרא דההוא גברא ושדייה לנהרא\u0004 \u0005[בא אדם אחד\u0006 ו\u0005דחף אותו, את החמור של האיש ההוא והשליכו לנהר]\u0006 \u0003וטבע\u0004 החמור, \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רבה, פטריה\u0004 \u0005[\u0006ו\u0005פטר אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003מציל עצמו בממון חבירו הוא! אמר ליה\u0004 \u0005[לו]\u0006 \u0003האי\u0004 \u0005[זה]\u0006 אותו אדם שהכניס את החמור \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני שהאנשים עלו \u0003רודף הוה\u0004 \u0005[היה]\u0006 שגרם לסכן את האחרים, ומשום כך מותר היה להם להציל את עצמם בממונו.","\u0003רבה לטעמיה\u0004 ש\u0003אמר רבה: רודף שהיה רודף אחר חבירו להורגו, ו\u0004הרודף הזה \u0003שיבר את הכלים, בין\u0004 ששיבר כליו \u0003של נרדף בין של כל אדם\u0004 — \u0003פטור, שהרי מתחייב בנפשו\u0004 על העבירה שהוא הולך לעשות.","\u0003ונרדף ששיבר את הכלים של רודף\u0004 — \u0003פטור, שלא יהא ממונו\u0004 של הרודף \u0003חביב עליו,\u0004 כלומר, נחשב יותר \u0003מגופו,\u0004 והרי מותר היה להציל את הנרדף אפילו בנפשו של הרודף. \u0003אבל\u0004 אם שיבר הנרדף כלים \u0003של כל אדם\u0004 — \u0003חייב,\u0004 ש\u0003אסור\u0004 לאדם \u0003להציל עצמו בממון חבירו.\u0004","אבל \u0003רודף\u0004 \u0003שהיה רודף אחר רודף\u0004 אחר כדי \u0003להציל\u0004 את הנרדף, \u0003ו\u0004הוא \u0003שבר כלים, בין של נרדף בין של כל אדם\u0004 — \u0003פטור. ולא מן הדין,\u0004 שהרי בעצם מן הדין היה צריך לשלם הכל, \u0003אלא שאם אי\u0004 (אין) \u0003אתה אומר כן,\u0004 והמציל יצטרך לשלם נזקים — \u0003אין לך אדם שמציל את חבירו מן הרודף,\u0004 שהוא מתחיל לחשוש שמא יתחייב על ידי כך בנזקים.","גזל קרקע ו\u0003שטפה נהר, אומר לו\u0004 הגזלן לנגזל: \u0003הרי שלך לפניך,\u0004 אף על פי שעל ידי שטיפת הנהר פחת הרבה ערך הקרקע משוויה בעת הגזילה.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הגוזל שדה מחבירו ושטפה נהר\u0004 — \u0003חייב להעמיד לו שדה אחר\u0004 במקומה, אלו \u0003דברי ר' אלעזר. וחכמים אומרים: אומר לו \"הרי שלך לפניך\".\u0004","ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 מהו העיקרון, הבסיס למחלוקתם? — הרי זה הבדל בדרשת הכתוב \"וכיחש בעמיתו בפקדון או בתשומת יד או בגזל או עשק את עמיתו... או מכל אשר ישבע עליו לשקר\" (ויקרא ה, כא. ויקרא ה כד). \u0003ר' אלעזר דרש ריבויי ומיעוטי\u0004 \u0005[דורש\u0006 את הפסוקים בשיטת \u0005ריבוי ומיעוט]\u0006 כיצד? נאמר: \u0003\"וכחש בעמיתו\"\u0004 — הרי זה \u0003ריבוי,\u0004 בכל אופן שהוא, \u0003\"בפקדון\"\u0004 — \u0003מיעט,\u0004 ונאמר: \u0003\"\u0004מ\u0003כל אשר ישבע עליו לשקר\"\u0004 (ויקרא ה כד) — \u0003חזר וריבה,\u0004 נמצא","ש\u0003ריבה ומיעט וריבה\u0004 — ולפי שיטה זו \u0003ריבה הכל, ומאי רבי\u0004 \u0005[ומה ריבה]?\u0006 — \u0003רבי\u0004 \u0005[ריבה]\u0006 \u0003כל מילי\u0004 \u0005[דבר]\u0006 שגוזל אדם,","\u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט?\u0004 — \u0003מיעט שטרות,\u0004 שלפי שיטת ריבוי ומיעוט וריבוי מוציאים רק את הדבר שהוא רחוק ביותר מן הריבוי שבכתוב, ולפי שיטה זו דין שבועת שקר וגזל חלים גם בקרקע. והואיל ולדעתו יש דין גזל בקרקע — קנה אותה הגזלן, וחייב להשיב לו קרקע תמורתה.","\u0003ו\u0004אילו \u0003רבנן דרשי כללי ופרטי\u0004 \u0005[חכמים דורשים\u0006 בשיטת \u0005כללים ופרטים],\u0006 וכך הם דורשים: \u0003\"וכחש\"\u0004 — \u0003כלל, \"בפקדון\"\u0004 — \u0003פרט, \"או מכל\u0004 אשר ישבע עליו לשקר \u0003\"\u0004— \u0003חזר וכלל,\u0004 נמצא שיש פה \u0003כלל ופרט וכלל,\u0004 ו\u0003אי\u0004 (אין) \u0003אתה דן\u0004 לכלול \u0003אלא\u0004 רק מה שהוא \u0003כעין הפרט.\u0004","ובאופן זה: \u0003מה הפרט\u0004 הוא \u0003דבר המיטלטל וגופו\u0004 (הוא עצמו) \u0003ממון, אף כל דבר המיטלטל וגופו ממון\u0004 חייבים עליו. \u0003יצאו קרקעות שאין מטלטלין, יצאו עבדים שהוקשו\u0004 (הושוו בכתוב) \u0003לקרקעות, יצאו שטרות\u0004 — \u0003שאף על פי ש\u0004הם עצמם \u0003מטלטלין אין גופן ממון,\u0004 אלא הם רק גורמים לממון. ומאחר שאין קרקע בכלל דין גזל — יכול לומר לו הגזלן \"הרי שלך לפניך\".","ושואלים: \u0003והדתניא\u0004 \u0005[ו\u0006ברייתא \u0005זו ששנויה]:\u0006 \u0003הגוזל את הפרה ושטפה נהר\u0004 — \u0003חייב להעמיד לו\u0004 לנגזל \u0003פרה\u0004 אחרת, אלו \u0003דברי ר' אלעזר. וחכמים אומרים: אומר לו \"הרי שלך לפניך\",\u0004 אם כן \u0003התם במאי קמיפלגי\u0004 \u0005[שם במה הם חלוקים]\u0006 שהרי כאן מדובר בפרה שהיא בוודאי דבר המיטלטל שחלים עליו דיני גזילה — והיו צריכים להסכים לדברי ר' אלעזר?","\u0003אמר רב פפא: התם במאי עסקינן\u0004 \u0005[שם במה אנו עוסקים]?\u0006 \u0003כגון שגזל שדה מחבירו והיתה\u0004"],["\u0003פרה רבוצה בו ושטפה נהר,\u0004 ש\u0003ר' אלעזר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שלדעתו כיון שקנה את השדה בגזילתו נקנתה לו אגב השדה גם הפרה, וכיון שהתחייב לשלם עבור הגזילה נתחייב גם על הפרה. \u0003ורבנן לטעמייהו\u0004 \u0005[וחכמים לטעמם,\u0006 לשיטתם\u0005]\u0006 שלדעתם אין לו קנין בשדה, וממילא לא נקנתה לו כלל הפרה שהיתה בשדה, ולכן פטור גם על הפרה.","\u0003הגוזל את חבירו, או שהלוה\u0004 (לווה) \u0003הימנו\u0004 (ממנו), \u0003או שהפקיד לו,\u0004 והיתה הגזילה או ההלוואה או ההפקדה \u0003ב\u0004מקום \u0003ישוב\u0004 — \u0003לא יחזיר לו במדבר,\u0004 במקום שאינו יכול לשומרו ואינו יכול ליהנות ממנו הרבה. אבל אם אמר לו הלווה או מקבל הפקדון \u0003על מנת לצאת במדבר\u0004 — \u0003יחזיר לו\u0004 אפילו \u0003במדבר.\u0004","שנינו במשנה שלא ניתן להחזיר מלוה במדבר, ועל כך \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003מלוה משתלמת בכל מקום,\u0004 ואילו \u0003אבידה ופקדון אין משתלמין אלא במקומן! אמר אביי, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003מלוה ניתנה ליתבע בכל מקום,\u0004 שיכול המלווה לתבוע את הלווה בכל מקום, ולאו דווקא במקום שבו הלווהו, אבל לענין ביצוע התשלום — המלווה יכול לסרב לקבל את החזרת ההלוואה במקום שאינו רוצה. ואילו \u0003אבידה ופקדון לא ניתנו ליתבע אלא במקומן,\u0004 ואינו יכול לתבוע אותם מן המוצא או השומר שלא במקום המציאה או ההפקדה.","שנינו במשנה שאם אמר \u0003\"על מנת לצאת במדבר\"\u0004 — יחזיר לו במדבר. ותוהים על כך: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאם התנה על כך, הכל לפי תנאו, ומה צורך יש לשנות זאת! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להישנות אלא במקרה שלא היה תנאי מפורש שיחזירנו שם, אלא \u0003דאמר ליה\u0004 \u0005[שאומר לו\u0006 המפקיד לשומר\u0005]:\u0006 \u0003ליהוי האי\u0004 \u0005[שיהא זה]\u0006 \u0003פקדון גבך דאנא\u0004 \u0005[אצלך, שאני]\u0006 \u0003למדבר נפיקנא\u0004 \u0005[יוצא],\u0006 \u0003ואמר ליה איהו\u0004 \u0005[לו הוא],\u0006 אותו שומר למפקיד: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003למדבר נמי בעינא למיפק\u0004 \u0005[גם כן רוצה לצאת],\u0006 ולכן \u0003אי בעינא לאהדרינהו\u0004 \u0005[אם ארצה להחזיר]\u0006 \u0003לך, התם מהדרנא\u0004 \u0005[שם אחזיר]\u0006 \u0003לך.\u0004","\u0003האומר לחבירו: \"גזלתיך\",\u0004 או \u0003\"\u0004\u0003הלויתני\",\u0004 או \u0003\"הפקדת אצלי\",\u0004 והוסיף \u0003\"\u0004אבל \u0003איני יודע אם החזרתי לך אם לא החזרתי לך\"\u0004 — \u0003חייב לשלם\u0004 לו. \u0003אבל אם אמר לו: \"איני יודע אם גזלתיך, אם הלויתני, אם הפקדת אצלי\"\u0004 — \u0003פטור מלשלם.\u0004","ומביאים ענין שיש לו ראיה ממשנתנו. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: התובע את חבירו ואומר לו \u0003\"מנה לי בידך\u0004 שאתה חייב לי \u0003\",\u0004 ואין לו ראיה לכך, \u0003והלה אומר \"איני יודע\"\u0004 — \u0003רב הונא ורב יהודה אמרי\u0004 \u0005[אומרים]:\u0006 במקרה כזה \u0003חייב\u0004 הנתבע לשלם, \u0003ו\u0004אילו \u0003רב נחמן ור' יוחנן אמרי\u0004 \u0005[אומרים]:\u0006 \u0003פטור.\u0004","ומסבירים תחילה את השיטות: \u0003רב הונא ורב יהודה אמרי\u0004 \u0005[אומרים]:\u0006 \u0003חייב,\u0004 כי במקרה בו יש טענות \u0003ברי\u0004 (ברור, ודאי) \u0003ושמא\u0004 — \u0003ברי עדיף.\u0004 והרי במקרה זה המלוה טוען טענת ברי, והנתבע אינו טוען אלא טענת שמא. ואילו \u0003רב נחמן ור' יוחנן אמרי\u0004 \u0005[אומרים]:\u0006 \u0003פטור,\u0004 שלדעתם הכלל הקובע כאן הוא: \u0003אוקי ממונא\u0004 \u0005[העמד\u0006 את \u0005הממון]\u0006 \u0003בחזקת מריה\u0004 \u0005[בעליו],\u0006 וכל עוד אין ראיה ביד התובע — ישאר הכסף ברשות המחזיק בו.","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אבל אם אמר לו \"איני יודע אם הלויתני\"\u0004 — \u0003פטור.\u0004 ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דלא קא תבע ליה\u0004 \u0005[אם תאמר\u0006 שמדובר פה במקרה \u0005שאינו תובע אותו],\u0006 אלא מעצמו בא ואומר זאת — \u0003רישא נמי דלא קא תבע ליה\u0004 \u0005[בראש,\u0006 במקרה הראשון שבמשנתנו \u0005גם כן\u0006 צריך לומר שמדובר \u0005שאינו תובע אותו],\u0006 אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 הרי אין האחר תובע אותו! \u0003אלא\u0004 צריך לומר שבמשנה מדובר \u0003דקתבע ליה\u0004 \u0005[ש\u0006הוא \u0005תובע אותו],\u0006 \u0003וקתני סיפא\u0004 \u0005[ושנה בסוף]:\u0006 \u0003פטור מלשלם.\u0004 ואם כן, מי שתבעו חבירו ואמר \"איני יודע\" פטור, והרי זו ראיה לרב נחמן ור' יוחנן וקשה על דעת רב הונא ורב יהודה!","ודוחים: \u0003לא, לעולם\u0004 מדובר במשנה \u0003דלא קא תבע ליה\u0004 \u0005[שאינו תובע אותו],\u0006 \u0003ורישא\u0004 \u0005[ובראש]\u0006 המשנה ששנינו בה שחייב לשלם, מדובר \u0003בבא לצאת ידי שמים,\u0004 שהוא חושש שמא הוא חייב כסף ורוצה לצאת ידי שמים, משום כך צריך הוא לשלם.","ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: האומר לחבירו \"מנה לי בידך\", והלה אומר \"איני יודע\"\u0004 — \u0003חייב, בבא לצאת ידי שמים,\u0004 אבל לא מן הדין.","\u0003הגונב טלה מן העדר והחזירו\u0004 לעדר בלא להודיע לבעלים, \u0003ומת\u0004 הטלה \u0003או נגנב\u0004 מן העדר — \u0003חייב\u0004 הגנב \u0003באחריותו,\u0004 שלא בטלה אחריותו ממנו על ידי השבה זו. אבל אם \u0003לא ידעו\u0004 ה\u0003בעלים לא בגניבתו ולא בחזירתו, ומנו את הצאן ושלימה היא\u0004 במספר, כמו שהיה המספר קודם הגניבה, ואחר כך מת או נגנב הטלה — \u0003פטור.\u0004","ונחלקו חכמים בדין הגנב וכן בפירוש משנתנו. \u0003אמר רב:\u0004 אם לקח הגנב \u0003לדעת,\u0004 שיודעים הבעלים שגנב — \u0003צריך דעת\u0004 הבעלים כשמחזיר כדי לפוטרו. אם לקח \u0003שלא לדעת\u0004 — ה\u0003מנין\u0004 שמנה הבעלים ולא ראה שחסר טלה \u0003פוטר,\u0004 שהדבר נחשב כאילו הטלה הוחזר לבעליו לגמרי. ואם כן, \u0003וכי קתני\u0004 \u0005[וכאשר שנה\u0006 במשנה\u0005]\u0006 \u0003\"ומנו את הצאן והיא שלימה\u0004 פטור \u0003\"\u0004— \u0003אסיפא\u0004 \u0005[על סוף]\u0006 המשנה מדובר, על המקרה שלא ידעו בגניבתו. אך אם ידע שנגנבה — אין המנין פוטר את הגנב מאחריות עד שיודיע לבעלים.","\u0003ושמואל אמר: בין\u0004 שלקח \u0003לדעת בין שלא לדעת\u0004 — \u0003מנין פוטר, וכי קתני\u0004 \u0005[וכאשר שנה]\u0006 \u0003\"ומנו והיא שלימה פטור\"\u0004 — \u0003אכולה\u0004 \u0005[על כל]\u0006 המשנה מדובר, שבכל מקרה אם הבעלים מצאו שהכל נמצא בעדר — הרי הוא פטור.","\u0003ור' יוחנן אומר:\u0004 אם לקח \u0003לדעת\u0004 — \u0003מנין פוטר, שלא לדעת\u0004 — \u0003אפילו מנין נמי\u0004 \u0005[גם כן]\u0006 \u0003לא צריך, וכי קתני\u0004 \u0005[וכאשר שנה]\u0006 \u0003\"ומנו את הצאן והיא שלימה\u0004 פטור \u0003\"\u0004— דבר זה מתייחס רק \u0003ארישא\u0004 \u0005[על ראשה]\u0006 של המשנה, במי שגנב טלה ונודע הדבר לבעלים, שלגבי המקרה שבסוף — אין צורך בדבר.","ואילו \u0003רב חסדא אמר\u0004 להיפך: אם גנבו \u0003לדעת\u0004 — \u0003מנין פוטר,\u0004 ואם לקחו \u0003שלא לדעת\u0004 — \u0003צריך דעת\u0004 הבעלים במפורש, \u0003וכי קתני\u0004 \u0005[וכאשר שנה]\u0006 \u0003\"ומנו את הצאן והיא שלימה\"\u0004 — \u0003ארישא\u0004 \u0005[על\u0006 ההלכה \u0005הראשונה]\u0006 מדובר, ולא על האחרונה, שאין די בכך.","\u0003אמר רבא:\u0004"],["\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב חסדא\u0004 האומר שדווקא אם גנב שלא לדעת צריך דעת הבעלים בהשבה? — \u0003הואיל ואנקטה נגרי ברייתא\u0004 \u0005[ולימד אותה בפסיעות זרות],\u0006 כלומר, שכיון שהוציא את הטלה למקום אחר, לומד הוא ללכת לאותם המקומות, והואיל והבעלים אינם יודעים על כך — יש לחשוש שטלה זה יברח, אבל אם גנב לדעתם — כיון שיודעים שנגנב, ישמרו אותו ביתר שאת. ומדברי רבא יש להבין שהוא סבור כרב חסדא.","ועל כך שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: האי מאן דחזייה לחבריה דאגבה אימרא מעדרא דידיה\u0004 \u0005[מי שראה את חבירו שמגביה טלה מן העדר שלו]\u0006 כדי לגנוב, \u0003ורמא ביה קלא ושדייה\u0004 \u0005[והשליך עליו צרור\u0006 אבן \u0005והשליכו\u0006 הגנב\u0005],\u0006 \u0003ולא ידע\u0004 בעל העדר \u0003אי הדריה אי\u0004 \u0005[אם החזירו, אם]\u0006 \u0003לא הדריה\u0004 \u0005[החזירו],\u0006 והלה החזירו בלא ידיעתו, \u0003ומת או נגנב\u0004 טלה זה לאחר שהוחזר — \u0003חייב\u0004 הגנב \u0003באחריותו.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 חייב באחריותו \u0003אף על גב דמני\u0004 \u0005[אף על פי שמנה]\u0006 את הצאן, והוא שלא כדברי רב חסדא, שהרי לדעתו הגונב לדעת אינו צריך דעת, ומנין פוטר! ודוחים: \u0003לא,\u0004 מדובר שם במקרה ש\u0003לא מני\u0004 \u0005[מנה].\u0006 אבל אם היה מונה — די בכך, ואינו צריך דעת.","ועוד שואלים בבירור השיטות: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]\u0006 שהגונב צריך לכל הפחות מנין כדי להיפטר? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: החזירו לעדר שבמדבר\u0004 — \u0003יצא,\u0004 משמע שאין צריך אפילו מנין! \u0003אמר רב חנן בר אבא: מודה רב ברקועתא\u0004 \u0005[במנומרים],\u0006 שטלה זה ניכר מיד ולכן הוא יודע בהשבתו.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שדבר זה שנוי במחלוקת \u0005תנאים]\u0006 ששנינו: \u0003הגונב טלה מן העדר,\u0004 או מטבע \u0003סלע מן הכיס\u0004 — \u0003למקום שגנב יחזיר\u0004 אף בלא להודיע על כך לבעלים, אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: צריך דעת בעלים.\u0004","\u0003סברוה\u0004 \u0005[סברו\u0006 הלומדים\u0005]\u0006 כהנחה בסיסית \u0003דכולי עלמא אית להו\u0004 \u0005[שלדעת הכל יש להם,\u0006 מחזיקים\u0005]\u0006 בדברי \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: אדם עשוי למשמש בכיסו בכל שעה,\u0004 ויודע כמה יש בו. ואם כן \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שנחלקו \u0003בסלע\u0004 שגנב \u0003לדעת, ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003רב ושמואל,\u0004 שלדעת ר' ישמעאל הואיל וממשמש בכיסו בכל שעה הרי זה מנין הפוטר כדעת שמואל. ואילו לדעת ר' עקיבא אין די בכך וצריך להודיעו, וכדעת רב?","ודוחים: \u0003לא,\u0004 אין מכאן ראיה, כי מדובר \u0003בטלה\u0004 שנגנב \u0003שלא לדעת, ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003רב חסדא ור' יוחנן.\u0004 האם יש צורך בדעת, כיון שהורגל הטלה ללכת למקומות אחרים, וכדברי רב חסדא, וכן סבור ר' עקיבא. או שמא הואיל וגנב שלא לדעת — אף מנין אינו צריך, וכדעת ר' יוחנן, וכך סבור גם ר' ישמעאל.","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: בשומר שגנב\u0004 טלה \u0003מרשות בעלים\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שהלכה \u0003כ\u0004דברי \u0003רב חסדא,\u0004 ואף ר' ישמעאל סבור כמותו. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בשומר שגנב מרשותו\u0004 של עצמו \u0003שיחזיר למקום שגנב קמיפלגי\u0004 \u0005[חלוקים],\u0006 \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003כלתה לו שמירתו,\u0004 כלומר, מכיון שגנב שוב אינו נחשב לשומר, ולכן צריך להחזיר לדעת הבעלים כשאר גנבים. \u0003ור' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003לא כלתה לו שמירתו\u0004, וכיון שהחזיר — מוחזר.","ועוד מציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שהשאלה הזו האם \u0003מנין פוטר\u0004 את הגנב מאחריות \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הגוזל את חבירו\u0004 סכום מסויים \u0003והבליע לו בחשבון\u0004 שבחשבון שהיה ביניהם הוסיף לו הגזלן את הכסף שגזל ממנו — \u0003תני חדא\u0004 \u0005[שנויה\u0006 הלכה בברייתא \u0005אחת]:\u0006 \u0003יצא\u0004 ידי חובת החזרה, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 הלכה בברייתא \u0005אחרת]:\u0006 \u0003לא יצא.\u0004","\u0003סברוה\u0004 \u0005[סברו\u0006 הלומדים\u0005],\u0006 \u0003דכולי עלמא אית להו\u0004 \u0005[שלדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003ר' יצחק,\u0004 ש\u0003אמר: אדם עשוי למשמש בכיסו בכל שעה ושעה,\u0004 ולכן כשהגיע הכסף שוב אליו אנו מניחים שמנאו. אם כן \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה\u0006 הם \u0005חולקים],\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאומר]\u0006 \u0003יצא, סבר\u0004 \u0005[סבור]:\u0006 \u0003מנין\u0004 בלבד \u0003פוטר, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003לא יצא, סבר\u0004 \u0005[סבור]:\u0006 \u0003מנין אינו פוטר?\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 \u0003כר' יצחק, כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003מנין פוטר, אלא ב\u0004דברי \u0003ר' יצחק\u0004 עצמו \u0003קמיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים],\u0006 \u0003מר אית ליה\u0004 \u0005[חכם זה יש לו]\u0006 את דברי \u0003ר' יצחק, ומר לית ליה\u0004 \u0005[וחכם זה אין לו]\u0006 את דברי \u0003ר' יצחק,\u0004 ולכן אין כאן מנין כלל.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003ר' יצחק, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה];\u0006 \u0003הא דמני ורמא ליה בכיסיה\u0004 \u0005[זה שמנה\u0006 הגזלן את הכסף (והבליע) \u0005והניח אותו בכיסו\u0006 של הנגזל\u0005]\u0006 — יצא, מכיון שהלה ממשמש בכיסו. \u0003והא דמני ורמא לידיה\u0004 \u0005[וזה שמנה ושם בידו],\u0006 ולא בדק כמה כסף היה זה, ואינו יכול להסתמך על כך שהנגזל יניח את הכסף בכיסו, וידע שאכן יש בידיו סכום שנגזל ממנו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אידי ואידי דמני ורמא בכיסיה\u0004 \u0005[זה וזה\u0006 מדברים במקרה \u0005שמנה ושם בכיסו],\u0006 אלא \u0003הא דאית ליה זוזי אחריני בכיסיה\u0004 \u0005[זה שיש לו זוזים,\u0006 מטבעות \u0005אחרים בכיסו],\u0006 ולכן אינו יכול להבחין בדיוק שהחזיר לו את הגזילה, \u0003הא דלית ליה זוזי אחריני בכיסיה\u0004 \u0005[\u0006ו\u0005זה שאין לו זוזים,\u0006 מטבעות \u0005אחרים בכיסו]\u0006 שאז יודע שקיבל כסף נוסף על מה שהיה לו.","\u0003אין לוקחין\u0004 (קונים) \u0003מן הרועים,\u0004 שרועים צאן שאינו שלהם, \u0003צמר וחלב וגדיים,\u0004 שיש לחשוש שהם גנובים מן הבעלים, \u0003ו\u0004כן \u0003לא\u0004 קונים \u0003משומרי פירות\u0004 — \u0003עצים ופירות.\u0004","\u0003אבל לוקחין מן הנשים כלי צמר ביהודה, וכלי פשתן בגליל, ועגלים בשרון,\u0004 מכיון שבמקומות אלה עושות הנשים מלאכה בדברים הללו, ומסתבר שעושות כן מדעת הבעלים ואין זו גניבה. \u0003וכולן,\u0004 כל אלה שהתירו לקנות מהם, במקרה \u0003שאמרו\u0004 לקונים מהם \u0003להטמין\u0004 את הדברים שקנו ולא להראותם בגלוי — \u0003אסור\u0004 לקנות, מפני שניכרים הדברים שגניבה היא. \u0003ולוקחין ביצים ותרנגולין מכל מקום,\u0004 ואין חוששים שהם גנובים.","ועוד בענין קניה מן הרועים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לוקחין מן הרועים לא עזים ולא גדיים, ולא גיזין\u0004 (חבילה של צמר גזוז) \u0003ולא תלושין של צמר, אבל לוקחין מהן\u0004 בגדים \u0003תפורין מפני\u0004 שחזקה \u0003שהן שלהן. ולוקחין מהן חלב וגבינה במדבר,\u0004 שמן הסתם נתנו הבעלים רשות לרועים למכור עבורם, שאינם יכולים להביאם בכל עת, \u0003ו\u0004אולם \u0003לא בישוב.\u0004","\u0003ולוקחין מהן ארבע וחמש צאן, ארבע וחמש גיזין\u0004 של צמר, שדבר כזה מן הסתם אין הרועים גונבים משום שהוא ניכר, \u0003אבל לא\u0004 קונים מהם \u0003שתי צאן ולא שתי גיזין.\u0004","\u0003ר' יהודה אומר: בייתות\u0004 (בהמות שחוזרות הביתה) \u0003לוקחין מהן,\u0004 משום שבעל הבית מבחין בחסרונן, ואם אינן של הרועים — לא היו מוכרים. \u0003מדבריות אין לוקחין מהן,\u0004 שהמוכר סומך על כך שהבעלים אינו חש בדבר. \u0003כללו של דבר: כל\u0004 דבר \u0003שהרועה מוכר\u0004 אותו לאחר \u0003ובעל הבית מרגיש בו\u0004 בחסרונו — \u0003לוקחין מהן,\u0004 דבר ש\u0003אין מרגיש בו\u0004 בעל הבית — \u0003אין לוקחין מהן.\u0004","ומעתה דנים בברייתא זו, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003לוקחין מהן ארבע וחמש צאן, ארבע וחמש גיזין.\u0004 ותוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003יש לומר ארבעה זבנינן\u0004 \u0005[קונים אנו\u0006 מהם\u0005],\u0006 \u0003חמשה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 \u0003אמר רב חסדא:\u0004 הכוונה היא \u0003ארבעה מתוך חמשה\u0004 צאן שהפקיד בעל הצאן בידו, שניכר הדבר. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים],\u0006 ש\u0003אמר רב חסדא\u0004 תירוץ אחר: \u0003ארבעה מעדר קטן, וחמש מעדר גדול.\u0004","ועוד שואלים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה,\u0006 ברייתא זו, \u0005קשה\u0006 מעצמה\u0005],\u0006 \u0003אמרת: ארבע וחמש צאן, ארבע וחמש גיזין,\u0004 ונדייק מכאן: \u0003ארבע וחמש\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל שלש\u0004 — \u0003לא. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003אבל לא שתי צאן.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שלש זבנינן\u0004 \u0005[קונים אנו]!\u0006","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא בברייתא\u0004 \u0005[זה בבריאות]\u0006 שבעל הבית מחשיב אותן ושם לב אליהן, ואז גם שלוש יכול לקנות, שוודאי אם היה גונבן היה בעל הבית מבחין בחסרונן, \u0003הא בכחישתא\u0004 \u0005[זה בכחושות]\u0006 שכיון שאינן חשובות בעיניו אינו מבחין בחסרונן, ופחות מארבע אינו רשאי לקנות.","שנינו בברייתא ש\u0003ר' יהודה אומר: בייתות לוקחין מהן, מדבריות אין לוקחין מהן כו'. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 פירוש דברי יהודה, האם \u0003ר' יהודה ארישא קאי ולחומרא\u0004 \u0005[על ראשה\u0006 של ההלכה הוא \u0005עומד,\u0006 מתייחס \u0005ו\u0006בא \u0005להחמיר]\u0006 לומר שבכל מקרה אין קונים מהם מדבריות אפילו בכמות גדולה, \u0003או דלמא אסיפא קאי ולקולא\u0004 \u0005[שמא על סופה\u0006 הוא \u0005עומד,\u0006 מתייחס \u0005ו\u0006בא \u0005להקל]?\u0006","ומפרטים: \u0003ארישא קאי ולחומרא\u0004 \u0005[על ראשה\u0006 הוא \u0005מתייחס ולהחמיר],\u0006 ובאופן זה תובן הברייתא, ש\u0003אמר\u0004 החכם הראשון: \u0003לוקחין מהן ארבעה וחמשה צאן,\u0004 ועל כך אמר ר' יהודה: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003בייתות, אבל מדבריות\u0004 — \u0003אפילו ארבעה וחמשה לא\u0004 יקח. \u0003או דלמא אסיפא קאי ולקולא\u0004 \u0005[שמא על סופה\u0006 הוא \u0005מתייחס ולהקל],\u0006 ובאופן זה תובן הברייתא, ש\u0003אמר\u0004 החכם הראשון: \u0003אבל לא שתי צאן ולא שתי גיזין,\u0004 ואמר ר' יהודה: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003מדבריות, אבל בייתות\u0004 — \u0003שתים נמי\u0004 \u0005[גם כן]\u0006 \u0003לוקחין?\u0004","ומתרצים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו מזה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 במפורש, \u0003ר' יהודה אומר: לוקחין בייתות מהן ואין לוקחין מהן מדבריות, ובכל מקום לוקחין מהן ארבעה וחמשה צאן.\u0004"],["\u0003מדאמר\u0004 \u0005[מ\u0006תוך \u0005שאומר]\u0006 \u0003\"בכל מקום\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אסיפא קאי ולקולא\u0004 \u0005[על סופה של ההלכה\u0006 הוא \u0005מתייחס ו\u0006בא \u0005להקל],\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003ולא\u0004 לוקחים \u0003משומרי פירות\u0004 עצים ופירות. מסופר: \u0003רב זבין שבישתא מאריסא\u0004 \u0005[קנה ענפי גפנים מאריס].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 בשאלה: \u0003והא תנן\u0004 \u0005[והרי שנינו]\u0006 במשנתנו: \u0003ולא\u0004 לוקחים \u0003משומרי פירות עצים ופירות! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003בשומר, דלית ליה בגופא דארעא מידי\u0004 \u0005[שאין לו בגוף הקרקע דבר]\u0006 ולכן אין לו זכות למכור דבר מן הגן, \u0003אבל אריס דאית ליה בגוויה\u0004 \u0005[שיש לו בהם\u0006 חלק\u0005],\u0006 \u0003אימא מדנפשיה קא מזבין\u0004 \u0005[אמור משל עצמו הוא מוכר]\u0006 ואין לחשוד בו שמא הוא גונב.","ועוד בדין קניה משומרי פירות \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שומרי פירות, לוקחין מהן\u0004 פירות \u0003כשהן יושבין ומוכרין\u0004 בקביעות \u0003והסלין לפניהם, וטורטני\u0004 (מאזניים) \u0003לפניהם, וכולן שאמרו\u0004 לקונה \u0003\"הטמן\u0004 את הדבר שקנית ואל תראהו בגלוי \u0003\"\u0004— \u0003אסור. לוקחין מהן מפתח הגינה, אבל לא מאחורי הגינה,\u0004 שהוא כמקום נסתר, ומסתבר שאינו רוצה שיראו אותו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בשאלה הבאה: \u0003גזלן, מאימת מותר לקנות הימנו\u0004 דבר, ולא לחשוש שהוא מוכר לו מן הגזל? \u0003רב אמר: עד שתהא רוב משלו\u0004 של היתר, ולא גזול. \u0003ושמואל אמר: אפילו\u0004 היה \u0003מיעוט שלו\u0004 אין צורך לחשוש.","ומסכמים: \u0003אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003רב יהודה לאדא דיילא\u0004 \u0005[השמש]\u0006 למעשה \u0003כדברי האומר\u0004 ש\u0003אפילו\u0004 רק ה\u0003מיעוט שלו\u0004 אין צורך לחשוש.","ועוד נחלקו ביחס ל\u0003ממון\u0004 של \u0003מסור\u0004 (מלשין, מוסר ממון חבירו לגויים), \u0003רב הונא ורב יהודה, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מותר לאבדו ביד, וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר: אסור לאבדו ביד.\u0004","ומסבירים את שיטותיהם: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מותר לאבדו ביד,\u0004 טעמו, שאנו אומרים: \u0003לא יהא ממונו חמור מגופו,\u0004 והרי אנו יודעים שהמלשינים הם בגדר של אלה שמותר אף להרוג אותם, כדין רודף, ואם כן בוודאי שגם את ממונם מותר לאבד. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 ש\u0003אסור לאבדו\u0004 ביד את ממונו של המסור, \u0003דלמא הוה ליה זרעא מעליא\u0004 \u0005[שמא יהיו לו זרע\u0006 צאצאים \u0005מעולה]\u0006 ואותם ילדים כשרים יירשו את הכסף ממנו, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"יכין (רשע) וצדיק ילבש\"\u0004 (איוב כז, יז).","מסופר: \u0003רב חסדא הוה ליה ההוא אריסא דהוה תקיל ויהיב תקיל ושקיל\u0004 \u0005[היה לו אריס אחד שהיה שוקל ונותן\u0006 ו\u0005שוקל ולוקח\u0006 ממנו\u0005],\u0006 שהיה מדקדק ביותר בחלוקת הרווחים, \u0003סלקיה\u0004 \u0005[סילק אותו]\u0006 רב חסדא מאריסותו, \u0003קרא אנפשיה\u0004 \u0005[קרא על עצמו]:\u0006 \u0003\"וצפון לצדיק חיל\u0004 (רכוש) \u0003חוטא\"\u0004 (משלי יג, כב).","אגב כך מביאים את הכתוב: \u0003\"כי מה תקות חנף כי יבצע\u0004 (יגזול) \u0003כי ישל\u0004 (יטול) \u0003אלוה נפשו\"\u0004 (איוב כז, ח), שעל ידי הגזל מאבד ונוטל הקדוש ברוך הוא נפש אדם. \u0003רב הונא ורב חסדא\u0004 נחלקו בפירוש הפסוק, \u0003חד\u0004 \u0005[אחד]\u0006 \u0003אמר:\u0004 הכוונה היא \u0003נפשו\u0004 של ה\u0003נגזל, וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר:\u0004 הכוונה היא \u0003נפשו של\u0004 ה\u0003גזלן.\u0004","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003נפשו של נגזל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כן ארחות כל בצע בצע את נפש בעליו יקח\"\u0004 (משלי א, יט), לומר שהגוזל ממונו של אדם כאילו גזל את נפשו. \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003נפשו של גזלן\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אל תגזל דל כי דל הוא ואל תדכא עני בשער, כי ה' יריב ריבם וקבע את קבעיהם\u0004 (גוזליהם) \u0003נפש\"\u0004 (משלי כב, כב–כג).","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"נפש בעליו יקח\"!\u0004 ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"בעליו\"?\u0004 אין הכוונה לבעליו הראשונים אלא \u0003בעליו דהשתא\u0004 \u0005[של עכשיו],\u0006 כלומר, הכוונה היא יקח את נפשו של הגזלן.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 כיצד הוא מפרש נפשו של נגזל? \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"וקבע את קבעיהם נפש\"!\u0004 ומסבירים: בלשון \u0003\"מה טעם\" קאמר\u0004 \u0005[\u0006הכתוב \u0005אומר]\u0006 ובאופן זה: \u0003מה טעם \"וקבע את קבעיהם\"? משום דקבעי\u0004 \u0005[ש\u0006הם \u0005קובעים,\u0006 גוזלים\u0005]\u0006 \u0003נפש.\u0004","וכעין זה \u0003אמר ר' יוחנן: כל הגוזל את חבירו שוה פרוטה\u0004 — \u0003כאילו נוטל\u0004 את \u0003נשמתו ממנו, שנאמר: \"כן ארחות כל בוצע בצע את נפש בעליו יקח\", ואומר: \"ואכל קצירך ולחמך\u0004 יאכלו \u0003בניך ובנותיך\"\u0004 (ירמיה ה, יז) שכאשר אוכל את הקציר הרי זה כאילו הורג נפשות הילדים.","\u0003ואומר: \"מחמס בני יהודה אשר שפכו דם נקיא בארצם\"\u0004 (יואל ד, יט), שעל ידי החמס (שהוא גזל ממון) כאילו שפכו דם. \u0003ואומר:\u0004 \u0003\"\u0004ויהי רעב בימי דוד שלוש שנים... \u0003אל שאול ואל בית הדמים על אשר המית את הגבענים\"\u0004 (שמואל ב כא, א).","ומסבירים את הדרשה: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"\u0004\u0003ואומר\"?\u0004 מדוע היה צריך להביא ראיות מפסוקים נוספים? — כך צריך להבין: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי מן הפסוק הראשון \"את נפש בעליו יקח\" אנו למדים שכאילו נוטל \u0003נפש דידיה\u0004 \u0005[הנפש שלו]\u0006 של הנגזל עצמו, \u0003אבל נפש בניו ובנותיו לא,\u0004 על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מן הכתוב הבא: \u0003\"בשר בניו ובנותיו\",\u0004 שאף בנטילת נפשם הדבר.","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003הני מילי היכא דלא יהיב דמי\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום שאינו נותן כסף]\u0006 כלל, אלא גוזל ממש, \u0003אבל היכא דיהיב דמי\u0004 \u0005[במקום שנותן כסף]\u0006 \u0003לא\u0004 נחשב הדבר לנטילת נפש, על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003\"מחמס בני יהודה אשר שפכו דם נקי בארצם\".\u0004 שהחמס, שמוגדר כלקיחת דבר שלא ברצון בעליו אף על פי שמשלם לו — נחשב כשפיכת דם נקי.","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003הני מילי היכא דקעביד\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום ש\u0006הוא \u0005עושה]\u0006 את הדבר \u0003בידים,\u0004 \u0003אבל גרמא\u0004 \u0005[כשגורם\u0006 לכך\u0005]\u0006 בלבד \u0003לא,\u0004 על כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 את דברי הכתוב \u0003\"אל שאול ואל בית הדמים על אשר המית את הגבענים\",\u0004 ופירוש הענין: \u0003וכי היכן מצינו\u0004 (מצאנו) \u0003שהרג שאול את הגבעונים? אלא מתוך שהרג נוב עיר הכהנים שהיו\u0004 הגבעונים \u0003מספיקין\u0004 (מספקים) \u0003להן מים ומזון,\u0004 ועל ידי כך קיפח את פרנסתם \u0003מעלה\u0004 (מחשיב) \u0003עליו הכתוב כאילו הרגן.\u0004","שנינו במשנה: \u0003אבל לוקחין מן הנשים\u0004 כלי צמר ביהודה וכלי פשתן בגליל ועגלים בשרון. ומביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003לוקחין מן הנשים כלי צמר ביהודה וכלי פשתן בגליל, אבל לא יינות ושמנים וסלתות,\u0004 שאין הנשים מצויות למוכרם. \u0003ולא\u0004 קונים כלל \u0003מן העבדים, ולא מן התינוקות. אבא שאול אומר: מוכרת אשה ב\u0004כדי \u0003ארבעה וחמשה דינר, כדי לעשות כפה\u0004 (כיסוי) \u0003לראשה\u0004 כלומר, שבעלה מרשה לה לעבוד מעט ולמכור מעט כדי לקנות לעצמה בגדים נוספים. \u0003וכולן שאמרו\u0004 לקונה \u0003להטמין\u0004 את הדבר שקנה מהם ולא להראותו בגלוי — \u0003אסור\u0004 לקנותו מהם.","\u0003גבאי צדקה לוקחין מהן\u0004 (מנשים וקטנים) \u0003דבר מועט, אבל לא דבר מרובה,\u0004 שיש לחשוש שהם נותנים ממון גנוב, שאינו שלהם.","\u0003והבדדין\u0004 (העובדים בסחיטת השמן בבית הבד) — אנשים \u0003לוקחין מהן זתים במידה, ושמן במידה\u0004 גדולה, שהיא נעשית בפרסום. \u0003אבל לא זיתים במועט ושמן במועט\u0004 בכמות קטנה. \u0003רבן שמעון בן גמליאל אומר: לוקחין מנשים זיתים במועד בגליל העליון,\u0004 שהשמן יקר שם, \u0003שפעמים אדם\u0004 הנזקק לכסף \u0003בוש למכור על פתח ביתו, ונותן לאשתו ומוכרת\u0004 כמות קטנה.","מסופר: \u0003רבינא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבי מחוזא, אתו נשי דבי מחוזא רמו קמיה כבלי ושירי, קביל מינייהו\u0004 \u0005[באו נשי מחוזא\u0006 ו\u0005השליכו לפניו\u0006 לצדקה \u0005שרשראות וצמידים,\u0006 ו\u0005קיבל מהם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה תוספאה לרבינא, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גבאי צדקה מקבלין מהן דבר מועט, אבל לא דבר מרובה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני\u0004 \u0005[אלה]\u0006 \u0003לבני מחוזא דבר מועט נינהו\u0004 \u0005[הם],\u0006 שמשום שהיו עשירים — דברים אלה אינם נחשבים להם כמתנה מרובה.","\u0003מוכין\u0004 (מעין חתיכות צמר קטנות) \u0003שהכובס מוציא\u0004 מהבגד תוך כדי כיבוסו — \u0003הרי אלו שלו, ו\u0004חוטים ש\u0003הסורק מוציא\u0004 — \u0003הרי אלו של בעל הבית. כובס נוטל שלשה חוטין\u0004 שעל שפת הבגד, שנועדו רק לשמירה \u0003והן שלו, יתר מכן\u0004 משלושה חוטים אלו — \u0003הרי אלו של בעל הבית, אם היה\u0004 חוטים אלה שעל שפת הבגד של צבע \u0003שחור על גבי\u0004 בגד בצבע \u0003הלבן \u0004 — \u0003נוטל את הכל והן שלו,\u0004 שוודאי אין בעל הבית רוצה בהם.","\u0003החייט ששייר\u0004 בסוף עבודתו \u0003את החוט\u0004 והיה ארוך \u0003כדי לתפור בו, ו\u0004כן אם שייר \u0003מטלית שהיא\u0004 בגודל \u0003שלש\u0004 אצבעות \u0003על שלש\u0004 אצבעות — \u0003הרי אלו של בעל הבית,\u0004 ואין אומרים שהוא ויתר בזה לחייט. \u0003מה שהחרש\u0004 (נגר) \u0003מוציא במעצד\u0004 (איזמל דק) — \u0003הרי\u0004 השיירים ה\u0003אלו שלו, ו\u0004מה שהוא מוציא \u0003בכשיל\u0004 (כלי חיתוך גדול) — הריהו \u0003של בעל הבית, ואם היה עושה\u0004 (עובד) \u0003אצל בעל הבית\u0004 — \u0003אף הנסרים\u0004 (הנסורת) \u0003של בעל הבית.\u0004","ועוד בענין הכובס במוכין \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003לוקחין\u0004 (קונים) \u0003מוכין מן הכובס\u0004 ואין חוששים שגזולים הם מבגדים שכיבס לאחרים, \u0003מפני שהן שלו,\u0004 כמבואר במשנה. \u0003הכובס נוטל שני חוטין העליונים\u0004 מן הבגד \u0003והן שלו.\u0004"],["\u0003ולא יטיל בו יותר משלשה חובין\u0004 (לולאות) ששמים בו כדי לתלותו ולמתוח אותו, שריבוי לולאות יביא לעשיית נקבים יתרים ולמתיחה מרובה. \u0003ולא יסרוק הבגד לשתיו\u0004 (לאורכו) \u0003אלא לערבו\u0004 (לרוחבו). \u0003ומשויהו,\u0004 כלומר, כשמיישר אותו על ידי גזירה, עושה זאת \u0003לארכו אבל לא לרחבו, ואם בא להשוותו עד טפח\u0004 — \u0003רשאי\u0004 לגזור.","ודנים בפרטי הברייתא, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: הכובס נוטל \u0003שני חוטין.\u0004 ומקשים על כך: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שלש!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שנוטל שנים בלבד הרי זה מדובר \u0003באלימי\u0004 \u0005[ב\u0006חוטים \u0005עבים],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 ששנינו שנוטל שלושה מדובר \u0003בקטיני\u0004 \u0005[ב\u0006חוטים \u0005דקים].\u0006","עוד שנינו בברייתא: \u0003ולא יסרוק הבגד לשתיו אלא לערבו\u0004 שלא יישחת על ידי כך\u0003.\u0004 ושואלים: \u0003והתניא איפכא\u0004 \u0005[והרי שנינו\u0006 בבריייתא בדיוק \u0005להיפך]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא בגלימא\u0004 \u0005[זה בגלימה]\u0006 יש לסורקה לערב ולא לשתי, \u0003הא בסרבלא\u0004 \u0005[זה בסרבל]\u0006 שהוא בגד עליון העשוי לנוי, שכיון שעשוי לנוי עדיף לסרוק אותו לשתי ולא לערב.","ועוד שנינו בברייתא: \u0003ולא יטיל בו יותר משלשה חובין.\u0004 ובפירוש הדברים \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 איך מחשבים אותם, האם \u0003אמטויי ואתויי חד\u0004 \u0005[להוליך ולהביא\u0006 נחשב ל\u0005אחד],\u0006 שמה שחוזר ותופר באותו מקום לשם חיזוק נחשב כתפר אחד. \u0003או דלמא אמטויי ואתויי תרי\u0004 \u0005[שמא להוליך ולהביא\u0006 נחשב ל\u0005שנים]?\u0006 שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו בברייתא גם: \u0003ומשויהו\u0004 את הבגד \u0003לארכו אבל לא לרחבו.\u0004 ומקשים שוב: \u0003והתניא איפכא\u0004 \u0005[והרי שנינו\u0006 בברייתא בדיוק \u0005להיפך]\u0006 שמשווהו דווקא לרוחבו! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא בגלימא\u0004 \u0005[זה בגלימה]\u0006 משווה לאורכה, \u0003הא בהמיוני\u0004 \u0005[זה בחגורה]\u0006 משווה לרוחבה משום שהוא הצד הנראה ולא אורכה. ובענין זכות הסורק במוכין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לוקחין\u0004 (קונים) \u0003מן הסורק מוכין, מפני שאינו שלו,\u0004 שכן שנינו במשנתנו שהם של בעל הבית. \u0003ובמקום שנהגו להיות שלו\u0004 — \u0003לוקחין. ובכל מקום לוקחין מהן כר מלא מוכין וכסת מלאה מוכין.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — אפילו אם גנבם \u0003קננהו\u0004 \u0005[קנה אותם]\u0006 \u0003בשינוי\u0004 על ידי שעשה מהם כלי. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לוקחין מגרדי\u0004 (אורג) \u0003לא אירין\u0004 (צמר המונח בקנה הערב) \u0003ולא נירין\u0004 (קצות החוטים הקשורים בקנה השתי), \u0003ולא פונקלין\u0004 (קצות החוטים הקשורים בקנה הערב), \u0003ולא שיורי פקיעות\u0004 של חוטים, שיש לחשוש שאינם משלו אלא גנבם מבעל הבית.","","","\u0003אבל לוקחין מהן בגד\u0004 שלם אפילו שהיה \u0003מנומר,\u0004 שנראה כאילו החוטים שבו במקומות שונים. וכן לוקחים מהם \u0003ערב ושתי,\u0004 צמר \u0003טווי ואריג,\u0004 שכל אלו נעשה בהם שינוי וקנאם בכך.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אמרת ש\u0003טווי שקלי\u0004 \u0005[לוקחים\u0006 מהם\u0005],\u0006 \u0003ארוג מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006 ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אריג\"?\u0004 — אין הכוונה לאריג ממש אלא \u0003תיכי\u0004 \u0005[\u0006כעין \u0005שרשרות]\u0006 שלא היו טוויות קודם לכן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לוקחין מן הצבע\u0004 (העוסק בצביעת אריגים) \u0003לא אותות ולא דוגמות\u0004 (פיסות קטנות של אריג להראות בהן צבעים) \u0003ולא תלושים של צמר, אבל לוקחין מהן בגד צבוע,\u0004 צמר \u0003טווי,\u0004 ו\u0003בגדים.\u0004 ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003טווי שקיל\u0004 \u0005[\u0006הוא \u0005לוקח],\u0006 \u0003בגדים מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהוא לוקח? ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"בגדים\"?\u0004 — \u0003נמטי\u0004 \u0005[\u0006בגדי \u0005לבד]\u0006 שאין טווים אותם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנותן עורות לעבדן\u0004 (מעבד עורות), \u0003הקיצועין\u0004 (חתיכות קטנות, שאריות העור לאחר חיתוכו) \u0003והתלושין\u0004 של צמר שהיה על גבי העור — \u0003הרי אלו של בעל הבית, ו\u0004אילו דבר \u0003העולה ומשטף\u0004 (ונשטף) \u0003במים\u0004 השוטפים את העור — \u0003הרי אלו שלו.\u0004","","","שנינו במשנה: \u0003אם היה\u0004 החוט בצבע \u0003שחור\u0004 על גבי בגד לבן — מותר לכובס לקחתו. \u0003אמר רב יהודה\u0004 בדרך של לשון נופל על לשון: \u0003קצרא\u0004 הוא \u0003שמיה\u0004 \u0005[שמו]\u0006 בארמית של הכובס, \u0003וקצרא שקיל ליה\u0004 \u0005[ו\u0006את \u0005הקיצורים\u0006 שמקצר מן הבגד הוא \u0005לוקח לו].\u0006 \u0003אמר רב יהודה: הכל עולין למנין תכלת,\u0004 שחוטים אלה שהם בשולי הבגד נחשבים כחלק ממנו לענין הרחקת נקב הציצית מקצה הבגד. \u0003ויצחק ברי קפיד עלייהו\u0004 \u0005[בני מקפיד עליהם]\u0006 ליטול אותם.","","שנינו במשנה: \u0003החייט ששייר את החוט\u0004 כדי לתפור, צריך להחזירו לבעל הבית. ושואלים: \u0003וכמה\u0004 הוא שיעור זה כדי \u0003לתפור? אמר רב אסי:\u0004 חוט שארכו כ\u0003מלא\u0004 אורך ה\u0003מחט חוץ למחט.\u0004 ומסופר: \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו בביאור דברי רב אסי: האם נתכוון לומר \u0003מלא מחט וחוץ למחט כמלא מחט,\u0004 כלומר, פעמיים כגודל המחט, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מלא מחט וחוץ למחט משהו?\u0004 ומציעים פתרון: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003החייט ששייר את החוט פחות מכדי לתפור בו, ומטלית שהיא פחותה משלש על שלש, בזמן שבעל הבית מקפיד עליהן\u0004 — \u0003הרי אלו של בעל הבית.\u0004 ואם \u0003אין בעל הבית מקפיד עליהן\u0004 — \u0003הרי אלו שלו.\u0004","ומעתה: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 \u0003מלא מחט וחוץ למחט\u0004 גם כן צריך להיות \u0003כמלא\u0004 אורך ה\u0003מחט,\u0004 אז גם \u0003פחות מכאן חזי לסיכתא\u0004 \u0005[ראוי\u0006 הדבר \u0005ללולאה]\u0006 ויש לומר שבעל הבית מקפיד בו. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כי אורך החוט צריך להיות כ\u0003מלא מחט וחוץ למחט משהו,\u0004 אם כן \u0003פחות מכאן למאי חזי\u0004 \u0005[למה\u0006 הוא \u0005ראוי]?\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 שהכוונה היתה \u0003מלא מחט וחוץ למחט כמלא\u0004 אורך ה\u0003מחט.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","","שנינו במשנה: \u0003מה שהחרש\u0004 מוציא במעצד הרי הוא שלו. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על כך ממה ששנינו בברייתא: \u0003מה שהחרש מוציא במעצד, והנפסק\u0004 (הנחתך) \u0003במגירה\u0004 (מסור) — \u0003הרי אלו של בעל הבית.\u0004 אבל \u0003היוצא מתחת\u0004 ה\u0003מקדח ומתחת\u0004 ה\u0003רהיטני\u0004 \u0005[מקצוע],\u0006 \u0003והנגרר במגירה,\u0004 אותה הנסורת שיוצאת מעצם הניסור במסור — \u0003הרי אלו שלו!\u0004","\u0003אמר רבא:\u0004 אין זו סתירה, \u0003באתרא\u0004 \u0005[במקומו]\u0006 של ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003איכא תרתי חציני\u0004 \u0005[יש שני\u0006 סוגי \u0005איזמלים],\u0006 \u0003לרבתי קרי לה\u0004 \u0005[לגדול קוראים לו]\u0006 \u0003\"כשיל\",\u0004 \u0003ולזוטרתי קרי לה\u0004 \u0005[ולקטן קוראים לו]\u0006 \u0003\"מעצד\",\u0004 ואילו \u0003באתרא\u0004 \u0005[במקומו]\u0006 של ה\u0003תנא ברא\u0004 \u0005[של הברייתא]\u0006 רק מין כלי \u0003חד\u0004 \u0005[אחד]\u0006 \u0003הוא דאיכא\u0004 \u0005[שיש],\u0006 \u0003וקרו לה\u0004 \u0005[וקוראים לו]\u0006 \u0003\"מעצד\",\u0004 ולכן נתכוון לכלי גדול ולא לכלי קטן.","שנינו במשנה: \u0003ואם היה\u0004 הנגר \u0003עושה\u0004 (עובד) \u0003אצל\u0004 בעל הבית — כל הנסורת של בעל הבית. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מסתתי אבנים\u0004 — \u0003אין בהם משום גזל\u0004 בעל הבית אם לוקחים לעצמם את הפסולת. \u0003מפסגי אילנות\u0004 שחותכים מקצת מענפי האילנות להיטיב את גידולם, וכן \u0003מפסגי גפנים, מנקפי\u0004 (קוצצי) \u0003היגי\u0004 (קוצים), \u0003מנכשי זרעים ועודרי ירקות, בזמן שבעל הבית מקפיד עליהם\u0004 שלא יקחו שום דבר ממה שחתכו או עקרו — \u0003יש בהן משום גזל.\u0004 ואם \u0003אין בעל הבית מקפיד עליהן\u0004 על כל מה שחתכו — \u0003הרי אלו שלו\u0004 של הפועל. \u0003אמר רב יהודה: כשות ו\u0004כן \u0003חזיז\u0004 (שיבלים בעודן צעירות מאד וראויות רק לשחת) — \u0003אין בהם משום גזל,\u0004 משום שהם גדלים מעצמם ואין מטפלים בהם. ואולם \u0003באתרא דקפדי\u0004 \u0005[במקום שמקפידים]\u0006 על כך — \u0003יש בהן משום גזל. אמר רבינא: ומתא מחסיא\u0004 — \u0003אתרא דקפדי\u0004 \u0005[מקום שמקפידים]\u0006 \u0003הוא\u0004 ולכן צריך הפועל להיזהר ולא ליטול אותם.","",""]]};
